--[[
	Midnight Helper — Midnight Codex (handbook) strings.

	SEVEN packs are merged here, in this order: enUS, itIT, nlNL, deDE, frFR, esES,
	ptBR. The header used to say "enUS + nlNL; the rest falls back" — that was true
	once and stopped being true without anyone updating it. Anything missing from a
	pack does still fall back to enUS via ns:L(), so a gap shows English, never a
	raw key.

	Article structure and ids live in Modules/MidnightCodexData.lua.
	Read docs/CODEX_ARCHITECTURE.md before writing anything that generates these.
]]

local _, ns = ...

local function merge(target, patch)
	if not target or not patch then
		return
	end
	for k, v in pairs(patch) do
		target[k] = v
	end
end

merge(ns._mhLocales and ns._mhLocales.enUS, {
	TAB_CODEX = "Midnight Codex",
	CODEX_PANEL_TITLE = "Midnight Codex",
	CODEX_PANEL_INTRO = "Your Midnight handbook — what each system is, what currency does what, and where to click in this addon. Hover currency icons for Blizzard tooltips.",
	CODEX_OPEN_TAB_FMT = "Open: %s",
	CODEX_NAV_DELVES_VAULT = "Delves & Vault tab (Great Vault block)",
	CODEX_NAV_DELVES_MIDNIGHT = "Delves & Vault tab (delve list)",
	CODEX_NAV_BASICS_DAWN = "Basics category (Crests)",
	CODEX_NAV_BASICS_PROF = "Basics tab (Professions guide)",
	CODEX_BALANCE_FMT = "You have: |cffffffff%d|r",
	CODEX_BALANCE_UNKNOWN = "Balance updates when you log in on this character.",
	CODEX_SEARCH_OPENED = "Opened Midnight Codex.",
	CODEX_BETA_DISABLED = "Midnight Codex is disabled in Settings (beta tabs).",

	CODEX_CAT_START = "Start Here",
	CODEX_CAT_WEEKLY = "Weekly loop",
	CODEX_CAT_CURRENCIES = "Currencies",
	CODEX_CAT_DELVES = "Delves",
	CODEX_CAT_DUNGEONS = "Dungeons & M+",
	CODEX_CAT_RAID = "Raid & crests",
	-- ⚠️ Was "Void & Rituals" until 19 aug, and half of what sits under it is neither.
	-- The category holds Prey hunts, rares, Turbulent Timeways and Showdowns alongside
	-- the void and ritual articles. Rob went looking for Prey, read that button, and
	-- walked straight past it — the same class of fault as the twelve type-only commands
	-- on 18 aug: the feature was there, under a name nobody would guess.
	CODEX_CAT_WORLD = "World content",
	CODEX_CAT_COILEDISLE = "Coiled Isle",
	CODEX_ROUTE_BTN = "Follow the route",
	CODEX_CAT_PROFESSIONS = "Professions",

	CODEX_START_TITLE = "Start Here — your Midnight week",
	CODEX_START_BODY = "|cffffcc00Think in layers:|r one weekly reset, several reward tracks. You do not need every system every day — pick a goal.|n|n|cffffff781) Account & reset|r|n• Check the |cffffffffThis Week|r tab for vault ready, world boss, keys, and chores.|n• |cffffffffAccount snapshot|r shows all alts (vault, Delver's Call, profession weeklies).|n|n|cffffff782) Combat content|r|n• |cffffffffDelves|r — main gearing track (keys, tiers, Great Vault slots). Use |cffffffffDelve Coach|r for tips per delve.|n• |cffffffffMythic+|r and |cffffffffRaid|r fill other Great Vault slots (see Dungeons & Raid categories).|n|n|cffffff783) Open world|r|n• |cffffffffCoiled Isle|r — the Season 2 zone from patch 12.1, with its own category here.|n• |cffffffffPrey|r hunts count for the same Great Vault row as delves.|n• |cffffffffVoid & Rituals|r tab — Field Accolades, Ritual Sites, Void Assaults (same renown track).|n• |cffffffffRares|r tab — weekly rare loot and routes.|n|n|cffffff784) Crafting|r|n• |cffffffffProfessions|r tab for KP / weekly mats; |cffffffffBasics|r for crests.|n|n|cffffcc00Tip:|r open the |cffffffffCurrencies|r category here when you forget what a token is for. Scroll the boss preview in Delve Coach to zoom.",
	CODEX_MIDSTART_TITLE = "Starting the Midnight campaign",
	CODEX_MIDSTART_BODY = "|cffffcc00At level 80 the quest |r|cffffffffMidnight|r|cffffcc00 arrives on its own.|r There is nothing to go looking for — it lands in your log the moment you ding. Below 80 you can already travel to Silvermoon, but there is nothing there to accept yet.|n|n|cffffff78Where it starts|r|n• Speak to the |cffffffffImage of Lady Liadrin|r. She stands in more than one capital — Dornogal, Stormwind and Orgrimmar all have her.|n• She offers two things: watch the introduction, or |cffffffffI have heard this tale before|r to skip it.|n|n|cffffff78The skip costs you nothing|r|n• You come out in |cffffffffSilvermoon City|r and the next quest is handed to you straight away.|n• Nothing is locked behind the introduction — routes, city pins and the weekly routine all work exactly the same.|n|n|cffffff78Choosing where to begin|r|n• That next quest, |cffffffffAdventuring in Midnight|r, sends you to the |cffffffffScouting Map|r in the Sanctum of Light.|n• Five starting points: |cffffffffArator's Journey|r, |cffffffffEversong|r, |cffffffffZul'Aman|r, |cffffffffVoidstorm|r and |cffffffffHarandar|r.|n• Hover one for a line about what is there; clicking only opens its scouting report. |cffffffffLooking costs nothing.|r|n|n|cffffcc00Picked one and changed your mind?|r Choosing hides the other four for as long as that quest is in your log — but |cffffffffabandon the quest|r and all five come back. It decides your order, not your path.",
	CODEX_WARBAND_TITLE = "Warband & the Warband Bank",
	CODEX_WARBAND_BODY = "|cffffcc00Your Warband|r is every character on your account, treated as one team. Lots of things are now |cffffffffWarbound|r — shared account-wide — so you mail far less between alts.|n|n|cffffff78Warbound items & currencies|r|n• Some currencies are shared by the whole account or can be moved between characters — your currency window shows which. Upgrade crests count per character.|n• Gear is often |cffffffffWarbound until equipped|r — send it to an alt, but once equipped it sticks to that character.|n|n|cffffff78The Warband Bank|r — a shared bank all your characters use.|n• Open it at |cffffffffany banker|r (or Jeeves) — it's a tab on your normal bank, next to your character bank.|n• Store any |cffffffffnon-soulbound|r item, and deposit or withdraw |cffffffffgold|r across characters (even cross-faction).|n• Craft straight from it — it counts as a reagent source.|n|n|cffffff78Tabs & cost|r — 5 tabs, 98 slots each (490 total). You start with none; buy them with gold:|n• Tab 1: |cffffffff1,000g|r|n• Tab 2: |cffffffff25,000g|r|n• Tab 3: |cffffffff100,000g|r|n• Tab 4: |cffffffff500,000g|r|n• Tab 5: |cffffffff2,500,000g|r  (all five = 3,126,000g)|n|n|cffffcc00Tip:|r 2-3 tabs is plenty for most players. Don't confuse it with your |cffffffffcharacter bank|r (also tabbed since patch 11.2, far cheaper) — that one is per-character; the Warband Bank is shared.",

	CODEX_WEEKLY_RESET_TITLE = "Weekly reset",
	CODEX_WEEKLY_RESET_BODY = "• Most weekly progress resets on your region's maintenance day (EU Wednesday morning, US Tuesday morning).|n• Great Vault choices, world boss loot and many weekly caps reset.|n• The |cffffffffThis Week|r tab shows time until reset when the API provides it.|n• Plan alts: the |cffffffffAccount snapshot|r compares who still has a vault reward, keys or Delver's Calls open.",

	CODEX_VAULT_TITLE = "Great Vault",
	CODEX_VAULT_BODY = "• Three rows: |cffffffffWorld|r (delves, Prey and other world activities), |cffffffffDungeons|r (Heroic, Mythic, Mythic+ and Timewalking), |cffffffffRaid|r (raid bosses on any difficulty, and the Lair boss).|n• Each row opens up to three choices: World at 2/4/8 activities, Dungeons at 1/4/8, Raid at 2/4/6 bosses.|n• Each choice is only as good as the weakest run it needed: the 4-run choice uses your 4th best run of the week, the 8-run choice your 8th best. One hard key only lifts your first Dungeons choice.|n• Season 2: a raid choice comes one step above what you killed — Normal kills give a Hero-track item, Heroic kills a Myth-track item.|n• After the reset you pick |cffffffffone|r reward in total from all your unlocked choices, at the Great Vault in Silvermoon. SHIFT-J only shows a summary.|n• With 3 or more choices unlocked, from any rows, you may take a |cffffffffNebulous Voidcore|r (a bonus roll) instead of an item.|n• |cffffffffVault Advisor|r (on Blizzard's vault UI) ranks options vs your equipped gear.|n• In this addon the World row is on the |cffffffffDelves & Vault|r tab — expand |cffffffffWeekly Great Vault (World)|r. Hover a character in the |cffffffffAccount snapshot|r to see all three rows.|n• Summary also on the |cffffffffThis Week|r tab.",

	CODEX_WORLDBOSS_TITLE = "World boss (Midnight)",
	CODEX_WORLDBOSS_BODY = "• One rotating world boss per week (Lu'ashal, Cragpine, Thorm'belan, Predaxas), as a skull world quest on the map. You do not need to pick anything up.|n• Lady Liadrin in Silvermoon sometimes offers |cffffffffMidnight: World Boss|r as one of her four weekly choices; killing this week's boss completes it.|n• Warband loot: once any character kills it, alts show completed.|n• Tracked at the top of |cffffffffDelves & Vault|r with TomTom route.|n• Also linked from SMC City Guide when in Silvermoon.",
	CODEX_FOLIO_TITLE = "Omnium Folio (12.0.7)",
	CODEX_FOLIO_BODY = "• Power system from patch 12.0.7, still active in 12.1 — a minimap book of |cffffffffrunes|r you swap freely out of combat (no slot cost).|n• Power comes from the |cffffffff'Seeking Knowledge'|r chain (5 steps): The Omnium Folio, Ritualized Arcana, Ley Line Assaults, Magical Primessence, Off-World Magic.|n• Each step rewards a |cffffffffMote of Omnial Inquiry|r that opens the next row of runes.|n• Finish all 5 for the meta achievement and the Sunstrider Omnium Simulacrum decor.|n• Missed weeks? Do the missed quests back-to-back to catch up — no waiting for resets.|n• Alts: once one character has done the introduction, the others can skip it (12.1). Your rune choices stay per character.",
	CODEX_S2_TITLE = "A new season — what it means",
	CODEX_S2_BODY = "• Your character, mounts and collections all stay — nothing is lost.|n• Your gear keeps its item level. New-season gear simply starts at higher numbers, so your old pieces are no longer top-end. That is normal and happens to everyone.|n• Your Mythic+ rating starts fresh too — again, for everyone.|n• Season 2 came in two steps: first patch 12.1 (the Coiled Isle, the campaign, the Altar of Fangs dungeon), then a week later the season itself (raid, Mythic+, PvP, Bountiful Delves).|n• Gear upgrades now cost |cffffffffMistcrests|r. Last season's Dawncrests do not work on the new gear.|n• What to do now: follow the Start Here path, no rush.",
	CODEX_SEASONEND_TITLE = "When a season ends",
	CODEX_SEASONEND_BODY = "• |cffffffffYour gear does not reset.|r Everything you are wearing carries over at the item level it already has. It stops being top-end, but it is a real head start on day one of the next season. The change where everyone's numbers come down at once is a squish, and that belongs to an expansion's pre-patch — not to a season rollover.|n• |cffffffffThe numbers move, not your progress.|r Each season raises item levels, so a piece that is maxed on the top track now sits several tracks lower in the new numbers. That is normal and it happens to everyone.|n• |cffffffffKeep opening the Great Vault to the last week.|r Every weekly is free gear that raises where you start next season.|n• |cffffffffSeasonal currencies usually do not survive a rollover intact|r — they tend to convert or stop being useful. Spending them beats hoarding them. The exact behaviour differs per currency and can change late, so check the currency tab in game rather than trusting a guide.|n• |cffffffffThe real deadline is the season-only things:|r mounts, titles and achievements tied to this season, and progress tracks that reset. Those are the ones worth finishing while you still can.|n• |cffffffffProgress tracks reset, but their rewards are usually not gone|r — they often move to a vendor afterwards without the rank requirement, at a much higher price. Finishing now is cheaper than buying later.|n• |cffffffffPick one lane.|r The last weeks are short. Finishing one track beats half-finishing three.",
	CODEX_PREY_TITLE = "Prey hunts",
	CODEX_PREY_BODY = "• |cffffffffA Prey hunt is a tracked kill, not a dungeon.|r You pick up the hunt from Magister Astalor Bloodsworn in Murder Row, Silvermoon, follow it, and finish with a fight against one named target. No group finder. There is a weekly limit, though: only your first two hunts on each difficulty each week give a gear chest.|n• |cffffffffIt counts for the Great Vault.|r Prey feeds the same world row as delves and ritual sites, so it is a real way to fill that reward slot rather than a side attraction.|n• |cffffffffThere are three difficulty modes.|r Start on the lowest. A harder mode gives better gear and a better Great Vault choice. On Normal other players can help you; on Nightmare you fight alone.|n• |cffffffffWar Mode hunts are counted separately.|r If you do not play with War Mode on, you are not missing anything the rest of the system needs.|n• |cffffffffThe whole target list is a long-term goal, not a weekly chore.|r Working through it ends in a title. Doing one hunt when you feel like it is a perfectly good way to play it.|n• |cffffffffIt also opens a portal, and that is the part nobody tells you.|r Get into the Prey line and a portal links Astalor's Sanctum in Silvermoon directly with The Coiled Isle, which saves the long flight every single trip. Midnight Helper only offers it in route guidance once your own character can actually use it, so if you do not see it yet, keep going with Prey.|n• |cffffffffStart here|r: {WAY:2393:56.74:67.30:Magister Astalor Bloodsworn} in Murder Row, Silvermoon. Click that to set a waypoint. He is downstairs, inside the building. The portal stands beside him, and its pin in the City Guide walks you to the door first.|n• |cffffffffAnd the way back|r, which is the half nobody writes down: {WAY:2512:58.12:48.48:Portal to Silvermoon} on The Coiled Isle. Standing on the isle with no idea where the return portal is happens to everyone once.|n• |cffffffffTo see where you stand|r, type |cffffffff/mh prey|r, or open the Adventure Guide with Shift-J. Both read your own progress from the game rather than from a list we wrote down.",
	CODEX_S2GLOSS_TITLE = "Season 2 — new terms",
	CODEX_S2GLOSS_BODY = "• |cffffffffCrest|r — a currency to upgrade gear. In Season 2 they are called |cffffffffMistcrests|r. Each track (Adventurer to Myth) has its own crest; you earn them from delves, dungeons, raids, Prey and outdoor events.|n• |cffffffffUpgrade track|r — the ladder a piece of gear climbs (Adventurer, Veteran, Champion, Hero, Myth). Higher track = higher ceiling.|n• |cffffffffTier set|r — matching armor pieces. Wear 2 or 4 and you unlock a bonus for your spec.|n• |cffffffffCatalyst|r — turns a normal piece into a tier piece; in Season 2 it keeps the item's secondary stats.|n• |cffffffffBountiful Delve|r — a delve with an extra chest at the end; opening that chest costs a Restored Coffer Key.|n• |cffffffffNemesis Delve|r — a special seasonal delve with its own boss and rewards.|n• |cffffffffLair|r — a world boss you enter at a spot and pick a difficulty for your group, like a mini-raid.|n• |cffffffffNebulous Voidcore|r — a bonus roll: spend one after a boss for an extra chance at loot. You can also take one from the Great Vault instead of an item, and from the week of 6 October Orin Straylight's quest at the Catalyst in Silvermoon adds one extra a week.|n• |cffffffffNew-season item levels|r — new gear starts at higher numbers, so old gear is no longer top-end. Your gear itself does not change. A |cffffffffsquish|r is the opposite (numbers go down) and comes with an expansion's pre-patch, not with a new season.",
	CODEX_TT_TITLE = "Turbulent Timeways (12.0.7)",
	CODEX_TT_BODY = "• Returning Timewalking event — this time a |cffffffffDragonflight|r dungeon pool: Algeth'ar Academy, Halls of Infusion, Neltharus, Ruby Life Pools, The Azure Vault, Brackenhide Hollow.|n• Weekly: run |cffffffff5 Timewalking dungeons|r for a gear cache; each run stacks |cffffffffKnowledge of Timeways|r (XP buff).|n• Earn |cffffffffMastery of Timeways|r in 4 of 6 weeks for 'Master of the Turbulent Timeways' and the |cffffffffSpawn of Vyranoth|r mount.|n• Spend Timewarped Badges at the event vendor.|n• Runs ~June 30 – Aug 11. (Datamined — confirm at launch.)",

	CODEX_DELVER_CALL_TITLE = "Delver's Call",
	CODEX_DELVER_CALL_BODY = "• One quest per Midnight delve: finish that delve once, on any tier. Every character can do each one once — they do not come back every week.|n• They pay a lot of XP, and the payout grows with your level. While levelling: finish the delves early, hand the quests in late (around level 87-88).|n• |cffffffffAccount snapshot|r shows which characters still hold finished calls (banked).|n• Hover the Delver's Call line in snapshot for per-character detail.",

	CODEX_ACCOUNT_TITLE = "Account snapshot",
	CODEX_ACCOUNT_BODY = "• Read-only overview of characters you've logged in on with Midnight Helper.|n• Sort/filter by vault ready, keys, Shards of Dundun cap, stale since reset, etc.|n• Use it to answer: “Which alt still has a vault reward, keys or Delver's Calls waiting?”|n• The world boss and the Silvermoon weekly quests are on the |cffffffffThis Week|r tab, not here.|n• Does not replace logging onto an alt for gear or quest checks.",

	CODEX_CUR_COFFER_KEY_TITLE = "Restored Coffer Key",
	CODEX_CUR_COFFER_KEY_BODY = "• Opens the |cffffffffBountiful Coffer|r at the end of a Bountiful delve. You do not need one to enter a delve.|n• Made from 100 Coffer Key Shards — entering a delve combines them for you. From Delver's Journey rank 6 you can also buy 2 a week from Naleidea Rivergleam in the Delver's HQ.|n• Each character has its own keys. Your count is on |cffffffffDelves & Vault|r; the Account snapshot shows the rest.",

	CODEX_CUR_SHARDS_TITLE = "Coffer Key Shards",
	CODEX_CUR_SHARDS_BODY = "• 100 shards make one Restored Coffer Key. Entering a delve combines them for you.|n• They come from the outdoors: the game names treasures, world quests and outdoor events, and rares pay them too.|n• Weekly earn cap of 600 — track 'Weekly: X / Y' on the Delves tab. That is about six keys a week. Delver's Journey rank 10 makes every source pay more.",

	CODEX_CUR_UNDERCOIN_TITLE = "Undercoin",
	CODEX_CUR_UNDERCOIN_BODY = "• Delve currency. It drops from the chests at the end of a delve — the most from Bountiful delves on higher tiers.|n• Spend it at |cffffffffNaleidea Rivergleam|r in the Delver's HQ in Silvermoon: cosmetics, decor, toys and the L00T RAID-R Mini. From Delver's Journey rank 6 she also sells your 2 weekly Restored Coffer Keys for it.|n• From Delver's Journey rank 5, |cffffffffZah'ran|r appears at the end of a Tier 6+ delve. He sells Champion gear for Undercoin, and his stock changes every run.",

	CODEX_CUR_MANA_TITLE = "Untainted Mana-Crystals",
	CODEX_CUR_MANA_BODY = "• Buys Hero gear from |cffffffffZah'ran|r, the vendor who appears at the end of a Tier 6+ delve.|n• Only from Delver's Journey rank 9: then Tier 11 Bountiful Coffers can hold them (or a Hero item), and Tiers 8-10 give smaller amounts.|n• Account snapshot can show per-character totals.",

	CODEX_CUR_ACCOLADES_TITLE = "Field Accolades",
	CODEX_CUR_ACCOLADES_BODY = "• Shared currency for the |cffffffffVoid & Rituals|r systems: you earn it from Ritual Sites and Void Assaults.|n• Spend it in the Bazaar in Silvermoon City: |cffffffffMaren Silverwing|r sells gear caches (Season 2: Adventurer gear for 200, Veteran gear for 500 at random or 750 for a slot you pick), |cffffffffTriam Dawnsetter|r sells cosmetics.|n• Live count on |cffffffffVoid & Rituals|r tab.",

	CODEX_CUR_DAWN_TITLE = "Crests",
	CODEX_CUR_DAWN_BODY = "• The currency you spend to upgrade gear one rank at a time: 20 crests per rank, and each track takes only its own crest. Not tied to your Great Vault raid slots.|n• Crafters use them too: crests set the item level of a crafted piece.|n• Live crest counts are on |cffffffffBasics -> Crests|r (not in this list).|n• Until the week of 20 October there is a cap. It counts how many you have earned this season, not how many you are holding — spending crests does not free up room. It goes up by 100 every week. From the week of 20 October the cap is gone.|n• Not the same as delve keys — see that guide for what to spend them on.",
	CODEX_TRACKS_TITLE = "Gear upgrade tracks",
	CODEX_TRACKS_BODY = "• Gear doesn't just have an item level — it sits on a |cfffffffftrack|r. Low to high: |cffffffffAdventurer|r (green), |cffffffffVeteran|r, |cffffffffChampion|r, |cffffffffHero|r, |cffffffffMyth|r.|n• A tooltip reading |cffffffffHero 3/6|r means: the Hero track, rank 3 of 6. Each rank you buy adds item level.|n• The track sets your ceiling — the tooltip shows the item level range it can reach. To climb past it you need a drop from a higher track.|n• Each track has its own crest colour. Harder content drops gear on a higher track — that's how you climb.|n• Outgrown a track? Trade lower crests up at |cffffffffVaskarn|r. Upgrade at |cffffffffCuzolth|r in Silvermoon — a rank costs that track's crests plus a little gold.|n• Each track has an achievement for outgrowing it, named after the season's own crest — in Season 2 the «…of the Mist» line. It halves that track's crest cost for your other characters, and (Adventurer to Hero) lets this character trade that crest up at Vaskarn: 30 for 10 of the next tier.|n• Live counts and waypoints: |cffffffffBasics -> Crests|r.",

	CODEX_DELVES_INTRO_TITLE = "Midnight delves — overview",
	CODEX_DELVES_INTRO_BODY = "• Short instanced runs for 1 to 5 players, with Valeera as your companion — across Quel'Thalas and the Coiled Isle.|n• |cffffffffTiers 1–11|r. Tier 4 and up needs level 90 and the Midnight campaign finished once on your Warband; after that, clearing a tier opens the next one.|n• Gear stops improving at |cffffffffTier 8|r: Bountiful Coffer 295, Great Vault 305 (Hero 1/6). Tier 11 still pays better crests.|n• Entering is free — no key needed. A |cffffffffBountiful|r delve (up to four a day) ends with a Bountiful Coffer, and that chest needs a |cffffffffRestored Coffer Key|r (see Currencies).|n• Use 'Find Nearest Bountiful Delve' on the Delves tab.",

	CODEX_DELVE_COACH_TITLE = "Delve Coach",
	CODEX_DELVE_COACH_BODY = "• Floating tips panel: route, trash, and boss mechanics per delve.|n• Opens by itself when you enter a delve, or via |cffffffffDelve Coach (preview tips)|r / |cffffffff/mh coach|r.|n• The tips are in your game's language; `/mh lang` switches between English and Dutch.|n• Boss spotlight: scroll on the model to zoom (saved per boss).|n• Blue spell names link to real spell tooltips when IDs are known.",

	CODEX_DELVE_CURIOS_TITLE = "Valeera & delve curios",
	CODEX_DELVE_CURIOS_BODY = "• Valeera has three slots you fill yourself: a |cffffffffPoison|r, a |cffffffffCombat Curio|r and a |cffffffffUtility Curio|r. Her role (Tank, Healer or DPS) is a separate choice.|n• Change them at the supplies at the start of a delve and at its checkpoint, where you also repair.|n• Season 2 has six poisons: three from the start, three more after Valeera's Season 2 intro quests (Seasonal Refresher: Midnight, then Slithering Spoils).|n• |cffffffff/mh curios|r shows what each option does in the game's own words, with a star on what most guides pick. A small panel with those picks opens beside her window.|n• The delve items popup tracks RAID-R Mini and Trovehunter's Bounty.",

	CODEX_TORMENTS_TITLE = "Venomfall Deeps (Nemesis delve)",
	CODEX_TORMENTS_BODY = "• The Season 2 Nemesis delve, in the north of the Coiled Isle: {WAY:2512:51.23:30.26:Venomfall Deeps}. The boss is |cffffffffAzta'rec|r, on difficulty |cffffffff?|r or |cffffffff??|r.|n• To unlock it, finish any Tier 7 delve with at least one life left (for ?), or any Tier 10 delve with a life left (for ??).|n• The entrance advises item level 290 for ? and 309 for ??.|n• Season-only: defeating him gives the achievement My Venomous Nemesis (a back transmog); on ?? with no other players, Let Me Solo Him: Azta'rec (the Apophic Soul Crusher mount).|n• Torment's Rise and Nullaeus were Season 1's Nemesis.|n• Delve Coach has the fight plan.",

	CODEX_DELVE_LOG_TITLE = "Delve Log",
	CODEX_DELVE_LOG_BODY = "• A per-character record of every Midnight delve and Ritual Site run you finish: tier, time and deaths — for delves also whether you used a key, and the end boss.|n• It tracks by itself; the tab does not need to be open.|n• Handy to see which tier you last cleared, and how long it took.|n• Looking for an entrance? |cffffffffFind Nearest Delve|r is on the |cffffffffDelves & Vault|r tab.",

	CODEX_MPLUS_TITLE = "Mythic+ & dungeon vault",
	CODEX_MPLUS_BODY = "• Mythic+ fills the |cffffffffDungeons|r Great Vault row (separate from delve/world rows). Heroic, Mythic 0 and Timewalking dungeons count there too, at a lower reward.|n• A higher key gives a higher item level in the vault. Timed or not, every finished key counts. This season it stops going up at +10.|n• Your three choices use your best, 4th best and 8th best key of the week.|n• Vault Advisor has separate M+ stat weights only for healers; tanks and damage dealers get the same weights for raid and M+.|n• Midnight Helper does not replace a route addon — use MDT / notes for affix weeks.",
	CODEX_MPLUS_START_TITLE = "Mythic+, from your first key",
	CODEX_MPLUS_START_BODY = "Mythic+ is a normal dungeon with a |cffffcc00Keystone|r: a key with a level, like +2 or +3. Higher keys are harder and give better loot, and every key you finish counts for your |cffffcc00Great Vault|r.|n|n|cffffcc00Your first key|r|n• Finish a Mythic 0 dungeon: the last boss gives you a key.|n• Or join someone else's key: when it is done, you get one too.|n• Lost yours, or never had one? |cffffffffLindormi|r in Silvermoon City, beside the portal to The Timeways, gives you one.|n• You hold one key at a time, and it starts at +2.|n|n|cffffcc00Join a group|r|n• Press |cffffffffI|r, open |cffffffff{UI:GROUP_FINDER}|r, then |cffffffff{UI:LFGLIST_NAME}|r and |cffffffffDungeons|r. Mythic dungeons have no queue.|n• Pick a low key, +2 to +4. Groups marked |cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r expect new players.|n• Click |cffffffff{UI:SIGN_UP}|r, tick your role, and wait for the leader to invite you.|n|n|cffffcc00Start your own group|r|n• Same place: click |cffffffff{UI:START_A_GROUP}|r, choose the dungeon on your key, pick a playstyle (|cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r is fine) and click |cffffffff{UI:LIST_GROUP}|r.|n• Set the dungeon difficulty to |cffffffffMythic|r before you walk in.|n• Inside, whoever holds the key clicks the |cffffffffFont of Power|r near the entrance, puts the key in and presses |cffffffff{UI:CHALLENGE_MODE_START_CHALLENGE}|r. After a 10-second countdown the timer runs.|n|n|cffffcc00During the run|r|n• On +2 to +5 a death costs no time, and marked enemies show you a route. From +6 every death costs time.|n• From +5 an extra rule of the week joins in. The |cffffffff{UI:CHALLENGES}|r tab in the Group Finder shows which one.|n• In time: your key goes up 1 to 3 levels. Too late: you still get loot, but the key drops 1 level. Either way it moves to another dungeon.|n• Need to stop? Type |cffffffff/abandon|r to start a vote. Just leaving can mark you as a Keystone Deserter.|n• Everyone opens the chest at the end for their own loot.|n|n|cffffcc00Help|r|n• Say it in the group: 'first time in this dungeon'. On low keys most players are glad to explain.|n• Ask your guild, or look in |cffffffff{UI:COMMUNITIES_GUILD_FINDER}|r and |cffffffffFind a Community|r in the Guild & Communities window (J).|n• Your |cffffffff{UI:DUNGEON_SCORE}|r is on the {UI:CHALLENGES} tab. Many leaders also look at the Raider.IO score.|n|nMidnight Helper helps inside: boss tips open as you walk in, and |cffffffff/mh mplus|r shows your best run per dungeon and where a key adds the most.",
	CODEX_AGGRO_TITLE = "Aggro: who is the enemy hitting?",
	CODEX_AGGRO_BODY = "Aggro means an enemy is attacking you. The tank wants it; a DPS or healer who pulls it often dies. The game can already warn you, but these warnings are switched off for many players. Midnight Helper changes none of them for you: type |cffffffff/mh aggro|r to see how yours are set.|n|n• |cffffffff{UI:NAMEPLATE_OPTIONS_LABEL} > {UI:UNIT_NAMEPLATES_THREAT_DISPLAY}|r: tick |cffffffff{UI:UNIT_NAMEPLATES_THREAT_DISPLAY_FLASH}|r. An enemy's nameplate flashes when the tank loses it or when a DPS or healer pulls it.|n• |cffffffff{UI:COMPACT_UNIT_FRAME_PROFILE_DISPLAYAGGROHIGHLIGHT}|r (raid frames): a red outline around whoever has aggro. Handy for healers.|n• |cffffffff{UI:ACCESSIBILITY_AUDIO_LABEL} > {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} > {UI:CAA_SAY_IF_TARGETED_LABEL}|r: a voice tells you when an enemy targets you. Turn on {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} first; this one is saved per specialization.|n|nUsing a nameplate addon such as Plater? Then the flash on nameplates comes from that addon, not from the game: look in its own settings.",

	CODEX_RAID_VAULT_TITLE = "Raid Great Vault",
	CODEX_RAID_VAULT_BODY = "• Raid bosses fill the Raid vault row: 2, 4 and 6 bosses open one, two and three choices. Every difficulty counts, Raid Finder too, and so does the Lair boss.|n• In Season 2 each choice comes from one difficulty higher than the one you killed the bosses on: Raid Finder gives Champion, Normal gives Hero, Heroic gives Myth, Mythic gives Myth at a higher level.|n• Mixed difficulties: each choice uses the highest difficulty on which you reached that number of bosses. The vault UI shows what you have this week.|n• Crests are what you spend afterwards to upgrade raid gear.",

	CODEX_VAULT_ADVISOR_TITLE = "Great Vault Advisor",
	CODEX_VAULT_ADVISOR_BODY = "• Side panel next to Blizzard's Great Vault window when you pick your reward at the Great Vault in Silvermoon — not inside Midnight Helper tabs. SHIFT-J only shows a summary, so the panel does not appear there.|n• Ranks vault pieces vs equipped gear using guide stat priorities (and optional Pawn).|n• Toggle in minimap quick settings / Esc -> AddOns -> Midnight Helper.|n• Auto vs Raid vs M+ profile for stat weights.",

	CODEX_WORLD_HUB_TITLE = "Void & Rituals — one system",
	CODEX_WORLD_HUB_BODY = "• Since patch 12.0.5, |cffffffffRitual Sites|r and |cffffffffVoid Assaults|r work as one system. Both move between Eversong Woods and Zul'Aman every week, and they share one currency and one renown.|n• Same |cffffffffField Accolades|r and Bazaar hub — do not grind them as unrelated farms.|n• Season 2 lowered the gear you buy with Field Accolades to Adventurer and Veteran: handy for a new character, not for top gear.|n• Open the combined tab for this week's active site and zone, your Field Accolades and renown, and route buttons.",

	CODEX_RITUAL_TITLE = "Ritual Sites",
	CODEX_RITUAL_BODY = "• An instanced ritual for 1 to 5 players. Each week it is at one of two places: Daggerspine Point in Eversong Woods or the Broken Throne in Zul'Aman. Pick a tier and finish it for accolades, renown and loot.|n• Only one site is active at a time; the addon highlights which.|n• The Ritual Site pin in the SMC City Guide sets a route to this week's active site. If the addon does not know it yet, the pin opens the Void & Rituals tab.",

	CODEX_VOID_TITLE = "Void Assaults",
	CODEX_VOID_BODY = "• The Void attacks Eversong Woods or Zul'Aman — one of the two each week. Clear Void Strikes; enough of them start a bigger Void Incursion. Both pay Field Accolades.|n• Shares Field Accolades and the Ritual Sites renown with Ritual Sites — progress both at once.|n• The Void & Rituals tab shows this week's zone, next week's zone and your weekly quest.",

	CODEX_RARES_TITLE = "Midnight rares",
	CODEX_RARES_BODY = "• Weekly rare mobs with account/character loot (check each rare's rules in-game).|n• |cffffffffRares|r tab: track kills and build a route, nearest rare first. The route arrow (Midnight Helper's own, or TomTom's if you use it) then moves on to the next closest one.|n• Live alert when a tracked rare is nearby (~500 yds) — toggle in settings.",

	CODEX_PROF_TITLE = "Professions — weekly loop",
	CODEX_PROF_BODY = "• Each profession has its own |cffffffffKnowledge Points (KP)|r and its own |cffffffffArtisan's Moxie|r: Alchemy Moxie only buys Alchemy things.|n• |cffffffffEvery week, per profession:|r the weekly quest from your trainer in Silvermoon (from skill 25), |cffffffffPatron orders|r at the Crafting Orders table that reward Knowledge (the biggest weekly source), up to two Knowledge items from ordinary treasures in the Midnight zones, and one Thalassian Treatise (made by Inscription).|n• Gatherers and Enchanters also get Knowledge items from gathering or disenchanting. Those catch up a missed week; most other weekly sources do not.|n• |cffffffffAbundance|r is a separate track: a Shard of Dundun (8 a week at most) starts an Abundant Harvest, and that pays Unalloyed Abundance.|n• |cffffffffProfessions|r tab: unspent KP, your Shards of Dundun, and map pins for treasures and books. Where to spend KP: the Basics guide.",

	CODEX_PROF_GUIDE_TITLE = "Professions beginner guide",
	CODEX_PROF_GUIDE_BODY = "• |cffffffffBasics -> Professions|r sub-tab: step-by-step KP plan and combo suggestions.|n• The |cffffffffCrests|r sub-tab is about crests: the currency you use to upgrade gear, earned from many activities — not only raids.|n• Re-read after patches — numbers and caps can change.",
	CODEX_CRAFTGEAR_TITLE = "Getting gear crafted",
	CODEX_CRAFTGEAR_BODY = "• You don't need the profession yourself — another player can craft it for you through a |cffffffffCrafting Order|r.|n• Crafted gear is the |cffffffffreliable|r route: no drop luck involved. It is also the only gear that can carry an |cffffffffEmbellishment|r (a special effect — you can wear two at most).|n• |cffffffffWhat you gather first:|r a |cffffffffSpark|r (2 for armour or a one-hand weapon, 4 for a two-hander) from the weekly quest in Silvermoon; |cffffffffcrests|r if you want the higher version; a |cffffffffMissive|r to pick your secondary stats (Auction House); and the materials.|n• |cffffffffThe crest step matters:|r without crests you get the base version. Adding crests of a higher tier raises the item level it can reach — the top-tier crests give the strongest craft. Your own crest tab shows what you have.|n• |cffffffffThen order it:|r talk to the Crafting Orders NPC in Silvermoon's Bazaar, pick the item, attach your spark, crests and missive, and place it as a public order or send it to a crafter you know. Add a tip so someone picks it up.|n• |cffffffffSparks and crests cannot be supplied by the crafter|r — you must own them. This is where most first orders fail.|n• The crafter's skill decides the quality, so a crafter you know beats a random public order.|n• Worth it when a slot refuses to drop for you, or for an Embellishment. If good drops come easily in that slot, save the crests.",
	CODEX_PROFRESET_TITLE = "Resetting a profession’s specializations (12.1)",
	CODEX_PROFRESET_BODY = "• Patch 12.1 lets you undo your Midnight specialization choices — once per profession.|n• |cffffffffWho:|r {WAY:2393:45.05:56.17:Theremis}, in Silvermoon’s Bazaar beside the crafting orders — click that for a waypoint. He offers one line per profession, so you can reset Blacksmithing and leave Enchanting exactly as it is.|n• |cffffffffWhat comes back:|r every Knowledge Point you spent in that profession’s Midnight trees, yours to re-allocate as you see fit.|n• |cffffffffWhat it costs:|r the game’s warning reads “You will lose all associated recipes”.|n• |cffffffffAssociated, not all.|r What goes is what those specialization choices unlocked. Recipes you learned from a trainer, a drop or a quest sit outside the trees and stay. Seen on a reset Enchanting: the recipe list was untouched and the spent Knowledge was back on the counter.|n• |cffffffffIt is once.|r The confirmation says ONCE in capitals, and that is per profession — there is no second attempt if the new path disappoints you.|n• So decide where the points are going |cffffffffbefore|r you confirm. The Professions page names the tree to fill and the exact node to spend on.|n• Does re-spending exactly as before return the recipes it took? The game never says so. Plan as though it will not.",
	CODEX_CORRPOWER_TITLE = "Corrosive Codex — which gift do I take first?",
	CODEX_CORRPOWER_BODY = "|cffffcc00Twelve gifts, and you may use one of them.|r Every single one costs |cffffffff8 Corrosive Souls|r, so all twelve together cost 96. Because the price is the same for all of them, your first pick is about |cffffffffwhat you need|r — never about what you can afford.|n|n|cffffff78One thing explains the whole system|r|n• It is a |cffffffffpoison loop|r. Half the gifts get stronger against an enemy that is Poisoned, or while |cffffffffyou yourself|r are poisoned.|n• That is why every good pair is |cffffffffone gift that poisons + one gift that pays off on poison|r. Once you see that, the combinations stop looking random.|n|n|cffffff78Which one first? Pick by your problem, not off a list|r|n• |cffffffffI just want to hit harder|r → |cffffffffUla'tek's Gift|r. It works on its own, with no second gift and no setup. Every guide we read names this one first.|n• |cffffffffGroups of enemies take too long|r → |cffffffffPlague of Corrosion|r or |cffffffffOphidian Maw|r.|n• |cffffffffI keep dying in delves|r → |cffffffffVirulent Mucus|r swallows the big hits, |cffffffffGorgoneion Gaze|r freezes everything around you the moment you drop below half health.|n• |cffffffffCasters keep getting their spell off|r → |cffffffffAccursed Poison|r. It interrupts one cast for you.|n|n|cffffcc00Watch out with Mephitic Cloud.|r It lets affected |cffffffffenemies|r heal whatever they are attacking. In a group that works against you.|n|n|cffffff78What we measured ourselves, and what we did not|r|n• |cffffffffOut of the game:|r the price of 8, and the full text of Ula'tek's Gift. Those are ours.|n• |cffffffffOut of guides:|r the order above, and how many gifts open the second slot. The game itself only says \"until your offerings are sufficient\" and names no number. |cffffffffSix sources say 8|r — including Wowhead's own spell page, which puts it in a table — and one blog says 6. So 8 is very probably right; we simply have not seen it happen ourselves. You will know the moment your second slot appears.|n• Ula'tek's Gift has |cffffffffalready been tuned down once|r. A ranking from August is not automatically true today — which is exactly why the poison loop above is the part worth remembering.",
	CODEX_ATALUTEK_TITLE = "The Vaults of Atal'Utek — what is in there, and where",
	CODEX_ATALUTEK_BODY = "|cff8fd3ffGetting started|r|n|n• |cffffffffWhat it is:|r a 12.1 area on the Coiled Isle with its own map, and a second map underneath it, the Underbelly. It is open now — there is no season gate on it.|n|n• |cffffffffHow you get in:|r a chain of four quests — |cffffffffInto the Vaults of Atal'Utek|r, then |cffffffffVaults of Atal'Utek: One Coin Too Many|r and |cffffffffVaults of Atal'Utek: A Toxic Tour|r, which you are given together, then |cffffffffVaults of Atal'Utek: The Altar of Corrosion|r. Everything below sits behind them, so do those first. |cffffffffA Toxic Tour is a one-time story quest, not a daily|r — it asks for one Patrol, one Strike, one Incursion and one Ancient Foe, so it completes itself while you do the loop described below.|n|n|cff8fd3ffWhat you do here|r|n|n• |cffffffffWhat you actually do here — four things, and they feed each other.|r |cffffffffTemple Patrols|r wander the map and rotate about every ten minutes; they are the easiest thing to join and the one that is nearly always running. |cffffffffTemple Strikes|r are bigger, and they are what builds toward an incursion. Once enough Strikes are done a |cffffffffTemple Incursion|r begins, and every Incursion ends by waking an |cffffffffAncient Foe|r — which is where the three rare elites come from: only one of them per week, on a ten-minute clock. Coins, keys, gear and reputation all come out of that loop, so if you are wondering what to do, the answer is join whatever is running.|n|n• |cffffffffHow do I actually find a Temple Strike?|r Open your map inside the Vaults and look for the event icons — a Strike is marked there like any world event, and |cffffffffit has no timer|r: it sits and waits until a group finishes it, so you can take your time walking over. |cffffffffA few players is enough|r; you do not need a premade, and other people are usually already on it. There are six, and each starts in a fixed spot — click one to set a waypoint: {WAY:2509:50.55:15.70:Cursed Depths} · {WAY:2509:47.36:46.17:Overflowing Venom} · {WAY:2509:47.67:46.34:Profane Pyres} · {WAY:2509:47.26:26.69:Purifying Earth and Sky} · {WAY:2509:39.32:39.92:Ruuk’Jar’s Clutch} · {WAY:2613:52.25:36.27:The Underbelly}.|nIf the map shows no Strike, an Incursion or its Ancient Foe is probably running right now — join that instead. A new Strike appears once it is over.|n|n• |cffffffffGetting around inside.|r The |cffffffffAmani Windcallers|r fly you between three points in the Vaults — the |cffffffffAmani Foothold|r hub, the Eastern Amani Outpost and the Northern Amani Bulwark. The flight master |cffffffffEagletender Mal’Tiki|r stands at {WAY:2509:44.42:62.21:Amani Foothold}. You cannot fly inside the Vaults, which is exactly why they are there — the place is bigger than it looks and walking it is the slow way.|n|n• |cffffffffThe repeatables — one weekly and eight dailies.|r |cffffffffPurging the Vaults|r from |cffffffffWarleader Abdumati|r in the Amani Foothold is the weekly worth not missing. The eight dailies are |cffffffffPatrolling the Temple|r, |cffffffffBounty of the Cursed|r, |cffffffffRelentless Strikes|r, |cffffffffDecisive Incursions|r, |cffffffffFrom Whence it Came|r, |cffffffffEssence of Malice|r, |cffffffffWhat's Out There?|r and |cffffffffShoulder to Shoulder|r — take whichever your map offers today. Most of them ask for the activities above, so they tick themselves off while you play. Two want you in a party (What's Out There? and Shoulder to Shoulder): the people already standing next to you are enough, not a premade. And one you would never find by being here: |cffffffffMidnight: Vaults of Atal'Utek|r is a weekly meta for this place that you pick up in |cffffffffSilvermoon|r.|n|n|cff8fd3ffCoin and Soul|r|n|n• |cffffffffCorrosive Coin|r is the zone's currency. The game's own words: “Spirits of the Amani within the Vaults of Atal'Utek deal exclusively in this phantasmal token.” Your balance is the number above this article.|n|n• |cffffffffCorrosive Soul is not that.|r It is not a currency at all but an |cffffffffitem|r in your bags, and it is what the Corrosive Codex asks you to offer. Guides swap the two names constantly; the game never does. If something tells you to spend Corrosive Coins at the Codex, that is the mix-up.|n|n• |cffffffffWhere the coins go — two places, both at Er’inye|r at {WAY:2509:51.10:62.76:Er'inye}. Talking to her buys |cffffffffCorrode Spirit|r, which is what feeds the Altar tree; beside her the |cffffffffSkull of Er’inye|r is a merchant with three pages of mounts, pets, ensembles and recipes, priced from 500 to 25,000 coin. |cffffffffThe corrode price climbs every time you buy it|r — seen at 1,500 and then 2,000 on one visit — so read the window rather than saving up for a number.",
	CODEX_ATALUTEK_DISC_TITLE = "Altar of Corrosion: the four keys",
	CODEX_ATALUTEK_DISC_BODY = "• |cffffffffThe Altar of Corrosion|r is the node tree the last quest of the chain opens. Most of it unlocks as you spend, but |cfffffffffour nodes sit behind a key you have to go and find|r — and all four work the same way: an item drops, you use it on one object somewhere in the Vaults, that gives a quest item, and Er’inye takes it from there.|n|cffffffffCorroded Key|r → the Venom-Worn Coffer → |cffffffffRun of the Vaults|r (Glideways, or Swift Steps) · |cffffffffSpirit Loupe|r → the Feather of Tok’jara at {WAY:2509:48.46:25.80:Feather of Tok'jara} → |cffffffffSpectral Winds|r (Spirit Walk, or Spectral Shipping) · |cffffffffExcising Knife|r → the Eye of Szarith, in a venom pool in the Underbelly → |cffffffffBroodmaster|r (+100% damage to eggs, or −75% damage from egg bursts) · |cffffffffDispelling Charm|r → Jin’tal’s Reliquary in the Profaned Mausoleum → |cffffffffSpiritual Protection|r (ghostly allies at Curse Surges, or getting straight back up when you die outside the Vaults).|n|cffffffffShowing a key to Er’inye does not unlock anything.|r She is blind, and she tells you what she feels — that is a hint about where the thing belongs. |cffffffffWhere the keys come from|r — the guides now agree: the Corroded Key from Temple Strikes, the Excising Knife from a Temple Incursion, the Spirit Loupe from an Ancient Foe. The |cffffffffDispelling Charm|r is the odd one out: it does not come from the events, but from Jin’tal in the Vault of Restless Bones, during a side questline about the Med’jai.|n|n• |cffffffffSpend your first coin on the tree straight away.|r Its first four nodes cost nothing and unlock as you spend elsewhere, and they raise the Corrosive Coin you earn by |cffffffff25, 50, 75 and finally 100 percent|r. The tree pays for itself, so every lap after the first one is richer — saving up is the expensive choice. And note the asymmetry that sets this zone’s pace: |cffffffffcoin has no cap|r, while Corrosive Souls are rationed. Farm coin freely; do not plan an evening around souls.",
	-- 12.1.5 (7 Oct 2026). Only shown from that build (minInterface in MidnightCodexData.lua). Facts and their
	-- sources: docs/PATCH_12_1_5_CONTENT_2026-10-07.md. Guide-only claims say "guides say".
	CODEX_LABYRINTH_TITLE = "The Labyrinth of Kindo'jan (12.1.5)",
	CODEX_LABYRINTH_BODY = "|cffffcc00A big delve of nine rooms, with the boss Kindo'jan at the end.|r New in patch 12.1.5. Valeera comes with you, as in every delve.|n|n|cffffff78Getting in|r|n• The entrance is in Eversong Woods: {WAY:2395:62.99:72.18:The Labyrinth of Kindo'jan}. There are 11 tiers; guides say you pick one at the door.|n|n|cffffff78You do not have to finish it|r|n• Every 3 rooms give |cffffffff2 Heavy Trunks, 1 Bountiful Coffer and Great Vault credit|r, and you may stop there. Crests from Heavy Trunks count double.|n• 3 rooms on a tier unlock the next tier.|n• |cffffffffIt opens normal delves too:|r 3 rooms on Labyrinth tier 1 to 8 unlock the next Delve tier for this season: Labyrinth tier 7 gives Delve tier 8. In the test-realm game data, tiers 9, 10 and 11 unlock the same Delve tier, not the next; that may still change at launch.|n|n|cffffff78Kindo'jan|r|n• From tier 8 he gives Great Vault credit once a week per character.|n• Three of his attacks are known: |cffffffffCrushing Blow|r (step out of the impact; an Amani Juggernaut appears), |cffffffffHash'ey's Command|r (4 Amani Headhunters — kill them fast) and |cffffffffDisgraceful Display|r, which stacks: at 3 stacks the loa find you unworthy. The game has no journal page for him.|n|n|cffffff78Help along the way|r|n• Four |cffffffffLoa-Spirit Conduits|r: click one for a strong boon for the whole group.|n• Bountiful Coffers from tier 8 hold a |cffffffffHeroic Soul Fragment|r; three make a random Hero-track piece.|n• A weekly questline of six steps, one new step each week, ends in two Myth-track armour pieces of your choice.|n|n|cffffcc00Not known yet:|r whether the coffers need a Restored Coffer Key, and how room credit and Kindo'jan's credit add up. Look at the Great Vault window rather than at a guide.",
	CODEX_AQIR_TITLE = "Aqir Invasion (12.1.5)",
	CODEX_AQIR_BODY = "|cffffcc00An outdoor event in Eversong Woods or Zul'Aman, 10 minutes every hour.|r The whole zone does public tasks together, and then a boss comes.|n• Six scenarios: Disrupt Aqir, Aid Defenders!, Aqir Nesting Grounds, Whack the Aqir, Aerial Assault and Reinforce Defenses. Three are fights; those get one of eight affixes.|n• From Blizzard's notes: interrupt the |cffffffffWebweaver|r and kill the |cffffffffVoidweaver|r first.|n• The reward track is |cffffffffAqir Research Enclave|r, a warband reputation up to Exalted. Its people are in Silvermoon: {WAY:2393:39.20:80.03:Aqir Researchers}.|n• Achievements: all six scenarios (No Hives Left Standing), ten invasions (Driving Back the Swarm), Exalted (Aqir Research Associate).|n• Guides say the zone changes every week and is never the zone of that week's Void Assault. We have not seen that ourselves yet.",
	CODEX_KITHIX_TITLE = "Kith'ix — a raid with one boss (12.1.5)",
	CODEX_KITHIX_BODY = "|cffffcc00The Unbinding of Kith'ix is a raid with one boss|r, the C'Thraxxi general Kith'ix. Lady Liadrin fights beside you. Story, Raid Finder, Normal, Heroic and Mythic (Mythic takes 15 to 25 players).|n• Entrance: under the Venomous Abyss, in The Underbelly: {WAY:2613:74.27:5.91:The Unbinding of Kith'ix}. Worked out from game data; not yet seen on screen.|n|n|cffffff78Everyone|r|n• Kill the adds before |cffffffffSuffocating Darkness|r. Whatever still lives then goes into a frenzy.|n• During Suffocating Darkness, |cffffffffstand in Liadrin's Refulgent Bulwark|r. Outside it you suffocate.|n• Before |cffffffffExtinguish|r, pick up |cffffffffLight's Embrace|r. It cuts the damage a lot.|n• Dodge |cffffffffTwisted Appendage|r.|n|n|cffffff78Healers|r — remove the |cffffffffAbyssal Grasp|r heal-absorb fast, or that player is dragged into the dark.|n|cffffff78Tanks|r — |cffffffffDark Devastation|r makes you take much more damage, so swap. Pull the aqir away from the boss: near him they take far less damage.|n|n|cffffff78Phase 2|r — |cffffffffStygian Howl|r stuns the raid. Liadrin saves you with Last Light and gives you a burst window. From there it is a race.",
	CODEX_VENOMSTONE_TITLE = "Ascendant Venomstones (12.1.5)",
	CODEX_VENOMSTONE_BODY = "|cffffcc00Venomstones lift a fully upgraded piece above its normal maximum.|r Ten |cffffffffAscendant Venomstones|r raise the item level of one Season 2 weapon, trinket or neck that is fully upgraded on the Hero or Myth track, or Tidal Crafted at top quality. You do it at the Catalyst in Silvermoon City, with Orin Straylight's help.|n|n|cffffff78It opens over three weeks|r, with quests from Orin in Silvermoon:|n• Week of 6 Oct — |cffffffffUmbral Blessings of the Catalyst|r: one extra Nebulous Voidcore a week.|n• Week of 13 Oct — |cffffffffAncient Depths, Ancient Venom|r: Orin starts his research.|n• Week of 20 Oct — |cffffffffAscending with Venomstones|r: the stones start to drop.|n• His earlier quests (In the Catalyst's Shadow, Prismatic Potential) come first.|n|n|cffffff78Where they drop|r — every Heroic and Mythic raid boss, Mythic+ from +10, Tier 11 Bountiful Delves, and the Champion gear chests of Nightmare Prey hunts.|n• In the week of 20 Oct the crest cap goes away too.|n|cffffcc00Guides say|r a piece that is already Ascendant cannot go higher.",
	CODEX_ATALUTEK_DEAD_TITLE = "The Honored Dead & the rares",
	CODEX_ATALUTEK_DEAD_BODY = "• |cffffffff“The Honored Dead” — twelve memorials|r on the Vaults map, one achievement, and the clearest thing here to just go and do. In one walking order, from the top of the map downwards:|n{WAY:2509:46.79:7.51:To a sister 46.79, 7.51} · {WAY:2509:56.49:22.88:To a shield-bearer 56.49, 22.88} · {WAY:2509:47.22:28.77:To a father 47.22, 28.77} · {WAY:2509:42.57:33.18:To a stranger 42.57, 33.18} (under the bridge) · {WAY:2509:52.91:33.90:To a captain 52.91, 33.90} · {WAY:2509:55.62:40.60:To a dream 55.62, 40.60} · {WAY:2509:42.84:39.93:To sons 42.84, 39.93} · {WAY:2509:52.21:45.12:To a lover 52.21, 45.12} · {WAY:2509:38.50:47.66:To Comrades 38.50, 47.66} · {WAY:2509:55.31:48.45:To parents 55.31, 48.45} · {WAY:2509:49.50:56.59:To a daughter 49.50, 56.59} · {WAY:2509:45.81:61.79:To Failure 45.81, 61.79}|n|n• |cffffffffThe Underbelly|r is the map below, entered at {WAY:2509:47.30:11.20:The Underbelly} on the Vaults map. One rare lives down there, |cffffffffSzarith the Fanged|r at {WAY:2613:38.40:17.69:Szarith the Fanged}, and the Underbelly carries its own achievement, |cffffffffSoft Underbelly|r. |cffffffffSzarith alone does not finish it:|r guides say it also wants several named elites that only show up while the Temple Strike |cffffffffThe Underbelly|r is running.|n|n• |cffffffffThree rare elites on the main map|r — Congealed Malice, Khu'tulak and Susarikk — make up a third, |cffffffffOppose the Foes|r. |cffffffffThey have no fixed spot, and that is the answer rather than a gap|r: one of them wakes up the moment a |cffffffffTemple Incursion|r is completed, and you have about ten minutes to kill it. |cffffffffOnly one of the three is in the rotation each week|r, so this achievement takes at least three weeks. You do not go hunting for them — you finish Incursions, and this week's one comes to you.",
})

merge(ns._mhLocales and ns._mhLocales.itIT, {
	TAB_CODEX = "Midnight Codex",
	CODEX_PANEL_TITLE = "Midnight Codex",
	CODEX_PANEL_INTRO = "Il tuo manuale per Midnight — cos'è ogni sistema, a cosa serve ogni currency e dove cliccare in questo addon. Passa il cursore sulle icone delle currency per i tooltip di Blizzard.",
	CODEX_OPEN_TAB_FMT = "Apri: %s",
	CODEX_NAV_DELVES_VAULT = "Scheda Delves & Vault (blocco Gran Banca)",
	CODEX_NAV_DELVES_MIDNIGHT = "Scheda Delves & Vault (elenco delve)",
	CODEX_NAV_BASICS_DAWN = "Categoria Basics (Crests)",
	CODEX_NAV_BASICS_PROF = "Scheda Basics (guida Professioni)",
	CODEX_BALANCE_FMT = "Hai: |cffffffff%d|r",
	CODEX_BALANCE_UNKNOWN = "Il saldo si aggiorna quando accedi con questo personaggio.",
	CODEX_SEARCH_OPENED = "Midnight Codex aperto.",
	CODEX_BETA_DISABLED = "Midnight Codex è disattivato nelle Impostazioni (schede beta).",

	CODEX_CAT_START = "Inizia qui",
	CODEX_CAT_WEEKLY = "Ciclo settimanale",
	CODEX_CAT_CURRENCIES = "Currencies",
	CODEX_CAT_DELVES = "Delves",
	CODEX_CAT_DUNGEONS = "Dungeons & M+",
	CODEX_CAT_RAID = "Raid & crests",
	-- ⚠️ Was "Void & Rituals" until 19 aug, and half of what sits under it is neither.
	-- The category holds Prey hunts, rares, Turbulent Timeways and Showdowns alongside
	-- the void and ritual articles. Rob went looking for Prey, read that button, and
	-- walked straight past it — the same class of fault as the twelve type-only commands
	-- on 18 aug: the feature was there, under a name nobody would guess.
	CODEX_CAT_WORLD = "World content",
	CODEX_CAT_COILEDISLE = "Coiled Isle",
	CODEX_ROUTE_BTN = "Segui il percorso",
	CODEX_CAT_PROFESSIONS = "Professions",

	CODEX_START_TITLE = "Inizia qui — la tua settimana Midnight",
	CODEX_START_BODY = "|cffffcc00Ragiona a livelli:|r un weekly reset, diverse tracce di ricompensa. Non ti serve ogni sistema ogni giorno — scegli un obiettivo.|n|n|cffffff781) Account & reset|r|n• Controlla la scheda |cffffffffThis Week|r per vault pronta, world boss, key e faccende.|n• |cffffffffAccount snapshot|r mostra tutti gli alt (vault, Delver's Call, weekly delle profession).|n|n|cffffff782) Contenuti di combattimento|r|n• |cffffffffDelves|r — traccia principale di gearing (key, tier, slot della Gran Banca). Usa |cffffffffDelve Coach|r per i consigli su ogni delve.|n• |cffffffffMythic+|r e |cffffffffIncursioni|r riempiono gli altri slot della Gran Banca (vedi le categorie Dungeons & Incursioni).|n|n|cffffff783) Mondo aperto|r|n• |cffffffffIsola Serpeggiante|r — la zona della Season 2 dalla patch 12.1, con una sua categoria qui.|n• Le cacce |cffffffffPrey|r contano per la stessa riga della Gran Banca delle delve.|n• Scheda |cffffffffVoid & Rituals|r — Field Accolades, Ritual Sites, Void Assaults (stessa traccia di renown).|n• Scheda |cffffffffRares|r — loot rare settimanale e percorsi.|n|n|cffffff784) Crafting|r|n• Scheda |cffffffffProfessioni|r per KP / mat settimanali; |cffffffffBasics|r per i crest.|n|n|cffffcc00Consiglio:|r apri qui la categoria |cffffffffCurrencies|r quando non ricordi a cosa serve un token. Scorri l'anteprima del boss in Delve Coach per zoomare.",

	CODEX_WEEKLY_RESET_TITLE = "Weekly reset",
	CODEX_WEEKLY_RESET_BODY = "• La maggior parte dei progressi settimanali si resetta nel giorno di manutenzione della tua regione (EU mercoledì mattina, US martedì mattina).|n• Si resettano le scelte della Gran Banca, il loot del world boss e molti cap settimanali.|n• La scheda |cffffffffThis Week|r mostra il tempo al reset quando l'API lo fornisce.|n• Pianifica gli alt: l'|cffffffffAccount snapshot|r confronta chi ha ancora in sospeso una ricompensa della vault, key o Delver's Call.",

	CODEX_VAULT_TITLE = "Gran Banca",
	CODEX_VAULT_BODY = "• Tre righe: |cffffffffWorld|r (delve, Prey e altre attività del mondo), |cffffffffDungeons|r (Eroico, Mitico, Mythic+ e Timewalking), |cffffffffIncursioni|r (boss d'incursione a qualsiasi difficoltà, e il boss della Lair).|n• Ogni riga apre fino a tre scelte: World a 2/4/8 attività, Dungeons a 1/4/8, Incursioni a 2/4/6 boss.|n• Ogni scelta vale quanto la run più debole che le è servita: la scelta da 4 run usa la tua 4ª miglior run della settimana, quella da 8 run la tua 8ª migliore. Una sola key difficile alza solo la tua prima scelta Dungeons.|n• Stagione 2: una scelta d'incursione arriva un gradino sopra ciò che hai ucciso — le uccisioni in Normale danno un oggetto della track Eroe, quelle in Eroico un oggetto della track Mito.|n• Dopo il reset scegli |cffffffffuna|r sola ricompensa in totale tra tutte le scelte sbloccate, alla Gran Banca a Silvermoon. SHIFT-J mostra solo un riepilogo.|n• Con 3 o più scelte sbloccate, da qualsiasi riga, puoi prendere un |cffffffffNebulous Voidcore|r (un tiro bonus) al posto di un oggetto.|n• |cffffffffVault Advisor|r (sull'UI vault di Blizzard) classifica le opzioni rispetto al tuo equip.|n• In questo addon la riga World è nella scheda |cffffffffDelves & Vault|r — espandi |cffffffffGran Banca settimanale (World)|r. Passa il cursore su un personaggio nell'|cffffffffAccount snapshot|r per vedere tutte e tre le righe.|n• Riepilogo anche nella scheda |cffffffffThis Week|r.",

	CODEX_WORLDBOSS_TITLE = "World boss (Midnight)",
	CODEX_WORLDBOSS_BODY = "• Un world boss a rotazione per settimana (Lu'ashal, Cragpine, Thorm'belan, Predaxas), come world quest con un teschio sulla mappa. Non devi raccogliere nulla.|n• Lady Liadrin a Silvermoon a volte offre |cffffffffMidnight: World Boss|r come una delle sue quattro scelte settimanali; uccidere il boss di questa settimana la completa.|n• Loot Warband: una volta che un personaggio lo uccide, gli alt risultano completati.|n• Tracciato in cima a |cffffffffDelves & Vault|r con percorso TomTom.|n• Collegato anche dalla SMC City Guide quando sei a Silvermoon.",
	CODEX_FOLIO_TITLE = "Omnium Folio (12.0.7)",
	CODEX_FOLIO_BODY = "• Sistema di potere dalla patch 12.0.7, ancora attivo nella 12.1 — un libro sulla minimappa di |cffffffffrune|r che scambi liberamente fuori dal combattimento (nessun costo di slot).|n• Il potere arriva dalla catena |cffffffff'Seeking Knowledge'|r (5 passi): The Omnium Folio, Ritualized Arcana, Ley Line Assaults, Magical Primessence, Off-World Magic.|n• Ogni passo ricompensa un |cffffffffMote of Omnial Inquiry|r che apre la riga successiva di rune.|n• Completa tutti e 5 per il meta achievement e l'arredo Sunstrider Omnium Simulacrum.|n• Hai saltato delle settimane? Fai le quest mancanti una dopo l'altra per recuperare — senza aspettare i reset.|n• Alt: quando un personaggio ha fatto l'introduzione, gli altri possono saltarla (12.1). Le tue scelte di rune restano per personaggio.",
	CODEX_TT_TITLE = "Turbulent Timeways (12.0.7)",
	CODEX_TT_BODY = "• Evento Timewalking di ritorno — questa volta un pool di dungeon |cffffffffDragonflight|r: Algeth'ar Academy, Halls of Infusion, Neltharus, Ruby Life Pools, The Azure Vault, Brackenhide Hollow.|n• Settimanale: completa |cffffffff5 dungeon Timewalking|r per un cache di gear; ogni run accumula |cffffffffKnowledge of Timeways|r (buff XP).|n• Ottieni |cffffffffMastery of Timeways|r in 4 settimane su 6 per 'Master of the Turbulent Timeways' e la cavalcatura |cffffffffSpawn of Vyranoth|r.|n• Spendi i Timewarped Badges dal venditore dell'evento.|n• Attivo dal ~30 giugno all'11 ago. (Da datamining — confermare al lancio.)",

	CODEX_DELVER_CALL_TITLE = "Delver's Call",
	CODEX_DELVER_CALL_BODY = "• Una missione per ogni delve di Midnight: completa quella delve una volta, a qualsiasi tier. Ogni personaggio può farle una volta sola — non tornano ogni settimana.|n• Danno molta XP, e la ricompensa cresce con il tuo livello. Mentre livelli: completa le delve presto, consegna le missioni tardi (verso il livello 87-88).|n• |cffffffffAccount snapshot|r mostra quali personaggi hanno ancora call completate (in banca).|n• Passa il cursore sulla riga Delver's Call nello snapshot per il dettaglio per personaggio.",

	CODEX_ACCOUNT_TITLE = "Account snapshot",
	CODEX_ACCOUNT_BODY = "• Panoramica in sola lettura dei personaggi con cui hai effettuato l'accesso usando Midnight Helper.|n• Ordina/filtra per vault pronta, key, cap di Shards of Dundun, inattivi dal reset, ecc.|n• Usalo per rispondere: “Quale alt ha ancora in sospeso una ricompensa della vault, key o Delver's Call?”|n• Il world boss e le quest settimanali di Silvermoon sono nella scheda |cffffffffThis Week|r, non qui.|n• Non sostituisce l'accesso a un alt per controllare gear o quest.",

	CODEX_CUR_COFFER_KEY_TITLE = "Restored Coffer Key",
	CODEX_CUR_COFFER_KEY_BODY = "• Apre il |cffffffffBountiful Coffer|r alla fine di una delve Bountiful. Non ti serve per entrare in una delve.|n• Si ottiene da 100 Coffer Key Shard — entrando in una delve si combinano da soli. Dal rango 6 del Delver's Journey puoi anche comprarne 2 a settimana da Naleidea Rivergleam al Delver's HQ.|n• Ogni personaggio ha le sue key. Il tuo conteggio è in |cffffffffDelves & Vault|r; l'Account snapshot mostra il resto.",

	CODEX_CUR_SHARDS_TITLE = "Coffer Key Shards",
	CODEX_CUR_SHARDS_BODY = "• 100 shard fanno una Restored Coffer Key. Entrando in una delve si combinano da soli.|n• Vengono dal mondo aperto: il gioco cita tesori, world quest ed eventi all'aperto, e li danno anche i rare.|n• Cap settimanale di guadagno di 600 — controlla 'Weekly: X / Y' nella scheda Delves. Sono circa sei key a settimana. Il rango 10 del Delver's Journey fa pagare di più ogni fonte.",

	CODEX_CUR_UNDERCOIN_TITLE = "Undercoin",
	CODEX_CUR_UNDERCOIN_BODY = "• Currency delle delve. Cade dai forzieri alla fine di una delve — di più dalle delve Bountiful ai tier più alti.|n• Spendila da |cffffffffNaleidea Rivergleam|r nel Delver's HQ a Silvermoon: cosmetici, arredi, giocattoli e il L00T RAID-R Mini. Dal rango 6 del Delver's Journey ti vende anche, in cambio di questa currency, le tue 2 Restored Coffer Key settimanali.|n• Dal rango 5 del Delver's Journey, |cffffffffZah'ran|r compare alla fine di una delve di Tier 6+. Vende equipaggiamento Campione per Undercoin, e la sua merce cambia a ogni run.",

	CODEX_CUR_MANA_TITLE = "Untainted Mana-Crystals",
	CODEX_CUR_MANA_BODY = "• Servono a comprare equipaggiamento Hero da |cffffffffZah'ran|r, il venditore che compare alla fine di una delve di Tier 6+.|n• Solo dal rango 9 del Delver's Journey: allora i Bountiful Coffer di Tier 11 possono contenerli (o un oggetto Hero), e i Tier 8-10 ne danno quantità minori.|n• Account snapshot può mostrare i totali per personaggio.",

	CODEX_CUR_ACCOLADES_TITLE = "Field Accolades",
	CODEX_CUR_ACCOLADES_BODY = "• Currency condivisa per i sistemi |cffffffffVoid & Rituals|r: la guadagni da Ritual Sites e Void Assaults.|n• Spendila nel Bazaar a Silvermoon City: |cffffffffMaren Silverwing|r vende cache di equipaggiamento (Stagione 2: equipaggiamento Adventurer per 200, equipaggiamento Veteran per 500 casuale o 750 per lo slot che scegli), |cffffffffTriam Dawnsetter|r vende cosmetici.|n• Conteggio in tempo reale nella scheda |cffffffffVoid & Rituals|r.",

	CODEX_CUR_DAWN_TITLE = "Crests",
	CODEX_CUR_DAWN_BODY = "• La currency che spendi per far salire l'equipaggiamento di un rank alla volta: 20 crest per rank, e ogni track accetta solo il proprio crest. Non è legata ai tuoi slot incursione della Gran Banca.|n• La usano anche i crafter: i crest fissano l'item level di un pezzo craftato.|n• I conteggi dei crest in tempo reale sono in |cffffffffBasics -> Crests|r (non in questo elenco).|n• Fino alla settimana del 20 ottobre c'è un cap. Conta quanti ne hai guadagnati in questa stagione, non quanti ne tieni — spenderli non libera spazio. Sale di 100 ogni settimana. Dalla settimana del 20 ottobre il cap sparisce.|n• Non sono come le key delle delve — vedi quella guida per capire in cosa spenderli.",
	CODEX_TRACKS_TITLE = "Gear upgrade tracks",
	CODEX_TRACKS_BODY = "• L'equipaggiamento non ha solo un item level — sta su una |cfffffffftrack|r. Dal basso all'alto: |cffffffffAdventurer|r (verde), |cffffffffVeteran|r, |cffffffffChampion|r, |cffffffffHero|r, |cffffffffMyth|r.|n• Un tooltip con |cffffffffHero 3/6|r significa: track Hero, grado 3 di 6. Ogni grado che compri aggiunge item level.|n• La track fissa il tuo limite — il tooltip mostra l'intervallo di item level che può raggiungere. Per superarlo ti serve un drop da una track più alta.|n• Ogni track ha il suo colore di crest. I contenuti più difficili fanno cadere equip su una track più alta — è così che sali.|n• Track superata? Scambia i crest inferiori da |cffffffffVaskarn|r. Potenzia da |cffffffffCuzolth|r a Silvermoon — un grado costa i crest di quella track più un po' d'oro.|n• Ogni track ha un achievement per averla superata, dal nome del crest della stagione — nella Season 2 la serie «…of the Mist». Dimezza il costo in crest di quella track per i tuoi altri personaggi e (da Adventurer a Hero) permette a questo personaggio di scambiare quel crest da Vaskarn: 30 per 10 del tier successivo.|n• Conteggi live e waypoint: |cffffffffBasics -> Crests|r.",

	CODEX_DELVES_INTRO_TITLE = "Midnight delves — panoramica",
	CODEX_DELVES_INTRO_BODY = "• Brevi run in istanza per 1-5 giocatori, con Valeera come compagna — tra Quel'Thalas e l'Isola Serpeggiante.|n• |cffffffffTier 1–11|r. Dal Tier 4 in su servono il livello 90 e la campagna di Midnight completata una volta sulla tua Warband; dopo, completare un tier apre il successivo.|n• L'equipaggiamento smette di migliorare al |cffffffffTier 8|r: Bountiful Coffer 295, Gran Banca 305 (Hero 1/6). Il Tier 11 dà comunque crest migliori.|n• Entrare è gratis — non serve una key. Una delve |cffffffffBountiful|r (fino a quattro al giorno) finisce con un Bountiful Coffer, e quel forziere richiede una |cffffffffRestored Coffer Key|r (vedi Currencies).|n• Usa 'Find Nearest Bountiful Delve' nella scheda Delves.",

	CODEX_DELVE_COACH_TITLE = "Delve Coach",
	CODEX_DELVE_COACH_BODY = "• Pannello di consigli fluttuante: percorso, trash e meccaniche dei boss per ogni delve.|n• Si apre da solo quando entri in una delve, o tramite |cffffffffDelve Coach (preview tips)|r / |cffffffff/mh coach|r.|n• I consigli sono nella lingua del tuo gioco; `/mh lang` passa dall'inglese all'olandese e viceversa.|n• Spotlight sul boss: scorri sul modello per zoomare (salvato per ogni boss).|n• I nomi delle spell in blu rimandano ai tooltip reali delle spell quando gli ID sono noti.",

	CODEX_DELVE_CURIOS_TITLE = "Valeera & delve curios",
	CODEX_DELVE_CURIOS_BODY = "• Valeera ha tre slot che riempi tu: un |cffffffffPoison|r, un |cffffffffCombat Curio|r e un |cffffffffUtility Curio|r. Il suo ruolo (Tank, Healer o DPS) è una scelta a parte.|n• Cambiali alle provviste all'inizio di una delve e al suo checkpoint, dove puoi anche riparare.|n• La Season 2 ha sei veleni: tre dall'inizio, altri tre dopo le missioni introduttive della Season 2 di Valeera (Seasonal Refresher: Midnight, poi Slithering Spoils).|n• |cffffffff/mh curios|r mostra cosa fa ogni opzione con le parole del gioco stesso, con una stella su ciò che sceglie la maggior parte delle guide. Accanto alla sua finestra si apre un piccolo pannello con quelle scelte.|n• Il popup degli oggetti delve traccia RAID-R Mini e Trovehunter's Bounty.",

	CODEX_TORMENTS_TITLE = "Venomfall Deeps (Nemesis delve)",
	CODEX_TORMENTS_BODY = "• La delve Nemesis della Season 2, nel nord dell'Isola Serpeggiante: {WAY:2512:51.23:30.26:Venomfall Deeps}. Il boss è |cffffffffAzta'rec|r, a difficoltà |cffffffff?|r o |cffffffff??|r.|n• Per sbloccarla, completa una qualsiasi delve di Tier 7 con almeno una vita rimasta (per ?), oppure una qualsiasi delve di Tier 10 con una vita rimasta (per ??).|n• L'ingresso consiglia item level 290 per ? e 309 per ??.|n• Solo in questa stagione: sconfiggerlo dà l'impresa My Venomous Nemesis (un transmog per la schiena); a ?? senza altri giocatori, Let Me Solo Him: Azta'rec (la cavalcatura Apophic Soul Crusher).|n• Torment's Rise e Nullaeus erano il Nemesis della Season 1.|n• Delve Coach ha il piano dello scontro.",

	CODEX_DELVE_LOG_TITLE = "Delve Log",
	CODEX_DELVE_LOG_BODY = "• Un registro per personaggio di ogni delve di Midnight e di ogni run di Ritual Site che completi: tier, tempo e morti — per le delve anche se hai usato una key, e il boss finale.|n• Si aggiorna da solo; la scheda non deve essere aperta.|n• Utile per vedere quale tier hai completato per ultimo, e quanto ci hai messo.|n• Cerchi un ingresso? |cffffffffFind Nearest Delve|r è nella scheda |cffffffffDelves & Vault|r.",

	CODEX_MPLUS_TITLE = "Mythic+ & vault dei dungeon",
	CODEX_MPLUS_BODY = "• Mythic+ riempie la riga |cffffffffDungeons|r della Gran Banca (separata dalle righe delve/world). Contano anche i dungeon Eroico, Mitico 0 e Timewalking, con una ricompensa più bassa.|n• Una key più alta dà un item level più alto nella vault. Nei tempi o no, ogni key completata conta. In questa stagione smette di salire a +10.|n• Le tue tre scelte usano la tua miglior key della settimana, la 4ª e l'8ª migliore.|n• Vault Advisor ha pesi delle stat M+ separati solo per gli healer; tank e DPS ricevono gli stessi pesi per incursioni e M+.|n• Midnight Helper non sostituisce un addon di route — usa MDT / note per le settimane degli affix.",
	CODEX_MPLUS_START_TITLE = "Mythic+, dalla tua prima key",
	CODEX_MPLUS_START_BODY = "Mythic+ è un normale dungeon con una |cffffcc00Keystone|r: una key con un livello, come +2 o +3. Le key più alte sono più difficili e danno loot migliore, e ogni key che completi conta per la tua |cffffcc00Gran Banca|r.|n|n|cffffcc00La tua prima key|r|n• Completa un dungeon Mythic 0: l'ultimo boss ti dà una key.|n• Oppure unisciti alla key di qualcun altro: quando è finita, ne ricevi una anche tu.|n• Hai perso la tua, o non l'hai mai avuta? |cffffffffLindormi|r a Silvermoon City, accanto al portale per The Timeways, te ne dà una.|n• Hai una sola key alla volta, e parte da +2.|n|n|cffffcc00Entra in un gruppo|r|n• Premi |cffffffffI|r, apri |cffffffff{UI:GROUP_FINDER}|r, poi |cffffffff{UI:LFGLIST_NAME}|r e |cffffffffDungeons|r. I dungeon Mythic non hanno coda.|n• Scegli una key bassa, da +2 a +4. I gruppi segnati |cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r si aspettano giocatori nuovi.|n• Clicca |cffffffff{UI:SIGN_UP}|r, spunta il tuo ruolo e aspetta che il leader ti inviti.|n|n|cffffcc00Crea il tuo gruppo|r|n• Stesso posto: clicca |cffffffff{UI:START_A_GROUP}|r, scegli il dungeon della tua key, scegli uno stile di gioco (|cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r va bene) e clicca |cffffffff{UI:LIST_GROUP}|r.|n• Imposta la difficoltà del dungeon su |cffffffffMythic|r prima di entrare.|n• Dentro, chi ha la key clicca la |cffffffffFont of Power|r vicino all'ingresso, inserisce la key e preme |cffffffff{UI:CHALLENGE_MODE_START_CHALLENGE}|r. Dopo un conto alla rovescia di 10 secondi parte il timer.|n|n|cffffcc00Durante la run|r|n• Da +2 a +5 una morte non costa tempo, e i nemici segnati ti mostrano un percorso. Da +6 ogni morte costa tempo.|n• Da +5 si aggiunge una regola extra della settimana. La scheda |cffffffff{UI:CHALLENGES}|r nel Group Finder mostra quale.|n• In tempo: la tua key sale di 1-3 livelli. Troppo tardi: ricevi comunque loot, ma la key scende di 1 livello. In entrambi i casi passa a un altro dungeon.|n• Devi fermarti? Scrivi |cffffffff/abandon|r per avviare un voto. Se esci e basta, puoi essere segnato come Keystone Deserter.|n• Alla fine ognuno apre la cassa per il proprio loot.|n|n|cffffcc00Aiuto|r|n• Dillo nel gruppo: 'first time in this dungeon' (prima volta in questo dungeon). Sulle key basse quasi tutti spiegano volentieri.|n• Chiedi alla tua gilda, o cerca in |cffffffff{UI:COMMUNITIES_GUILD_FINDER}|r e |cffffffffFind a Community|r nella finestra Guild & Communities (J).|n• Il tuo |cffffffff{UI:DUNGEON_SCORE}|r è nella scheda {UI:CHALLENGES}. Molti leader guardano anche il punteggio Raider.IO.|n|nMidnight Helper ti aiuta dentro: i consigli sui boss si aprono quando entri, e |cffffffff/mh mplus|r mostra la tua run migliore per ogni dungeon e dove una key aggiunge di più.",
	CODEX_AGGRO_TITLE = "Aggro: chi sta colpendo il nemico?",
	CODEX_AGGRO_BODY = "Aggro significa che un nemico ti sta attaccando. Il tank lo vuole; un DPS o un healer che lo prende spesso muore. Il gioco può già avvisarti, ma per molti giocatori questi avvisi sono disattivati. Midnight Helper non ne cambia nessuno per te: scrivi |cffffffff/mh aggro|r per vedere come sono impostati i tuoi.|n|n• |cffffffff{UI:NAMEPLATE_OPTIONS_LABEL} > {UI:UNIT_NAMEPLATES_THREAT_DISPLAY}|r: spunta |cffffffff{UI:UNIT_NAMEPLATES_THREAT_DISPLAY_FLASH}|r. La nameplate di un nemico lampeggia quando il tank lo perde o quando un DPS o un healer lo prende.|n• |cffffffff{UI:COMPACT_UNIT_FRAME_PROFILE_DISPLAYAGGROHIGHLIGHT}|r (riquadri di incursione): un bordo rosso attorno a chi ha l'aggro. Comodo per i healer.|n• |cffffffff{UI:ACCESSIBILITY_AUDIO_LABEL} > {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} > {UI:CAA_SAY_IF_TARGETED_LABEL}|r: una voce ti avvisa quando un nemico ti prende come bersaglio. Attiva prima {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL}; questa opzione viene salvata per specializzazione.|n|nUsi un addon per le nameplate come Plater? Allora il lampeggio sulle nameplate viene da quell'addon, non dal gioco: guarda nelle sue impostazioni.",

	CODEX_RAID_VAULT_TITLE = "Raid Great Vault",
	CODEX_RAID_VAULT_BODY = "• I boss d'incursione riempiono la riga Incursioni della vault: 2, 4 e 6 boss aprono una, due e tre scelte. Conta ogni difficoltà, anche Raid Finder, e anche il boss della Lair.|n• Nella Stagione 2 ogni scelta viene da una difficoltà sopra quella in cui hai ucciso i boss: Raid Finder dà Champion, Normale dà Hero, Eroico dà Myth, Mitico dà Myth a un livello più alto.|n• Difficoltà miste: ogni scelta usa la difficoltà più alta in cui hai raggiunto quel numero di boss. L'UI della vault mostra cosa hai questa settimana.|n• I crest sono ciò che spendi dopo per potenziare il gear d'incursione.",

	CODEX_VAULT_ADVISOR_TITLE = "Vault Advisor della Gran Banca",
	CODEX_VAULT_ADVISOR_BODY = "• Pannello laterale accanto alla finestra Gran Banca di Blizzard quando scegli la tua ricompensa alla Gran Banca a Silvermoon — non dentro le schede di Midnight Helper. SHIFT-J mostra solo un riepilogo, quindi lì il pannello non compare.|n• Classifica i pezzi della vault rispetto al gear equipaggiato usando le priorità di stat della guida (e Pawn opzionale).|n• Attiva/disattiva nelle impostazioni rapide della minimappa / Esc -> AddOns -> Midnight Helper.|n• Profilo Auto vs Incursione vs M+ per i pesi delle stat.",

	CODEX_WORLD_HUB_TITLE = "Void & Rituals — un unico sistema",
	CODEX_WORLD_HUB_BODY = "• Dalla patch 12.0.5, |cffffffffRitual Sites|r e |cffffffffVoid Assaults|r funzionano come un unico sistema. Entrambi si spostano ogni settimana tra Eversong Woods e Zul'Aman, e condividono un'unica currency e un unico renown.|n• Stesse |cffffffffField Accolades|r e hub Bazaar — non farmarli come attività scollegate.|n• La Season 2 ha abbassato l'equipaggiamento che compri con le Field Accolades ad Avventuriero e Veterano: comodo per un personaggio nuovo, non per il gear migliore.|n• Apri la scheda combinata per il sito e la zona attivi di questa settimana, le tue Field Accolades e il renown, e i pulsanti di percorso.",

	CODEX_RITUAL_TITLE = "Ritual Sites",
	CODEX_RITUAL_BODY = "• Un rituale istanziato per 1-5 giocatori. Ogni settimana si trova in uno di due posti: Daggerspine Point in Eversong Woods o il Broken Throne a Zul'Aman. Scegli un tier e completalo per accolades, renown e loot.|n• Solo un sito è attivo alla volta; l'addon evidenzia quale.|n• Il pin di Ritual Site nella SMC City Guide imposta un percorso verso il sito attivo di questa settimana. Se l'addon non lo conosce ancora, il pin apre la scheda Void & Rituals.",

	CODEX_VOID_TITLE = "Void Assaults",
	CODEX_VOID_BODY = "• Il Vuoto attacca Eversong Woods o Zul'Aman — uno dei due ogni settimana. Completa i Void Strikes; quando ne fai abbastanza parte una Void Incursion più grande. Entrambi danno Field Accolades.|n• Condivide le Field Accolades e il renown dei Ritual Sites con i Ritual Sites — porti avanti entrambi insieme.|n• La scheda Void & Rituals mostra la zona di questa settimana, quella della prossima e la tua quest settimanale.",

	CODEX_RARES_TITLE = "Midnight rares",
	CODEX_RARES_BODY = "• Mob rari settimanali con loot per account/personaggio (controlla in-game le regole di ogni rare).|n• Scheda |cffffffffRares|r: traccia le uccisioni e crea un percorso, prima il rare più vicino. La freccia del percorso (quella di Midnight Helper, o quella di TomTom se lo usi) passa poi al successivo più vicino.|n• Avviso in tempo reale quando un rare tracciato è vicino (~500 yd) — attiva/disattiva nelle impostazioni.",

	CODEX_PROF_TITLE = "Professioni — ciclo settimanale",
	CODEX_PROF_BODY = "• Ogni professione ha i suoi |cffffffffpunti Conoscenza (KP)|r e la sua |cffffffffGrinta dell'Artigiano|r: la Grinta di Alchemy compra solo cose di Alchemy.|n• |cffffffffOgni settimana, per professione:|r la quest settimanale del tuo trainer a Silvermoon (dalla skill 25), i |cffffffffPatron orders|r al tavolo dei Crafting Orders che danno Conoscenza (la fonte settimanale più grande), fino a due oggetti Conoscenza da tesori normali nelle zone di Midnight, e un Thalassian Treatise (fatto con Inscription).|n• Raccoglitori ed Enchanter ottengono oggetti Conoscenza anche raccogliendo o disincantando. Con quelli recuperi una settimana persa; con la maggior parte delle altre fonti settimanali no.|n• |cffffffffAbundance|r è una traccia a parte: uno Shard of Dundun (al massimo 8 a settimana) avvia un Abundant Harvest, che dà Unalloyed Abundance.|n• Scheda |cffffffffProfessioni|r: KP non spesi, i tuoi Shards of Dundun e pin sulla mappa per tesori e libri. Dove spendere i KP: la guida Basics.",

	CODEX_PROF_GUIDE_TITLE = "Professions beginner guide",
	CODEX_PROF_GUIDE_BODY = "• Sotto-scheda |cffffffffBasics -> Professioni|r: piano KP passo passo e suggerimenti di combo.|n• La sotto-scheda |cffffffffCrests|r parla dei crest: la currency con cui potenzi l'equipaggiamento, guadagnata da tante attività — non solo dalle incursioni.|n• Rileggi dopo le patch — numeri e cap possono cambiare.",
	CODEX_PROFRESET_TITLE = "Azzerare le specializzazioni di una professione (12.1)",
	CODEX_PROFRESET_BODY = "• La patch 12.1 permette di annullare le scelte di specializzazione Midnight — una volta per professione.|n• |cffffffffDa chi:|r Theremis, nel Bazaar di Silvermoon accanto agli ordini di artigianato. Offre una riga per professione, quindi puoi azzerare Blacksmithing e lasciare Enchanting intatto.|n• |cffffffffCosa recuperi:|r ogni punto Conoscenza speso negli alberi Midnight di quella professione, libero di essere ridistribuito.|n• |cffffffffQuanto costa:|r l’avviso del gioco dice “You will lose all associated recipes”.|n• |cffffffffAssociate, non tutte.|r Sparisce ciò che quelle specializzazioni avevano sbloccato. Le ricette imparate da un maestro, da un bottino o da una missione stanno fuori dagli alberi e restano. Osservato su un Enchanting azzerato: la lista delle ricette era intatta e la Conoscenza spesa era tornata sul contatore.|n• |cffffffffÈ una volta sola.|r La conferma scrive ONCE in maiuscolo, e vale per professione — nessun secondo tentativo se la nuova strada delude.|n• Decidi |cffffffffprima|r di confermare. La pagina Professioni indica l’albero da riempire e il nodo esatto.|n• Le ricette tolte tornano se ridistribuisci in modo identico? Il gioco non lo dice mai. Conta che non sia così.",
	CODEX_MIDSTART_TITLE = "Iniziare la campagna Midnight",
	-- ⚠️ Silvermoon resta in inglese, come dice l'intestazione di itIT.lua: i nomi di zona
	-- sono nomi propri di Blizzard e non si traducono in questo pack.
	CODEX_MIDSTART_BODY = "|cffffcc00Al livello 80 la missione |r|cffffffffMidnight|r|cffffcc00 arriva da sola.|r Non devi cercare niente: finisce nel tuo diario nel momento in cui diventi 80. Sotto l'80 puoi già viaggiare fino a Silvermoon, ma lì non c'è ancora nulla da accettare.|n|n|cffffff78Dove comincia|r|n• Parla con l'|cffffffffImage of Lady Liadrin|r. Si trova in più di una capitale, quindi anche nella tua.|n• Offre due cose: guardare l'introduzione, oppure |cffffffffI have heard this tale before|r per saltarla.|n|n|cffffff78Saltarla non ti costa nulla|r|n• Esci a |cffffffffSilvermoon|r e la missione successiva ti viene data subito.|n• Dietro l'introduzione non c'è nulla di bloccato: percorsi, punti della città e routine settimanale funzionano allo stesso modo.|n|n|cffffff78Scegliere da dove partire|r|n• Quella missione successiva, |cffffffffAdventuring in Midnight|r, ti manda alla |cffffffffScouting Map|r nel Sanctum of Light.|n• Cinque punti di partenza: |cffffffffArator's Journey|r, |cffffffffEversong|r, |cffffffffZul'Aman|r, |cffffffffVoidstorm|r e |cffffffffHarandar|r.|n• Passaci sopra il mouse per sapere cosa ti aspetta; il clic apre solo il suo scouting report. |cffffffffGuardare non costa nulla.|r|n|n|cffffcc00Scelto e poi ripensato?|r La scelta nasconde gli altri quattro finché quella missione resta nel diario — ma |cffffffffabbandona la missione|r e tornano tutti e cinque. Decide il tuo ordine, non il tuo percorso.",
	CODEX_CORRPOWER_TITLE = "Corrosive Codex — quale gift prendo per primo?",
	CODEX_CORRPOWER_BODY = "|cffffcc00Dodici gift, e ne puoi usare uno.|r Ognuno costa |cffffffff8 Corrosive Souls|r, quindi tutti e dodici insieme ne costano 96. Siccome il prezzo è uguale per tutti, la tua prima scelta riguarda |cffffffffcosa ti serve|r — mai cosa puoi permetterti.|n|n|cffffff78Una cosa sola spiega tutto il sistema|r|n• È un |cffffffffciclo di veleno|r. Metà dei gift diventa più forte contro un nemico Poisoned, o mentre |cffffffffsei tu|r a essere avvelenato.|n• Per questo ogni buona coppia è |cffffffffun gift che avvelena + un gift che ne approfitta|r. Una volta che lo vedi, le combinazioni smettono di sembrare casuali.|n|n|cffffff78Quale per primo? Scegli in base al tuo problema, non a una classifica|r|n• |cffffffffVoglio solo fare più danno|r → |cffffffffUla'tek's Gift|r. Funziona da solo, senza un secondo gift e senza preparazione. Tutte le guide che abbiamo letto lo mettono per primo.|n• |cffffffffI gruppi di nemici durano troppo|r → |cffffffffPlague of Corrosion|r o |cffffffffOphidian Maw|r.|n• |cffffffffMuoio in continuazione nelle delve|r → |cffffffffVirulent Mucus|r assorbe i colpi grossi, |cffffffffGorgoneion Gaze|r pietrifica tutto intorno a te appena scendi sotto metà vita.|n• |cffffffffI caster riescono a lanciare|r → |cffffffffAccursed Poison|r. Ne interrompe uno per te.|n|n|cffffcc00Attenzione a Mephitic Cloud.|r Permette ai |cffffffffnemici|r colpiti di curare ciò che stanno attaccando. In gruppo lavora contro di te.|n|n|cffffff78Cosa abbiamo misurato noi e cosa no|r|n• |cffffffffDal gioco:|r il prezzo di 8 e il testo completo di Ula'tek's Gift. Quelli sono nostri.|n• |cffffffffDalle guide:|r l'ordine qui sopra e quanti gift aprono il secondo slot. Il gioco dice solo \"until your offerings are sufficient\" e non dà nessun numero. |cffffffffSei fonti dicono 8|r — tra cui la pagina dell'incantesimo di Wowhead, che lo mette in tabella — e un blog dice 6. Quindi 8 è quasi certamente giusto; semplicemente non l'abbiamo visto di persona. Lo saprai nel momento in cui comparirà il tuo secondo slot.|n• Ula'tek's Gift è |cffffffffgià stato indebolito una volta|r. Una classifica di agosto non è automaticamente vera oggi — ed è proprio per questo che il ciclo di veleno qui sopra è la parte da ricordare.",
	CODEX_ATALUTEK_TITLE = "Le Vaults of Atal'Utek — cosa c'è dentro, e dove",
	CODEX_ATALUTEK_BODY = "|cff8fd3ffPer cominciare|r|n|n• |cffffffffCos'è:|r una zona della 12.1 sulla Coiled Isle con una mappa propria, e sotto di essa una seconda mappa, la Underbelly. È già aperta — nessun blocco stagionale.|n|n• |cffffffffCome si entra:|r una catena di quattro missioni — |cffffffffInto the Vaults of Atal'Utek|r, poi |cffffffffVaults of Atal'Utek: One Coin Too Many|r e |cffffffffVaults of Atal'Utek: A Toxic Tour|r, che ricevi insieme, poi |cffffffffVaults of Atal'Utek: The Altar of Corrosion|r. Tutto quello che segue sta dietro a queste, quindi falle per prime. |cffffffffA Toxic Tour è una missione della storia che si fa una volta sola, non una daily|r — chiede una Patrol, uno Strike, una Incursion e un Ancient Foe, quindi si completa da sola mentre fai il giro descritto qui sotto.|n|n|cff8fd3ffCosa si fa qui|r|n|n• |cffffffffCosa fai davvero qui — quattro cose, e si alimentano a vicenda.|r Le |cffffffffTemple Patrols|r girano per la mappa e ruotano circa ogni dieci minuti; sono la cosa più facile a cui unirsi e ce n’è quasi sempre una attiva. Le |cffffffffTemple Strikes|r sono più grosse e preparano un’incursione. Fatte abbastanza Strikes parte una |cffffffffTemple Incursion|r, e ogni Incursion finisce risvegliando un |cffffffffAncient Foe|r — è da lì che arrivano i tre rari elite: solo uno di loro a settimana, con dieci minuti di orologio. Monete, chiavi, equipaggiamento e reputazione escono tutti da quel ciclo. Se ti chiedi cosa fare: unisciti a quello che sta girando.|n|n• |cffffffffMa come si trova davvero un Temple Strike?|r Apri la mappa dentro le Vaults e cerca le icone degli eventi — uno Strike è segnato lì come qualsiasi evento di zona, e |cffffffffnon ha un timer|r: resta lì finché un gruppo non lo completa, quindi puoi andarci con calma. |cffffffffBastano pochi giocatori|r; non serve un gruppo organizzato e di solito c’è già qualcuno. Sono sei, ognuno con un punto di partenza fisso — cliccane uno per un waypoint: {WAY:2509:50.55:15.70:Cursed Depths} · {WAY:2509:47.36:46.17:Overflowing Venom} · {WAY:2509:47.67:46.34:Profane Pyres} · {WAY:2509:47.26:26.69:Purifying Earth and Sky} · {WAY:2509:39.32:39.92:Ruuk’Jar’s Clutch} · {WAY:2613:52.25:36.27:The Underbelly}.|nSe la mappa non mostra nessuno Strike, probabilmente in questo momento è in corso una Incursion o il suo Ancient Foe — unisciti a quello. Un nuovo Strike compare quando è finito.|n|n• |cffffffffCome ti muovi dentro.|r Gli |cffffffffAmani Windcallers|r ti portano tra tre punti delle Vaults — l’hub |cffffffffAmani Foothold|r, l’Eastern Amani Outpost e il Northern Amani Bulwark. Il maestro di volo |cffffffffEagletender Mal’Tiki|r sta a {WAY:2509:44.42:62.21:Amani Foothold}. Dentro le Vaults non si può volare, ed è esattamente per questo che ci sono — è più grande di quanto sembri, e andare a piedi è la via lenta.|n|n• |cffffffffLe missioni ripetibili — una settimanale e otto giornaliere.|r |cffffffffPurging the Vaults|r da |cffffffffWarleader Abdumati|r nell'Amani Foothold è la settimanale da non saltare. Le otto giornaliere sono |cffffffffPatrolling the Temple|r, |cffffffffBounty of the Cursed|r, |cffffffffRelentless Strikes|r, |cffffffffDecisive Incursions|r, |cffffffffFrom Whence it Came|r, |cffffffffEssence of Malice|r, |cffffffffWhat's Out There?|r e |cffffffffShoulder to Shoulder|r — prendi quelle che la mappa ti offre oggi. La maggior parte chiede le attività qui sopra, quindi si spuntano da sole mentre giochi. Due vogliono che tu sia in un gruppo (What's Out There? e Shoulder to Shoulder): bastano le persone che ti stanno già accanto, non serve un premade. E una che qui non troveresti mai: |cffffffffMidnight: Vaults of Atal'Utek|r è una meta settimanale di questo posto che si prende a |cffffffffSilvermoon|r.|n|n|cff8fd3ffCoin and Soul|r|n|n• |cffffffffCorrosive Coin|r è la currency della zona. Parole del gioco: “Spirits of the Amani within the Vaults of Atal'Utek deal exclusively in this phantasmal token.” Il tuo saldo è il numero sopra questo articolo.|n|n• |cffffffffCorrosive Soul non è quella.|r Non è affatto una currency ma un |cffffffffoggetto|r nelle tue borse, ed è ciò che il Corrosive Codex ti chiede di offrire. Le guide scambiano di continuo i due nomi; il gioco mai. Se qualcosa ti dice di spendere Corrosive Coins al Codex, è quello lo scambio.|n|n• |cffffffffDove finiscono le monete — due posti, entrambi da Er’inye|r a {WAY:2509:51.10:62.76:Er'inye}. Parlarle compra |cffffffffCorrode Spirit|r, che alimenta l’albero dell’altare; accanto a lei lo |cffffffffSkull of Er’inye|r è un mercante con tre pagine di cavalcature, mascotte, completi e ricette, da 500 a 25.000 monete. |cffffffffIl prezzo del corrode sale a ogni acquisto|r — visto a 1.500 e poi 2.000 in una visita — quindi leggi la finestra invece di risparmiare per una cifra.",
	CODEX_ATALUTEK_DISC_TITLE = "Altar of Corrosion: le quattro chiavi",
	CODEX_ATALUTEK_DISC_BODY = "• |cffffffffL'Altar of Corrosion|r è l'albero di nodi che apre l'ultima missione della catena. Gran parte si sblocca spendendo, ma |cffffffffquattro nodi stanno dietro a una chiave che devi andare a trovare|r — e tutti e quattro funzionano allo stesso modo: cade un oggetto, lo usi su un oggetto fisso da qualche parte nelle Vaults, quello dà un oggetto missione, ed Er’inye fa il resto.|n|cffffffffCorroded Key|r → il Venom-Worn Coffer → |cffffffffRun of the Vaults|r (Glideways, oppure Swift Steps) · |cffffffffSpirit Loupe|r → la Feather of Tok’jara a {WAY:2509:48.46:25.80:Feather of Tok'jara} → |cffffffffSpectral Winds|r (Spirit Walk, oppure Spectral Shipping) · |cffffffffExcising Knife|r → l'Eye of Szarith, in una pozza di veleno nella Underbelly → |cffffffffBroodmaster|r (+100% danni alle uova, oppure −75% danni dalle esplosioni delle uova) · |cffffffffDispelling Charm|r → Jin’tal’s Reliquary nel Profaned Mausoleum → |cffffffffSpiritual Protection|r (alleati spettrali ai Curse Surge, oppure rialzarti subito se muori fuori dalle Vaults).|n|cffffffffMostrare una chiave a Er’inye non sblocca nulla.|r È cieca, e ti dice cosa sente — è un indizio su dove va quell'oggetto. |cffffffffDa dove arrivano le chiavi|r — ora le guide sono d'accordo: la Corroded Key dalle Temple Strikes, l'Excising Knife da una Temple Incursion, la Spirit Loupe da un Ancient Foe. Il |cffffffffDispelling Charm|r è l'eccezione: non arriva dagli eventi, ma da Jin’tal nel Vault of Restless Bones, durante una linea di missioni secondaria sui Med’jai.|n|n• |cffffffffSpendi subito le prime monete nell’albero.|r I suoi primi quattro nodi non costano nulla e si aprono mentre spendi altrove, e alzano la Corrosive Coin che guadagni del |cffffffff25, 50, 75 e infine 100 per cento|r. L’albero si ripaga da solo, quindi ogni giro dopo il primo rende di più — risparmiare è la scelta costosa. E nota l’asimmetria che detta il ritmo della zona: |cffffffffle monete non hanno tetto|r, le Corrosive Souls sì. Farma monete liberamente; non pianificare una serata intorno alle souls.",
	CODEX_ATALUTEK_DEAD_TITLE = "The Honored Dead e i rari",
	CODEX_ATALUTEK_DEAD_BODY = "• |cffffffff“The Honored Dead” — dodici memoriali|r sulla mappa delle Vaults, un obiettivo, ed è la cosa più chiara da andare a fare qui. In un unico percorso, dall'alto della mappa verso il basso:|n{WAY:2509:46.79:7.51:To a sister 46.79, 7.51} · {WAY:2509:56.49:22.88:To a shield-bearer 56.49, 22.88} · {WAY:2509:47.22:28.77:To a father 47.22, 28.77} · {WAY:2509:42.57:33.18:To a stranger 42.57, 33.18} (sotto il ponte) · {WAY:2509:52.91:33.90:To a captain 52.91, 33.90} · {WAY:2509:55.62:40.60:To a dream 55.62, 40.60} · {WAY:2509:42.84:39.93:To sons 42.84, 39.93} · {WAY:2509:52.21:45.12:To a lover 52.21, 45.12} · {WAY:2509:38.50:47.66:To Comrades 38.50, 47.66} · {WAY:2509:55.31:48.45:To parents 55.31, 48.45} · {WAY:2509:49.50:56.59:To a daughter 49.50, 56.59} · {WAY:2509:45.81:61.79:To Failure 45.81, 61.79}|n|n• |cffffffffLa Underbelly|r è la mappa sottostante, si entra a {WAY:2509:47.30:11.20:The Underbelly} sulla mappa delle Vaults. Là sotto vive un raro, |cffffffffSzarith the Fanged|r a {WAY:2613:38.40:17.69:Szarith the Fanged}, e la Underbelly ha un obiettivo tutto suo, |cffffffffSoft Underbelly|r. |cffffffffSzarith da solo non basta:|r secondo le guide l'obiettivo chiede anche diversi elite con nome che compaiono solo mentre è in corso la Temple Strike |cffffffffThe Underbelly|r.|n|n• |cffffffffTre rari elite sulla mappa principale|r — Congealed Malice, Khu'tulak e Susarikk — formano un terzo: |cffffffffOppose the Foes|r. |cffffffffNon hanno un punto fisso, e questa è la risposta, non una lacuna|r: uno dei tre si sveglia nel momento in cui viene completata una |cffffffffTemple Incursion|r, e hai circa dieci minuti per ucciderlo. |cffffffffOgni settimana solo uno dei tre è nella rotazione|r, quindi questo obiettivo richiede almeno tre settimane. Non vai a cercarli — finisci le Incursion, e quello della settimana arriva da te.",
})

merge(ns._mhLocales and ns._mhLocales.nlNL, {
	TAB_CODEX = "Midnight Codex",
	CODEX_PANEL_TITLE = "Midnight Codex",
	CODEX_PANEL_INTRO = "Jouw Midnight-handboek — wat elk systeem is, welke currency waarvoor dient, en waar je in deze addon moet klikken. Hover currency-iconen voor Blizzard-tooltips.",
	CODEX_OPEN_TAB_FMT = "Open: %s",
	CODEX_NAV_DELVES_VAULT = "Tab Delves & Vault (Great Vault-blok)",
	CODEX_NAV_DELVES_MIDNIGHT = "Tab Delves & Vault (delve-lijst)",
	CODEX_NAV_BASICS_DAWN = "Categorie Basics (Crests)",
	CODEX_NAV_BASICS_PROF = "Tab Basics (Professions-gids)",
	CODEX_BALANCE_FMT = "Je hebt: |cffffffff%d|r",
	CODEX_BALANCE_UNKNOWN = "Saldo werkt bij na inloggen op dit personage.",
	CODEX_SEARCH_OPENED = "Midnight Codex geopend.",
	CODEX_BETA_DISABLED = "Midnight Codex staat uit in Instellingen (beta-tabs).",

	CODEX_CAT_START = "Start Here",
	CODEX_CAT_WEEKLY = "Weeklijkse loop",
	CODEX_CAT_CURRENCIES = "Currencies",
	CODEX_CAT_DELVES = "Delves",
	CODEX_CAT_DUNGEONS = "Dungeons & M+",
	CODEX_CAT_RAID = "Raid & crests",
	-- ⚠️ Was "Void & Rituals" until 19 aug, and half of what sits under it is neither.
	-- The category holds Prey hunts, rares, Turbulent Timeways and Showdowns alongside
	-- the void and ritual articles. Rob went looking for Prey, read that button, and
	-- walked straight past it — the same class of fault as the twelve type-only commands
	-- on 18 aug: the feature was there, under a name nobody would guess.
	CODEX_CAT_WORLD = "Wereldcontent",
	CODEX_CAT_COILEDISLE = "Coiled Isle",
	CODEX_ROUTE_BTN = "Volg de route",
	CODEX_CAT_PROFESSIONS = "Professions",

	CODEX_START_TITLE = "Start Here — jouw Midnight-week",
	CODEX_START_BODY = "|cffffcc00Denk in lagen:|r één weekly reset, meerdere beloningslijnen. Je hoeft niet alles elke dag te doen — kies een doel.|n|n|cffffff781) Account & reset|r|n• Check tab |cffffffffThis Week|r voor vault, world boss, keys en weektaken.|n• |cffffffffAccount snapshot|r toont al je alts (vault, Delver's Call, profession-weeklies).|n|n|cffffff782) Combat content|r|n• |cffffffffDelves|r — hoofdgear-track (keys, tiers, Great Vault-slots). Gebruik |cffffffffDelve Coach|r voor tips per delve.|n• |cffffffffMythic+|r en |cffffffffRaid|r vullen andere vault-slots (zie categorieën Dungeons & Raid).|n|n|cffffff783) Open wereld|r|n• |cffffffffCoiled Isle|r — de Season 2-zone uit patch 12.1, met een eigen categorie hier.|n• |cffffffffPrey|r-hunts tellen voor dezelfde Great Vault-rij als delves.|n• Tab |cffffffffVoid & Rituals|r — Field Accolades, Ritual Sites, Void Assaults (zelfde renown).|n• Tab |cffffffffRares|r — weekly rare loot en routes.|n|n|cffffff784) Crafting|r|n• Tab |cffffffffProfessions|r voor KP / weekly mats; |cffffffffBasics|r voor crests.|n|n|cffffcc00Tip:|r open de categorie |cffffffffCurrencies|r als je een token bent vergeten. Scroll op het baas-beeld in Delve Coach om te zoomen.",
	CODEX_MIDSTART_TITLE = "De Midnight-campagne beginnen",
	CODEX_MIDSTART_BODY = "|cffffcc00Op level 80 komt de quest |r|cffffffffMidnight|r|cffffcc00 vanzelf binnen.|r Je hoeft er niets voor te zoeken — hij staat in je log op het moment dat je 80 wordt. Onder 80 kun je al wél naar Silvermoon reizen, maar er valt daar nog niets aan te nemen.|n|n|cffffff78Waar het begint|r|n• Praat met de |cffffffffImage of Lady Liadrin|r. Ze staat in meerdere hoofdsteden — Dornogal, Stormwind en Orgrimmar hebben haar alle drie.|n• Ze biedt twee dingen: de introductie kijken, of |cffffffffI have heard this tale before|r om hem over te slaan.|n|n|cffffff78Die skip kost je niets|r|n• Je komt uit in |cffffffffSilvermoon City|r en krijgt de volgende quest meteen aangereikt.|n• Er zit niets achter de introductie op slot — routes, stadspins en de weekroutine werken precies hetzelfde.|n|n|cffffff78Kiezen waar je begint|r|n• Die volgende quest, |cffffffffAdventuring in Midnight|r, stuurt je naar de |cffffffffScouting Map|r in het Sanctum of Light.|n• Vijf startpunten: |cffffffffArator's Journey|r, |cffffffffEversong|r, |cffffffffZul'Aman|r, |cffffffffVoidstorm|r en |cffffffffHarandar|r.|n• Hover erover voor een regel over wat er te doen is; klikken opent alleen het scouting report. |cffffffffKijken kost niets.|r|n|n|cffffcc00Gekozen en toch getwijfeld?|r Kiezen verbergt de andere vier zolang die quest in je log staat — maar |cffffffffabandon de quest|r en ze staan alle vijf weer open. Het bepaalt je volgorde, niet je pad.",
	CODEX_WARBAND_TITLE = "Warband & de Warband Bank",
	CODEX_WARBAND_BODY = "|cffffcc00Je Warband|r is elk personage op je account, als één team. Veel dingen zijn nu |cffffffffWarbound|r — account-breed gedeeld — dus je mailt veel minder tussen alts.|n|n|cffffff78Warbound items & currencies|r|n• Sommige currencies zijn account-breed of kun je tussen personages verplaatsen — je currency-venster laat zien welke. Upgrade-crests tellen per personage.|n• Gear is vaak |cffffffffWarbound tot uitgerust|r — stuur het naar een alt, maar zodra het uitgerust is hoort het bij dat personage.|n|n|cffffff78De Warband Bank|r — een gedeelde bank die al je personages gebruiken.|n• Open 'm bij |cffffffffelke bankier|r (of Jeeves) — het is een tabblad op je gewone bank, naast je character-bank.|n• Bewaar elk |cffffffffniet-soulbound|r item, en stort of neem |cffffffffgoud|r op tussen personages (ook cross-factie).|n• Craft er direct uit — het telt als reagent-bron.|n|n|cffffff78Tabs & kosten|r — 5 tabs, 98 slots elk (490 totaal). Je begint met geen; koop ze met goud:|n• Tab 1: |cffffffff1.000g|r|n• Tab 2: |cffffffff25.000g|r|n• Tab 3: |cffffffff100.000g|r|n• Tab 4: |cffffffff500.000g|r|n• Tab 5: |cffffffff2.500.000g|r  (alle vijf = 3.126.000g)|n|n|cffffcc00Tip:|r 2-3 tabs is voor de meeste spelers genoeg. Verwar 'm niet met je |cffffffffcharacter-bank|r (sinds patch 11.2 ook met tabs, veel goedkoper) — die is per personage; de Warband Bank is gedeeld.",

	CODEX_WEEKLY_RESET_TITLE = "Weekly reset",
	CODEX_WEEKLY_RESET_BODY = "• Het meeste weekly progress reset op onderhoudsdag (EU woensdag ochtend, US dinsdag ochtend).|n• Great Vault, world boss en veel weekly caps resetten.|n• Tab |cffffffffThis Week|r toont tijd tot reset als de API dat geeft.|n• Plan alts: de |cffffffffAccount snapshot|r vergelijkt wie nog een vault-beloning, keys of Delver's Calls open heeft.",

	CODEX_VAULT_TITLE = "Great Vault",
	CODEX_VAULT_BODY = "• Drie rijen: |cffffffffWorld|r (delves, Prey en andere world-activiteiten), |cffffffffDungeons|r (Heroic, Mythic, Mythic+ en Timewalking), |cffffffffRaid|r (raid-bazen op elke moeilijkheid, en de Lair-baas).|n• Elke rij opent tot drie keuzes: World bij 2/4/8 activiteiten, Dungeons bij 1/4/8, Raid bij 2/4/6 bosses.|n• Elke keuze is zo goed als de zwakste run die ervoor nodig was: de keuze voor 4 runs gebruikt je 4e beste run van de week, die voor 8 runs je 8e beste. Eén zware key tilt alleen je eerste Dungeons-keuze op.|n• Season 2: een raid-keuze komt één stap boven wat je versloeg — Normal-kills geven een Hero-track item, Heroic-kills een Myth-track item.|n• Na reset kies je |cfffffffféén|r beloning in totaal uit al je open keuzes, bij de Great Vault in Silvermoon. SHIFT-J toont alleen een overzicht.|n• Met 3 of meer open keuzes, uit welke rijen ook, mag je in plaats van een item een |cffffffffNebulous Voidcore|r (bonus roll) nemen.|n• |cffffffffVault Advisor|r (op Blizzard vault-UI) rangschikt opties vs je gear.|n• In de addon staat de World-rij op tab |cffffffffDelves & Vault|r — klap |cffffffffWeekly Great Vault (World)|r open. Hover een personage in de |cffffffffAccount snapshot|r om alle drie rijen te zien.|n• Samenvatting ook op tab |cffffffffThis Week|r.",

	CODEX_WORLDBOSS_TITLE = "World boss (Midnight)",
	CODEX_WORLDBOSS_BODY = "• Eén roterende world boss per week (Lu'ashal, Cragpine, Thorm'belan, Predaxas), als world quest met een schedel op de kaart. Je hoeft niets op te halen.|n• Lady Liadrin in Silvermoon biedt soms |cffffffffMidnight: World Boss|r aan als een van haar vier weekkeuzes; de boss van deze week verslaan maakt hem af.|n• Warband-loot: killt één char, alts tonen klaar.|n• Bovenaan |cffffffffDelves & Vault|r met TomTom-route.|n• Ook via SMC City Guide in Silvermoon.",
	CODEX_FOLIO_TITLE = "Omnium Folio (12.0.7)",
	CODEX_FOLIO_BODY = "• Power-systeem uit patch 12.0.7, nog steeds actief in 12.1 — een minimap-boek met |cffffffffrunen|r die je vrij wisselt buiten combat (geen slot nodig).|n• Power komt uit de |cffffffff'Seeking Knowledge'|r-keten (5 stappen): The Omnium Folio, Ritualized Arcana, Ley Line Assaults, Magical Primessence, Off-World Magic.|n• Elke stap levert een |cffffffffMote of Omnial Inquiry|r die de volgende rij runen opent.|n• Alle 5 af = meta-achievement + de Sunstrider Omnium Simulacrum-decor.|n• Weken gemist? Doe de gemiste quests achter elkaar om bij te komen — geen reset afwachten.|n• Alts: heeft één personage de introductie gedaan, dan kunnen de andere hem overslaan (12.1). Je rune-keuzes blijven per personage.",
	CODEX_S2_TITLE = "Een nieuw seizoen — wat het betekent",
	CODEX_S2_BODY = "• Je personage, mounts en collecties blijven allemaal — er gaat niets verloren.|n• Je gear houdt zijn item level. Gear van het nieuwe seizoen begint gewoon met hogere getallen, dus je oude stukken zijn niet langer top-end. Dat is normaal en overkomt iedereen.|n• Je Mythic+-rating begint ook opnieuw — ook voor iedereen.|n• Season 2 kwam in twee stappen: eerst patch 12.1 (de Coiled Isle, de campaign, de dungeon Altar of Fangs), een week later het seizoen zelf (raid, Mythic+, PvP, Bountiful Delves).|n• Gear upgraden kost nu |cffffffffMistcrests|r. De Dawncrests van vorig seizoen werken niet op de nieuwe gear.|n• Wat je nu doet: volg het Start Here-pad, geen haast.",
	CODEX_SEASONEND_TITLE = "Als een seizoen afloopt",
	CODEX_SEASONEND_BODY = "• |cffffffffJe gear reset niet.|r Alles wat je draagt gaat mee, op het item level dat het al heeft. Het is niet langer top-end, maar het is een echte voorsprong op dag één van het volgende seizoen. De wijziging waarbij ieders getallen wél omlaag gaan heet een squish, en die hoort bij de pre-patch van een uitbreiding — niet bij een seizoenswissel.|n• |cffffffffDe getallen schuiven, niet je voortgang.|r Elk seizoen gaan de item levels omhoog, dus een stuk dat nu maximaal is op de hoogste track zit in de nieuwe getallen meerdere tracks lager. Dat is normaal en overkomt iedereen.|n• |cffffffffBlijf je Great Vault openen tot de laatste week.|r Elke weekly is gratis gear die bepaalt waar je volgend seizoen begint.|n• |cffffffffSeizoensvaluta overleeft een wissel meestal niet ongeschonden|r — het wordt omgezet of onbruikbaar. Uitgeven is beter dan oppotten. Het gedrag verschilt per valuta en kan laat nog veranderen, dus kijk in je currency-tab in de game in plaats van op een guide te vertrouwen.|n• |cffffffffDe echte deadline zijn de seizoensgebonden dingen:|r mounts, titels en achievements van dit seizoen, en voortgangstracks die resetten. Dié zijn het waard om af te maken nu het nog kan.|n• |cffffffffVoortgangstracks resetten, maar hun beloningen zijn meestal niet weg|r — ze verhuizen daarna vaak naar een vendor zonder rang-eis, tegen een flink hogere prijs. Nu afmaken is goedkoper dan later kopen.|n• |cffffffffKies één lane.|r De laatste weken zijn kort. Eén track afmaken is beter dan drie half.",
	CODEX_PREY_TITLE = "Prey-hunts",
	CODEX_PREY_BODY = "• |cffffffffEen Prey-hunt is een gevolgde jacht, geen dungeon.|r Je pakt hem op bij Magister Astalor Bloodsworn in Murder Row, Silvermoon, volgt hem, en sluit af met een gevecht tegen één doelwit met een naam. Geen group finder. Wel een weeklimiet: alleen je eerste twee hunts per moeilijkheid per week geven een gear-kist.|n• |cffffffffHet telt mee voor de Great Vault.|r Prey vult dezelfde world-rij als delves en ritual sites, dus het is een echte manier om die beloning te vullen en geen bijzaak.|n• |cffffffffEr zijn drie moeilijkheidsmodi.|r Begin op de laagste. Een zwaardere modus geeft betere gear en een betere Great Vault-keuze. Op Normal mogen andere spelers je helpen; op Nightmare vecht je alleen.|n• |cffffffffWar Mode-hunts tellen apart.|r Speel je zonder War Mode, dan mis je niets wat de rest van het systeem nodig heeft.|n• |cffffffffDe volledige doelenlijst is een langetermijndoel, geen weektaak.|r Hem afwerken levert een titel op. Eén jacht doen wanneer je er zin in hebt is een prima manier om het te spelen.|n• |cffffffffHet opent ook een portaal, en dat vertelt niemand je.|r Kom je de Prey-lijn in, dan verbindt een portaal Astalor's Sanctum in Silvermoon rechtstreeks met The Coiled Isle — dat scheelt elke keer de lange vlucht. Midnight Helper biedt hem pas aan in de routebegeleiding als jouw personage hem echt kan gebruiken; zie je hem nog niet, ga dan verder met Prey.|n• |cffffffffHier begint het|r: {WAY:2393:56.74:67.30:Magister Astalor Bloodsworn} in Murder Row, Silvermoon. Klik erop voor een waypoint. Hij staat beneden, binnen in het gebouw. Het portaal staat naast hem, en de pin ervoor in de City Guide brengt je eerst naar de deur.|n• |cffffffffEn de weg terug|r, de helft die niemand opschrijft: {WAY:2512:58.12:48.48:Portaal naar Silvermoon} op The Coiled Isle. Op het eiland staan zonder te weten waar het portaal terug is, overkomt iedereen één keer.|n• |cffffffffWil je weten hoe je ervoor staat|r, typ dan |cffffffff/mh prey|r, of open de Adventure Guide met Shift-J. Allebei lezen je voortgang uit de game, niet uit een lijstje van ons.",
	CODEX_S2GLOSS_TITLE = "Season 2 — nieuwe termen",
	CODEX_S2GLOSS_BODY = "• |cffffffffCrest|r — een currency om gear te upgraden. In Season 2 heten ze |cffffffffMistcrests|r. Elke track (Adventurer tot Myth) heeft z'n eigen crest; je verdient ze in delves, dungeons, raids, Prey en outdoor events.|n• |cffffffffUpgrade-track|r — de ladder die een stuk gear beklimt (Adventurer, Veteran, Champion, Hero, Myth). Hogere track = hoger plafond.|n• |cffffffffTier set|r — bij elkaar horende armor-stukken. Draag er 2 of 4 en je ontgrendelt een bonus voor je spec.|n• |cffffffffCatalyst|r — verandert een gewoon stuk in een tier-stuk; in Season 2 blijven de secondary stats van het item behouden.|n• |cffffffffBountiful Delve|r — een delve met een extra kist aan het eind; die kist openen kost een Restored Coffer Key.|n• |cffffffffNemesis Delve|r — een speciale seizoensdelve met een eigen boss en beloningen.|n• |cffffffffLair|r — een world boss die je op een plek binnengaat en waar je een difficulty voor je groep kiest, als een mini-raid.|n• |cffffffffNebulous Voidcore|r — een bonus roll: geef er één uit na een boss voor een extra kans op loot. Je kunt er ook één uit de Great Vault nemen in plaats van een item, en vanaf de week van 6 oktober geeft de quest van Orin Straylight bij de Catalyst in Silvermoon er één extra per week.|n• |cffffffffItem levels per seizoen|r — nieuwe gear begint met hogere getallen, dus oude gear is niet langer top-end. Je gear zelf verandert niet. Een |cffffffffsquish|r is het omgekeerde (getallen gaan omlaag) en hoort bij de pre-patch van een uitbreiding, niet bij een nieuw seizoen.",
	CODEX_TT_TITLE = "Turbulent Timeways (12.0.7)",
	CODEX_TT_BODY = "• Terugkerend Timewalking-event — nu een |cffffffffDragonflight|r-dungeonpool: Algeth'ar Academy, Halls of Infusion, Neltharus, Ruby Life Pools, The Azure Vault, Brackenhide Hollow.|n• Weekly: doe |cffffffff5 Timewalking-dungeons|r voor een gear-kist; elke run stapelt |cffffffffKnowledge of Timeways|r (XP-buff).|n• Verdien |cffffffffMastery of Timeways|r in 4 van 6 weken voor 'Master of the Turbulent Timeways' + het |cffffffffSpawn of Vyranoth|r-mount.|n• Geef Timewarped Badges uit bij de event-vendor.|n• Loopt ~30 juni – 11 aug. (Gedataminet — bij launch bevestigen.)",

	CODEX_DELVER_CALL_TITLE = "Delver's Call",
	CODEX_DELVER_CALL_BODY = "• Eén quest per Midnight-delve: haal die delve één keer, op elke tier. Elk character kan ze elk één keer doen — ze komen niet elke week terug.|n• Ze geven veel XP, en meer naarmate je level hoger is. Tijdens het levelen: delves vroeg halen, quests laat inleveren (rond level 87-88).|n• |cffffffffAccount snapshot|r toont welke chars nog afgeronde calls hebben liggen (gebankt).|n• Hover Delver's Call in snapshot voor detail per char.",

	CODEX_ACCOUNT_TITLE = "Account snapshot",
	CODEX_ACCOUNT_BODY = "• Overzicht van chars waar je op hebt ingelogd met Midnight Helper.|n• Sorteer/filter op vault ready, keys, Dundun-cap, stale sinds reset.|n• Beantwoordt: “Welke alt heeft nog een vault-beloning, keys of Delver's Calls liggen?”|n• De world boss en de weekly quests in Silvermoon staan op tab |cffffffffThis Week|r, niet hier.|n• Vervangt niet inloggen voor gear of quest-checks.",

	CODEX_CUR_COFFER_KEY_TITLE = "Restored Coffer Key",
	CODEX_CUR_COFFER_KEY_BODY = "• Opent de |cffffffffBountiful Coffer|r aan het eind van een Bountiful delve. Om een delve in te gaan heb je er geen nodig.|n• Gemaakt van 100 Coffer Key Shards — bij het binnengaan van een delve gebeurt dat vanzelf. Vanaf Delver's Journey rank 6 koop je er ook 2 per week bij Naleidea Rivergleam in de Delver's HQ.|n• Elk character heeft z'n eigen keys. Je aantal staat op |cffffffffDelves & Vault|r; de Account snapshot toont de rest.",

	CODEX_CUR_SHARDS_TITLE = "Coffer Key Shards",
	CODEX_CUR_SHARDS_BODY = "• 100 shards worden één Restored Coffer Key. Als je een delve binnengaat, gebeurt dat vanzelf.|n• Ze komen uit de open wereld: het spel noemt treasures, world quests en outdoor events, en rares geven ze ook.|n• Weekly earn cap van 600 — 'Weekly: X / Y' op Delves-tab. Dat is zo'n zes keys per week. Delver's Journey rank 10 laat elke bron meer geven.",

	CODEX_CUR_UNDERCOIN_TITLE = "Undercoin",
	CODEX_CUR_UNDERCOIN_BODY = "• Delve-currency. Valt uit de kisten aan het eind van een delve — het meest uit Bountiful delves op hogere tiers.|n• Uitgeven doe je bij |cffffffffNaleidea Rivergleam|r in de Delver's HQ in Silvermoon: cosmetics, decor, toys en de L00T RAID-R Mini. Vanaf Delver's Journey rank 6 verkoopt ze je er ook je 2 Restored Coffer Keys per week voor.|n• Vanaf Delver's Journey rank 5 verschijnt |cffffffffZah'ran|r aan het eind van een delve van Tier 6+. Hij verkoopt Champion-gear voor Undercoin, en zijn aanbod wisselt elke run.",

	CODEX_CUR_MANA_TITLE = "Untainted Mana-Crystals",
	CODEX_CUR_MANA_BODY = "• Koopt Hero-gear bij |cffffffffZah'ran|r, de vendor die aan het eind van een delve van Tier 6+ verschijnt.|n• Pas vanaf Delver's Journey rank 9: dan kunnen Tier 11 Bountiful Coffers ze geven (of een Hero-item), en Tier 8-10 kleinere aantallen.|n• Snapshot kan totals per char tonen.",

	CODEX_CUR_ACCOLADES_TITLE = "Field Accolades",
	CODEX_CUR_ACCOLADES_BODY = "• Gedeelde currency voor |cffffffffVoid & Rituals|r: je verdient hem met Ritual Sites en Void Assaults.|n• Uitgeven doe je in de Bazaar in Silvermoon City: |cffffffffMaren Silverwing|r verkoopt gear-caches (Season 2: Adventurer-gear voor 200, Veteran-gear voor 500 willekeurig of 750 voor een slot naar keuze), |cffffffffTriam Dawnsetter|r verkoopt cosmetics.|n• Live count op tab |cffffffffVoid & Rituals|r.",

	CODEX_CUR_DAWN_TITLE = "Crests",
	CODEX_CUR_DAWN_BODY = "• De currency waarmee je gear één rang per keer upgradet: 20 crests per rang, en elke track neemt alleen zijn eigen crest. Niet gekoppeld aan je Great Vault-raidslots.|n• Crafters gebruiken ze ook: crests bepalen het item level van een gecraft stuk.|n• Live crest-saldi staan op |cffffffffBasics -> Crests|r (niet in deze lijst).|n• Tot de week van 20 oktober is er een cap. Die telt hoeveel je er deze season hebt verdiend, niet hoeveel je er nu hebt — uitgeven maakt dus geen ruimte vrij. Hij gaat elke week 100 omhoog. Vanaf de week van 20 oktober is de cap weg.|n• Niet hetzelfde als delve keys — zie die gids voor waar je ze aan uitgeeft.",
	CODEX_TRACKS_TITLE = "Gear upgrade tracks",
	CODEX_TRACKS_BODY = "• Gear heeft niet alleen een item level — het zit op een |cfffffffftrack|r. Laag naar hoog: |cffffffffAdventurer|r (groen), |cffffffffVeteran|r, |cffffffffChampion|r, |cffffffffHero|r, |cffffffffMyth|r.|n• Staat er |cffffffffHero 3/6|r op een tooltip, dan betekent dat: de Hero-track, rang 3 van 6. Elke rang die je koopt geeft item level erbij.|n• De track bepaalt je plafond — de tooltip toont het ilvl-bereik dat 'ie kan halen. Daarboven kom je alleen met een drop van een hogere track.|n• Elke track heeft z'n eigen crest-kleur. Zwaardere content dropt gear op een hogere track — zo klim je.|n• Track ontgroeid? Ruil lagere crests om bij |cffffffffVaskarn|r. Upgraden doe je bij |cffffffffCuzolth|r in Silvermoon — een rang kost de crests van die track plus een beetje goud.|n• Elke track heeft een achievement voor het ontgroeien ervan, genoemd naar de crest van dat seizoen — in Season 2 de «…of the Mist»-reeks. Die halveert de crest-kosten van die track voor je andere characters, en (Adventurer t/m Hero) mag dit character die crest bij Vaskarn omhoog ruilen: 30 voor 10 van de tier erboven.|n• Live saldi en waypoints: |cffffffffBasics -> Crests|r.",

	CODEX_DELVES_INTRO_TITLE = "Midnight delves — overzicht",
	CODEX_DELVES_INTRO_BODY = "• Korte instanced runs voor 1 tot 5 spelers, met Valeera als companion — in heel Quel'Thalas en op de Coiled Isle.|n• |cffffffffTier 1–11|r. Tier 4 en hoger vraagt level 90 en de Midnight-campagne één keer uitgespeeld op je Warband; daarna opent elke gehaalde tier de volgende.|n• Gear wordt vanaf |cffffffffTier 8|r niet meer beter: Bountiful Coffer 295, Great Vault 305 (Hero 1/6). Tier 11 geeft nog wel betere crests.|n• Naar binnen is gratis — geen key nodig. Een |cffffffffBountiful|r delve (tot vier per dag) eindigt met een Bountiful Coffer, en die kist vraagt een |cffffffffRestored Coffer Key|r.|n• Knop 'Find Nearest Bountiful Delve' op Delves-tab.",

	CODEX_DELVE_COACH_TITLE = "Delve Coach",
	CODEX_DELVE_COACH_BODY = "• Zwevend tip-venster: route, trash en boss per delve.|n• Opent vanzelf zodra je een delve in gaat, of via |cffffffffDelve Coach (preview tips)|r / |cffffffff/mh coach|r.|n• De tips staan in de taal van je spel; `/mh lang` wisselt tussen Engels en Nederlands.|n• Baas-beeld: scroll = zoom (opgeslagen per baas).|n• Blauwe spells = echte tooltips waar IDs bekend zijn.",

	CODEX_DELVE_CURIOS_TITLE = "Valeera & delve curios",
	CODEX_DELVE_CURIOS_BODY = "• Valeera heeft drie slots die je zelf vult: een |cffffffffPoison|r, een |cffffffffCombat Curio|r en een |cffffffffUtility Curio|r. Haar rol (Tank, Healer of DPS) kies je los daarvan.|n• Wisselen doe je bij de supplies aan het begin van een delve en bij het checkpoint, waar je ook repareert.|n• Season 2 heeft zes poisons: drie vanaf het begin, drie extra na Valeera's Season 2-introquests (Seasonal Refresher: Midnight, dan Slithering Spoils).|n• |cffffffff/mh curios|r laat in de woorden van het spel zien wat elke optie doet, met een ster bij wat de meeste guides kiezen. Naast haar venster opent een klein paneel met die keuzes.|n• Delve items popup voor RAID-R Mini, Trovehunter's Bounty.",

	CODEX_TORMENTS_TITLE = "Venomfall Deeps (Nemesis-delve)",
	CODEX_TORMENTS_BODY = "• De Nemesis-delve van Season 2, in het noorden van de Coiled Isle: {WAY:2512:51.23:30.26:Venomfall Deeps}. De baas is |cffffffffAzta'rec|r, op moeilijkheid |cffffffff?|r of |cffffffff??|r.|n• Vrijspelen: haal een delve van Tier 7 met minstens één leven over (voor ?), of een delve van Tier 10 met een leven over (voor ??).|n• De ingang adviseert item level 290 voor ? en 309 voor ??.|n• Alleen dit seizoen: hem verslaan geeft de achievement My Venomous Nemesis (een back-transmog); op ?? zonder andere spelers Let Me Solo Him: Azta'rec (de Apophic Soul Crusher-mount).|n• Torment's Rise en Nullaeus waren de Nemesis van Season 1.|n• Zie Delve Coach voor het gevecht.",

	CODEX_DELVE_LOG_TITLE = "Delve Log",
	CODEX_DELVE_LOG_BODY = "• Per character een logboek van elke Midnight-delve en Ritual Site-run die je afmaakt: tier, tijd en hoe vaak je doodging — bij delves ook of je een key gebruikte, en de eindbaas.|n• Dat gaat vanzelf; de tab hoeft niet open te staan.|n• Handig om te zien welke tier je het laatst haalde, en hoe lang dat duurde.|n• Op zoek naar een ingang? |cffffffffFind Nearest Delve|r staat op de tab |cffffffffDelves & Vault|r.",

	CODEX_MPLUS_TITLE = "Mythic+ & dungeon vault",
	CODEX_MPLUS_BODY = "• M+ vult de |cffffffffDungeons|r vault-rij. Heroic, Mythic 0 en Timewalking tellen daar ook mee, met een lagere beloning.|n• Hogere key = hogere ilvl in de vault. Op tijd of niet: elke afgemaakte key telt. Dit seizoen stopt het bij +10.|n• Je drie keuzes gebruiken je beste, 4e beste en 8e beste key van de week.|n• Vault Advisor heeft alleen voor healers aparte M+-stat weights; tanks en DPS krijgen voor raid en M+ dezelfde weights.|n• Geen route-addon — gebruik MDT voor affix-weken.",
	CODEX_MPLUS_START_TITLE = "Mythic+, vanaf je eerste key",
	CODEX_MPLUS_START_BODY = "Mythic+ is een gewone dungeon met een |cffffcc00Keystone|r: een sleutel met een niveau, zoals +2 of +3. Hogere keys zijn moeilijker en geven betere loot, en elke key die je afmaakt telt mee voor je |cffffcc00Great Vault|r.|n|n|cffffcc00Je eerste key|r|n• Maak een Mythic 0-dungeon af: de laatste boss geeft je een key.|n• Of loop mee met de key van iemand anders: als die klaar is, krijg jij er ook een.|n• Kwijt, of nooit gehad? |cffffffffLindormi|r in Silvermoon City, naast het portaal naar The Timeways, geeft je er een.|n• Je hebt altijd maar één key, en hij begint op +2.|n|n|cffffcc00Bij een groep aansluiten|r|n• Druk op |cffffffffI|r, open |cffffffff{UI:GROUP_FINDER}|r, dan |cffffffff{UI:LFGLIST_NAME}|r en |cffffffffDungeons|r. Voor Mythic-dungeons bestaat geen queue.|n• Kies een lage key, +2 tot +4. Groepen met |cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r verwachten nieuwe spelers.|n• Klik op |cffffffff{UI:SIGN_UP}|r, vink je rol aan, en wacht tot de leider je uitnodigt.|n|n|cffffcc00Zelf een groep maken|r|n• Op dezelfde plek: klik |cffffffff{UI:START_A_GROUP}|r, kies de dungeon van je key, kies een speelstijl (|cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r is prima) en klik |cffffffff{UI:LIST_GROUP}|r.|n• Zet de dungeon-moeilijkheid op |cffffffffMythic|r voordat je naar binnen loopt.|n• Binnen klikt wie de key heeft op de |cffffffffFont of Power|r bij de ingang, stopt de key erin en drukt op |cffffffff{UI:CHALLENGE_MODE_START_CHALLENGE}|r. Na 10 seconden aftellen loopt de timer.|n|n|cffffcc00Tijdens de run|r|n• Op +2 tot +5 kost een death geen tijd, en gemarkeerde vijanden wijzen je een route. Vanaf +6 kost elke death tijd.|n• Vanaf +5 komt er een extra regel van de week bij. De tab |cffffffff{UI:CHALLENGES}|r in de Group Finder laat zien welke.|n• Op tijd: je key gaat 1 tot 3 niveaus omhoog. Te laat: je krijgt nog steeds loot, maar de key zakt 1 niveau. Hoe dan ook wordt het een andere dungeon.|n• Moet je stoppen? Typ |cffffffff/abandon|r voor een stemming. Zomaar weggaan kan je het stempel Keystone Deserter opleveren.|n• Iedereen opent aan het eind zelf de kist voor zijn eigen loot.|n|n|cffffcc00Hulp|r|n• Zeg het in de groep: 'first time in this dungeon'. Op lage keys leggen de meeste spelers het graag uit.|n• Vraag het je guild, of kijk bij |cffffffff{UI:COMMUNITIES_GUILD_FINDER}|r en |cffffffffFind a Community|r in het venster Guild & Communities (J).|n• Je |cffffffff{UI:DUNGEON_SCORE}|r staat op de tab {UI:CHALLENGES}. Veel leiders kijken ook naar de Raider.IO-score.|n|nMidnight Helper helpt binnen: bosstips openen zodra je binnenloopt, en |cffffffff/mh mplus|r toont je beste run per dungeon en waar een key het meest oplevert.",
	CODEX_AGGRO_TITLE = "Aggro: wie slaat de vijand?",
	CODEX_AGGRO_BODY = "Aggro betekent dat een vijand jou aanvalt. De tank wil dat; een DPS of healer die het trekt, gaat vaak dood. Het spel kan je al waarschuwen, maar bij veel spelers staan die waarschuwingen uit. Midnight Helper zet er niets van voor je om: typ |cffffffff/mh aggro|r om te zien hoe ze bij jou staan.|n|n• |cffffffff{UI:NAMEPLATE_OPTIONS_LABEL} > {UI:UNIT_NAMEPLATES_THREAT_DISPLAY}|r: vink |cffffffff{UI:UNIT_NAMEPLATES_THREAT_DISPLAY_FLASH}|r aan. De nameplate van een vijand flitst als de tank hem kwijtraakt of als een DPS of healer hem trekt.|n• |cffffffff{UI:COMPACT_UNIT_FRAME_PROFILE_DISPLAYAGGROHIGHLIGHT}|r (raid frames): een rode rand om wie aggro heeft. Handig voor healers.|n• |cffffffff{UI:ACCESSIBILITY_AUDIO_LABEL} > {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} > {UI:CAA_SAY_IF_TARGETED_LABEL}|r: een stem zegt het als een vijand jou kiest. Zet eerst {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} aan; deze wordt per specialisatie bewaard.|n|nGebruik je een nameplate-addon zoals Plater? Dan komt het flitsen op nameplates van die addon, niet van het spel: kijk in de eigen instellingen daarvan.",

	CODEX_RAID_VAULT_TITLE = "Raid Great Vault",
	CODEX_RAID_VAULT_BODY = "• Raid-bazen vullen de Raid vault-rij: 2, 4 en 6 bazen openen één, twee en drie keuzes. Elke moeilijkheid telt, Raid Finder ook, en de Lair-baas ook.|n• In Season 2 komt elke keuze uit één moeilijkheid hoger dan waarop je de bazen versloeg: Raid Finder geeft Champion, Normal geeft Hero, Heroic geeft Myth, Mythic geeft Myth op een hoger niveau.|n• Gemengde moeilijkheden: elke keuze gebruikt de hoogste moeilijkheid waarop je dat aantal bazen haalde. De vault-UI laat zien wat je deze week hebt.|n• Crests geef je daarna uit om raid-gear te upgraden.",

	CODEX_VAULT_ADVISOR_TITLE = "Great Vault Advisor",
	CODEX_VAULT_ADVISOR_BODY = "• Zijpaneel naast Blizzards Great Vault-venster als je je reward kiest bij de Great Vault in Silvermoon — niet in een Midnight Helper-tab. SHIFT-J toont alleen een overzicht, daar verschijnt het paneel dus niet.|n• Rangschikt vs equipped gear (optioneel Pawn).|n• Toggle in minimap settings / Esc -> AddOns.|n• Auto / Raid / M+ profiel.",

	CODEX_WORLD_HUB_TITLE = "Void & Rituals — één systeem",
	CODEX_WORLD_HUB_BODY = "• Sinds patch 12.0.5 vormen |cffffffffRitual Sites|r en |cffffffffVoid Assaults|r één systeem. Allebei wisselen ze elke week tussen Eversong Woods en Zul'Aman, en ze delen één currency en één renown.|n• Zelfde |cffffffffField Accolades|r en Bazaar-hub — farm ze niet als losse dingen.|n• Season 2 verlaagde de gear die je met Field Accolades koopt naar Adventurer en Veteran: handig voor een nieuw personage, niet voor top-gear.|n• De gecombineerde tab toont de actieve site en zone van deze week, je Field Accolades en renown, en routeknoppen.",

	CODEX_RITUAL_TITLE = "Ritual Sites",
	CODEX_RITUAL_BODY = "• Een instanced ritual voor 1 tot 5 spelers. Elke week staat hij op één van twee plekken: Daggerspine Point in Eversong Woods of de Broken Throne in Zul'Aman. Kies een tier en maak hem af voor accolades, renown en loot.|n• Eén site tegelijk actief; de addon markeert welke.|n• De Ritual Site-pin in de SMC City Guide zet een route naar de actieve site van deze week. Weet de addon die nog niet, dan opent de pin de tab Void & Rituals.",

	CODEX_VOID_TITLE = "Void Assaults",
	CODEX_VOID_BODY = "• De Void valt Eversong Woods of Zul'Aman aan — elke week één van de twee. Doe Void Strikes; genoeg daarvan starten een grotere Void Incursion. Allebei geven Field Accolades.|n• Deelt Field Accolades en de Ritual Sites-renown met Ritual Sites — je bouwt aan allebei tegelijk.|n• De tab Void & Rituals toont de zone van deze week, die van volgende week en je weekly quest.",

	CODEX_RARES_TITLE = "Midnight rares",
	CODEX_RARES_BODY = "• Weekly rares met account/char loot.|n• Tab |cffffffffRares|r: kills, en een route met de dichtstbijzijnde eerst. De routepijl (die van Midnight Helper, of die van TomTom als je dat gebruikt) gaat daarna door naar de volgende.|n• Alert bij rare in de buurt (~500 yd) — toggle in settings.",

	CODEX_PROF_TITLE = "Professions — weekly loop",
	CODEX_PROF_BODY = "• Elk beroep heeft zijn eigen |cffffffffKnowledge Points (KP)|r en zijn eigen |cffffffffArtisan's Moxie|r: Alchemy-Moxie koopt alleen Alchemy-spullen.|n• |cffffffffElke week, per beroep:|r de weekly quest van je trainer in Silvermoon (vanaf skill 25), |cffffffffPatron orders|r aan de Crafting Orders-tafel die Knowledge geven (de grootste wekelijkse bron), tot twee Knowledge-items uit gewone treasures in de Midnight-zones, en één Thalassian Treatise (gemaakt door Inscription).|n• Gatherers en Enchanters krijgen ook Knowledge-items uit verzamelen of disenchanten. Daarmee haal je een gemiste week in; bij de meeste andere wekelijkse bronnen kan dat niet.|n• |cffffffffAbundance|r is een apart spoor: een Shard of Dundun (hooguit 8 per week) start een Abundant Harvest, en die geeft Unalloyed Abundance.|n• Tab |cffffffffProfessions|r: unspent KP, je Shards of Dundun en kaartpins voor treasures en boeken. Waar je KP uitgeeft: de Basics-gids.",

	CODEX_PROF_GUIDE_TITLE = "Professions beginner guide",
	CODEX_PROF_GUIDE_BODY = "• |cffffffffBasics -> Professions|r: KP-plan en combos.|n• De sub-tab |cffffffffCrests|r gaat over crests: de currency waarmee je gear upgradet, en die krijg je uit veel activiteiten — niet alleen raids.|n• Herlees na patches — getallen en caps kunnen wijzigen.",
	CODEX_CRAFTGEAR_TITLE = "Gear laten craften",
	CODEX_CRAFTGEAR_BODY = "• Je hoeft het beroep niet zelf te hebben — een andere speler kan het voor je maken via een |cffffffffCrafting Order|r.|n• Crafted gear is de |cffffffffbetrouwbare|r route: geen geluk met drops nodig. Het is ook de enige gear met een |cffffffffEmbellishment|r (een speciaal effect — je draagt er maximaal twee).|n• |cffffffffWat je eerst verzamelt:|r een |cffffffffSpark|r (2 voor een kledingstuk of 1-hander, 4 voor een 2-hander) uit de wekelijkse quest in Silvermoon; |cffffffffcrests|r als je de hogere versie wilt; een |cffffffffMissive|r om je secondary stats te kiezen (Auction House); en de materialen.|n• |cffffffffDe crest-stap is bepalend:|r zonder crests krijg je de basisversie. Crests van een hogere tier verhogen het item level dat het stuk kan halen — de hoogste crests geven de sterkste craft. Je crest-tab laat zien wat je hebt.|n• |cffffffffDan bestellen:|r praat met de Crafting Orders-NPC in de Bazaar van Silvermoon, kies het item, hang je spark, crests en missive eraan, en zet hem als publieke order of stuur hem naar een crafter die je kent. Zet er een fooi bij, anders blijft hij hangen.|n• |cffffffffSparks en crests kan de crafter NIET leveren|r — die moet jij hebben. Hier gaat de eerste bestelling meestal mis.|n• De skill van de crafter bepaalt de kwaliteit, dus een crafter die je kent is beter dan een willekeurige publieke order.|n• De moeite waard als een slot maar niet wil droppen, of voor een Embellishment. Vallen er in dat slot makkelijk goede drops, bewaar je crests dan.",
	CODEX_PROFRESET_TITLE = "Je beroepsspecialisaties resetten (12.1)",
	CODEX_PROFRESET_BODY = "• Patch 12.1 laat je je Midnight-specialisatiekeuzes terugdraaien — één keer per beroep.|n• |cffffffffBij wie:|r {WAY:2393:45.05:56.17:Theremis}, in de Bazaar van Silvermoon naast de crafting orders — klik erop voor een waypoint. Hij biedt per beroep een aparte regel, dus je kunt Blacksmithing resetten en Enchanting precies laten zoals hij is.|n• |cffffffffWat je terugkrijgt:|r elk Knowledge Point dat je in de Midnight-bomen van dat beroep hebt uitgegeven, vrij om opnieuw te verdelen.|n• |cffffffffWat het kost:|r de waarschuwing van het spel luidt “You will lose all associated recipes”.|n• |cffffffffBijbehorende, niet alle.|r Weg is wat die specialisatiekeuzes hadden ontgrendeld. Recepten van een trainer, een drop of een quest staan buiten de bomen en blijven gewoon staan. Gezien bij een gereset Enchanting: de receptenlijst was onaangeroerd en de uitgegeven Knowledge stond weer op de teller.|n• |cffffffffHet is één keer.|r De bevestiging zegt ONCE in hoofdletters, en dat is per beroep — er is geen tweede poging als het nieuwe pad tegenvalt.|n• Bepaal dus |cffffffffvooraf|r waar de punten heen gaan. De Professions-pagina noemt de boom die je moet vullen en precies welke node.|n• Komen de recepten die hij afnam terug als je identiek herbesteedt? Het spel zegt dat nergens. Reken erop van niet.",
	CODEX_CORRPOWER_TITLE = "Corrosive Codex — welke gift neem ik als eerste?",
	CODEX_CORRPOWER_BODY = "|cffffcc00Twaalf gifts, en je mag er één gebruiken.|r Ze kosten allemaal |cffffffff8 Corrosive Souls|r, dus alle twaalf samen kosten er 96. Omdat de prijs voor allemaal gelijk is, gaat je eerste keuze over |cffffffffwat je nodig hebt|r — nooit over wat je kunt betalen.|n|n|cffffff78Eén ding verklaart het hele systeem|r|n• Het is een |cffffffffgifkringloop|r. De helft van de gifts wordt sterker tegen een vijand die Poisoned is, of terwijl |cffffffffjijzelf|r vergiftigd bent.|n• Daarom bestaat elk goed duo uit |cfffffffféén gift die vergiftigt + één gift die daarvan profiteert|r. Zie je dat eenmaal, dan zien die combinaties er niet meer willekeurig uit.|n|n|cffffff78Welke eerst? Kies op je probleem, niet uit een lijstje|r|n• |cffffffffIk wil gewoon harder slaan|r → |cffffffffUla'tek's Gift|r. Werkt op zichzelf, zonder tweede gift en zonder opzet. Elke gids die we lazen noemt deze als eerste.|n• |cffffffffGroepjes vijanden duren te lang|r → |cffffffffPlague of Corrosion|r of |cffffffffOphidian Maw|r.|n• |cffffffffIk ga steeds dood in delves|r → |cffffffffVirulent Mucus|r vangt de grote klappen op, |cffffffffGorgoneion Gaze|r bevriest alles om je heen zodra je onder de helft van je leven zakt.|n• |cffffffffCasters krijgen hun spell er steeds uit|r → |cffffffffAccursed Poison|r. Die onderbreekt er één voor je.|n|n|cffffcc00Pas op met Mephitic Cloud.|r Die laat getroffen |cffffffffvijanden|r genezen wat ze aanvallen. In een groep werkt dat tegen je.|n|n|cffffff78Wat we zelf gemeten hebben, en wat niet|r|n• |cffffffffUit het spel:|r de prijs van 8, en de volledige tekst van Ula'tek's Gift. Die zijn van ons.|n• |cffffffffUit gidsen:|r de volgorde hierboven, en hoeveel gifts het tweede slot openen. Het spel zelf zegt alleen \"until your offerings are sufficient\" en noemt geen getal. |cffffffffZes bronnen zeggen 8|r — waaronder Wowheads eigen spell-pagina, die het in een tabel zet — en één blog zegt 6. Dus 8 klopt vrijwel zeker; we hebben het alleen zelf nog niet zien gebeuren. Jij weet het op het moment dat je tweede slot verschijnt.|n• Ula'tek's Gift is |cffffffffal een keer afgezwakt|r. Een ranglijst uit augustus is dus niet vanzelf de waarheid van vandaag — precies daarom is die gifkringloop hierboven het stuk dat je moet onthouden.",
	CODEX_ATALUTEK_TITLE = "De Vaults of Atal'Utek — wat er te doen is, en waar",
	CODEX_ATALUTEK_BODY = "|cff8fd3ffOm te beginnen|r|n|n• |cffffffffWat het is:|r een stuk 12.1-content op de Coiled Isle met een eigen kaart, en daaronder nóg een kaart: de Underbelly. Het staat nu al open — er zit geen seizoenspoort op.|n|n• |cffffffffHoe je binnenkomt:|r een keten van vier quests — |cffffffffInto the Vaults of Atal'Utek|r, dan |cffffffffVaults of Atal'Utek: One Coin Too Many|r en |cffffffffVaults of Atal'Utek: A Toxic Tour|r, die je samen krijgt, dan |cffffffffVaults of Atal'Utek: The Altar of Corrosion|r. Alles hieronder zit erachter, dus doe die eerst. |cffffffffA Toxic Tour is een verhaalquest, geen daily|r — hij vraagt om één Temple Patrol, één Temple Strike, één Temple Incursion en één Ancient Foe, dus hij loopt vanzelf vol terwijl je de rondgang hieronder doet.|n|n|cff8fd3ffWat je hier doet|r|n|n• |cffffffffWat je hier eigenlijk dóét — vier dingen, en ze voeden elkaar.|r |cffffffffTemple Patrols|r zwerven over de kaart en wisselen ongeveer elke tien minuten; dat is het makkelijkst om bij aan te haken en er loopt er bijna altijd één. |cffffffffTemple Strikes|r zijn groter, en die bouwen naar een incursion toe. Zijn er genoeg Strikes gedaan, dan begint een |cffffffffTemple Incursion|r, en elke Incursion eindigt met het wekken van een |cffffffffAncient Foe|r — daar komen die drie rare elites vandaan: maar één per week, met een klok van tien minuten. Munten, sleutels, gear en reputatie komen allemaal uit die lus. Vraag je je af wat je moet doen: sluit gewoon aan bij wat er loopt.|n|n• |cffffffffHoe vind ik nou eigenlijk een Temple Strike?|r Open je kaart binnen de Vaults en kijk naar de event-iconen — een Strike staat daar net als elk ander wereld-event, en |cffffffffhij heeft geen klok|r: hij blijft staan tot een groep hem afmaakt, dus je kunt er rustig heen lopen. |cffffffffEen paar spelers is genoeg|r; je hebt geen vooraf gemaakte groep nodig en meestal is er al iemand mee bezig. Er zijn er zes, elk met een vaste startplek — klik erop voor een waypoint: {WAY:2509:50.55:15.70:Cursed Depths} · {WAY:2509:47.36:46.17:Overflowing Venom} · {WAY:2509:47.67:46.34:Profane Pyres} · {WAY:2509:47.26:26.69:Purifying Earth and Sky} · {WAY:2509:39.32:39.92:Ruuk’Jar’s Clutch} · {WAY:2613:52.25:36.27:The Underbelly}.|nStaat er geen Strike op je kaart, dan loopt er waarschijnlijk net een Incursion of de Ancient Foe daarna — sluit je daar dan bij aan. Zodra die voorbij is, verschijnt er een nieuwe Strike.|n|n• |cffffffffHoe je je binnen verplaatst.|r De |cffffffffAmani Windcallers|r vliegen je tussen drie punten in de Vaults — de hub |cffffffffAmani Foothold|r, de Eastern Amani Outpost en de Northern Amani Bulwark. Vliegmeester |cffffffffEagletender Mal’Tiki|r staat op {WAY:2509:44.42:62.21:Amani Foothold}. Vliegen kan niet binnen de Vaults, en daarom bestaan ze — het is er groter dan het lijkt en lopen is de trage manier.|n|n• |cffffffffDe herhaalbare quests — één weekly en acht dailies.|r |cffffffffPurging the Vaults|r bij |cffffffffWarleader Abdumati|r in de Amani Foothold is de weekly die je niet wilt missen. De acht dailies zijn |cffffffffPatrolling the Temple|r, |cffffffffBounty of the Cursed|r, |cffffffffRelentless Strikes|r, |cffffffffDecisive Incursions|r, |cffffffffFrom Whence it Came|r, |cffffffffEssence of Malice|r, |cffffffffWhat's Out There?|r en |cffffffffShoulder to Shoulder|r — pak wat je kaart je vandaag aanbiedt. De meeste vragen om de activiteiten hierboven, dus ze vinken zichzelf af terwijl je speelt. Twee willen dat je in een party zit (What's Out There? en Shoulder to Shoulder): de mensen die al naast je staan zijn genoeg, geen premade. En één die je hier nooit vindt: |cffffffffMidnight: Vaults of Atal'Utek|r is een weekly meta voor deze plek die je in |cffffffffSilvermoon|r ophaalt.|n|n|cff8fd3ffCoin and Soul|r|n|n• |cffffffffCorrosive Coin|r is de currency van de zone. In de woorden van het spel zelf: “Spirits of the Amani within the Vaults of Atal'Utek deal exclusively in this phantasmal token.” Je eigen saldo is het getal hierboven.|n|n• |cffffffffCorrosive Soul is dat niet.|r Het is helemaal geen currency maar een |cffffffffitem|r in je tassen, en het is wat de Corrosive Codex als offer van je vraagt. Gidsen halen de twee namen voortdurend door elkaar; het spel nooit. Zegt iets dat je Corrosive Coins bij de Codex moet uitgeven, dan is dat precies die verwisseling.|n|n• |cffffffffWaar de munten heen gaan — twee plekken, allebei bij Er’inye|r op {WAY:2509:51.10:62.76:Er'inye}. Met haar praten koopt |cffffffffCorrode Spirit|r, en dat is wat de Altar-boom voedt; naast haar is de |cffffffffSkull of Er’inye|r een handelaar met drie pagina’s mounts, pets, ensembles en recepten, van 500 tot 25.000 munt. |cffffffffDe corrode-prijs loopt elke keer op|r — gezien op 1.500 en daarna 2.000 in één bezoek — dus lees het venster in plaats van te sparen voor een bedrag.",
	CODEX_ATALUTEK_DISC_TITLE = "Altar of Corrosion: de vier sleutels",
	CODEX_ATALUTEK_DISC_BODY = "• |cffffffffThe Altar of Corrosion|r is de boom met nodes die de laatste quest van de keten opent. Het meeste gaat vanzelf open naarmate je uitgeeft, maar |cffffffffvier nodes zitten achter een sleutel die je zelf moet vinden|r — en alle vier werken ze hetzelfde: er valt een item, dat gebruik je op één object ergens in de Vaults, dat geeft een questitem, en Er’inye doet de rest.|n|cffffffffCorroded Key|r → de Venom-Worn Coffer → |cffffffffRun of the Vaults|r (Glideways, of Swift Steps) · |cffffffffSpirit Loupe|r → de Feather of Tok’jara op {WAY:2509:48.46:25.80:Feather of Tok'jara} → |cffffffffSpectral Winds|r (Spirit Walk, of Spectral Shipping) · |cffffffffExcising Knife|r → de Eye of Szarith, in een gifpoel in de Underbelly → |cffffffffBroodmaster|r (+100% schade op eggs, of −75% schade van egg bursts) · |cffffffffDispelling Charm|r → Jin’tal’s Reliquary in het Profaned Mausoleum → |cffffffffSpiritual Protection|r (spookbondgenoten bij Curse Surges, of meteen weer opstaan als je buiten de Vaults doodgaat).|n|cffffffffEen sleutel aan Er’inye tonen ontgrendelt niets.|r Ze is blind, en ze vertelt je wat ze vóélt — dat is een hint over waar het ding hoort. |cffffffffWaar de sleutels vandaan komen|r — daar zijn de gidsen het nu over eens: de Corroded Key uit Temple Strikes, de Excising Knife uit een Temple Incursion, de Spirit Loupe van een Ancient Foe. De |cffffffffDispelling Charm|r is de uitzondering: die komt niet uit de events, maar van Jin’tal in de Vault of Restless Bones, tijdens een zijquestlijn over de Med’jai.|n|n• |cffffffffGeef je eerste munten meteen uit aan de boom.|r De eerste vier nodes kosten niets en gaan vanzelf open naarmate je elders uitgeeft, en ze verhogen de Corrosive Coin die je verdient met |cffffffff25, 50, 75 en uiteindelijk 100 procent|r. De boom betaalt zichzelf terug, dus elke ronde ná de eerste levert meer op — sparen is juist de dure keuze. En let op de scheefheid die het tempo van deze zone bepaalt: |cffffffffop munten zit geen cap|r, op Corrosive Souls wel. Farm munten gerust; plan je avond niet rond souls.",
	CODEX_LABYRINTH_TITLE = "The Labyrinth of Kindo'jan (12.1.5)",
	CODEX_LABYRINTH_BODY = "|cffffcc00Een grote delve van negen kamers, met aan het eind de baas Kindo'jan.|r Nieuw in patch 12.1.5. Valeera gaat mee, zoals in elke delve.|n|n|cffffff78Erin komen|r|n• De ingang ligt in Eversong Woods: {WAY:2395:62.99:72.18:The Labyrinth of Kindo'jan}. Er zijn 11 tiers; volgens gidsen kies je er één bij de deur.|n|n|cffffff78Je hoeft hem niet af te maken|r|n• Elke 3 kamers geven |cffffffff2 Heavy Trunks, 1 Bountiful Coffer en Great Vault-credit|r, en daarna mag je stoppen. Crests uit Heavy Trunks tellen dubbel.|n• 3 kamers op een tier spelen de volgende tier vrij.|n• |cffffffffHij opent ook gewone delves:|r 3 kamers op Labyrinth-tier 1 tot en met 8 spelen de volgende Delve-tier vrij voor dit seizoen: Labyrinth-tier 7 geeft Delve-tier 8. In de spelgegevens van de testserver geven tier 9, 10 en 11 dezelfde Delve-tier, niet de volgende; dat kan bij de release nog veranderen.|n|n|cffffff78Kindo'jan|r|n• Vanaf tier 8 geeft hij één keer per week per character Great Vault-credit.|n• Drie aanvallen zijn bekend: |cffffffffCrushing Blow|r (stap uit de inslag; er verschijnt een Amani Juggernaut), |cffffffffHash'ey's Command|r (4 Amani Headhunters — snel doden) en |cffffffffDisgraceful Display|r, dat stapelt: bij 3 stacks vinden de loa je onwaardig. Het spel heeft nog geen journal-pagina voor hem.|n|n|cffffff78Hulp onderweg|r|n• Vier |cffffffffLoa-Spirit Conduits|r: klik er één voor een sterke boon voor de hele groep.|n• Bountiful Coffers vanaf tier 8 bevatten een |cffffffffHeroic Soul Fragment|r; drie daarvan geven een willekeurig Hero-track-stuk.|n• Een wekelijkse questlijn van zes stappen, elke week één nieuwe, eindigt in twee Myth-track-armor-stukken naar keuze.|n|n|cffffcc00Nog niet bekend:|r of de coffers een Restored Coffer Key vragen, en hoe kamer-credit en Kindo'jan-credit optellen. Kijk in het Great Vault-venster, niet in een gids.",
	CODEX_AQIR_TITLE = "Aqir Invasion (12.1.5)",
	CODEX_AQIR_BODY = "|cffffcc00Een buitenevent in Eversong Woods of Zul'Aman, elk uur 10 minuten.|r De hele zone doet samen openbare opdrachten, en daarna komt er een baas.|n• Zes scenario's: Disrupt Aqir, Aid Defenders!, Aqir Nesting Grounds, Whack the Aqir, Aerial Assault en Reinforce Defenses. Drie zijn gevechten; die krijgen één van acht affixen.|n• Uit Blizzards notes: kick de |cffffffffWebweaver|r en dood de |cffffffffVoidweaver|r eerst.|n• De beloning loopt via |cffffffffAqir Research Enclave|r, een warband-reputatie tot Exalted. Hun mensen staan in Silvermoon: {WAY:2393:39.20:80.03:Aqir Researchers}.|n• Achievements: alle zes scenario's (No Hives Left Standing), tien invasies (Driving Back the Swarm), Exalted (Aqir Research Associate).|n• Volgens gidsen wisselt de zone elke week en is het nooit de zone van die week's Void Assault. Dat hebben we zelf nog niet gezien.",
	CODEX_KITHIX_TITLE = "Kith'ix — een raid met één baas (12.1.5)",
	CODEX_KITHIX_BODY = "|cffffcc00The Unbinding of Kith'ix is een raid met één baas|r, de C'Thraxxi-generaal Kith'ix. Lady Liadrin vecht met je mee. Story, Raid Finder, Normal, Heroic en Mythic (Mythic met 15 tot 25 spelers).|n• Ingang: onder de Venomous Abyss, in The Underbelly: {WAY:2613:74.27:5.91:The Unbinding of Kith'ix}. Berekend uit speldata; nog niet op een scherm gezien.|n|n|cffffff78Iedereen|r|n• Dood de adds vóór |cffffffffSuffocating Darkness|r. Wat dan nog leeft, gaat razen.|n• Tijdens Suffocating Darkness: |cffffffffsta in Liadrins Refulgent Bulwark|r. Daarbuiten stik je.|n• Pak vóór |cffffffffExtinguish|r een |cffffffffLight's Embrace|r. Dat scheelt veel schade.|n• Ontwijk |cffffffffTwisted Appendage|r.|n|n|cffffff78Healers|r — haal de heal-absorb |cffffffffAbyssal Grasp|r snel weg, anders wordt die speler de duisternis in gesleept.|n|cffffff78Tanks|r — |cffffffffDark Devastation|r laat je veel meer schade nemen, dus wissel. Trek de aqir weg bij de baas: dicht bij hem nemen ze veel minder schade.|n|n|cffffff78Fase 2|r — |cffffffffStygian Howl|r stunt de raid. Liadrin redt je met Last Light en geeft je een burst-venster. Daarna is het een race.",
	CODEX_VENOMSTONE_TITLE = "Ascendant Venomstones (12.1.5)",
	CODEX_VENOMSTONE_BODY = "|cffffcc00Venomstones tillen een volledig geüpgraded stuk boven zijn normale maximum.|r Tien |cffffffffAscendant Venomstones|r verhogen het item level van één Season 2-wapen, -trinket of -ketting dat volledig geüpgraded is op de Hero- of Myth-track, of Tidal Crafted op de hoogste kwaliteit. Dat doe je bij de Catalyst in Silvermoon City, met hulp van Orin Straylight.|n|n|cffffff78Het gaat in drie weken open|r, met quests van Orin in Silvermoon:|n• Week van 6 okt — |cffffffffUmbral Blessings of the Catalyst|r: één extra Nebulous Voidcore per week.|n• Week van 13 okt — |cffffffffAncient Depths, Ancient Venom|r: Orin begint zijn onderzoek.|n• Week van 20 okt — |cffffffffAscending with Venomstones|r: de stenen gaan droppen.|n• Zijn eerdere quests (In the Catalyst's Shadow, Prismatic Potential) komen eerst.|n|n|cffffff78Waar ze droppen|r — elke Heroic- en Mythic-raidbaas, Mythic+ vanaf +10, Tier 11 Bountiful Delves, en de Champion-gearkisten van Nightmare Prey-hunts.|n• In de week van 20 okt verdwijnt ook de crest-cap.|n|cffffcc00Volgens gidsen|r kan een stuk dat al Ascendant is niet nog hoger.",
	CODEX_ATALUTEK_DEAD_TITLE = "The Honored Dead & de rares",
	CODEX_ATALUTEK_DEAD_BODY = "• |cffffffff“The Honored Dead” — twaalf gedenktekens|r op de Vaults-kaart, één achievement, en verreweg het duidelijkste om hier gewoon te gaan dóen. In één looproute, van boven op de kaart naar beneden:|n{WAY:2509:46.79:7.51:To a sister 46.79, 7.51} · {WAY:2509:56.49:22.88:To a shield-bearer 56.49, 22.88} · {WAY:2509:47.22:28.77:To a father 47.22, 28.77} · {WAY:2509:42.57:33.18:To a stranger 42.57, 33.18} (onder de brug) · {WAY:2509:52.91:33.90:To a captain 52.91, 33.90} · {WAY:2509:55.62:40.60:To a dream 55.62, 40.60} · {WAY:2509:42.84:39.93:To sons 42.84, 39.93} · {WAY:2509:52.21:45.12:To a lover 52.21, 45.12} · {WAY:2509:38.50:47.66:To Comrades 38.50, 47.66} · {WAY:2509:55.31:48.45:To parents 55.31, 48.45} · {WAY:2509:49.50:56.59:To a daughter 49.50, 56.59} · {WAY:2509:45.81:61.79:To Failure 45.81, 61.79}|n|n• |cffffffffDe Underbelly|r is de kaart eronder, met de ingang op {WAY:2509:47.30:11.20:The Underbelly} op de Vaults-kaart. Daar woont één rare, |cffffffffSzarith the Fanged|r op {WAY:2613:38.40:17.69:Szarith the Fanged}, en de Underbelly heeft een eigen achievement: |cffffffffSoft Underbelly|r. |cffffffffAlleen Szarith is niet genoeg:|r volgens de gidsen vraagt het achievement ook om een paar named elites die alleen verschijnen terwijl de Temple Strike |cffffffffThe Underbelly|r loopt.|n|n• |cffffffffDrie rare elites op de hoofdkaart|r — Congealed Malice, Khu'tulak en Susarikk — vormen een derde: |cffffffffOppose the Foes|r. |cffffffffZe hebben geen vaste plek, en dat ís het antwoord, geen gat in onze kennis|r: één van de drie wordt wakker op het moment dat er een |cffffffffTemple Incursion|r wordt afgerond, en je hebt ongeveer tien minuten om hem te doden. |cffffffffElke week zit er maar één van de drie in de rotatie|r, dus dit achievement kost minstens drie weken. Je gaat dus niet op ze jagen — je maakt Incursions af, en dan komt die van deze week naar jou toe.",
})

merge(ns._mhLocales and ns._mhLocales.deDE, {
	TAB_CODEX = "Midnight Codex",
	CODEX_PANEL_TITLE = "Midnight Codex",
	CODEX_PANEL_INTRO = "Dein Handbuch für Midnight — was jedes System ist, wofür jede Währung dient und wo du in diesem Addon klickst. Bewege den Cursor über Währungssymbole für Blizzard-Tooltips.",
	CODEX_OPEN_TAB_FMT = "Öffnen: %s",
	CODEX_NAV_DELVES_VAULT = "Tab Delves & Vault (Große-Schatzkammer-Block)",
	CODEX_NAV_DELVES_MIDNIGHT = "Tab Delves & Vault (Tiefen-Liste)",
	CODEX_NAV_BASICS_DAWN = "Kategorie Basics (Crests)",
	CODEX_NAV_BASICS_PROF = "Tab Basics (Berufe-Guide)",
	CODEX_BALANCE_FMT = "Du hast: |cffffffff%d|r",
	CODEX_BALANCE_UNKNOWN = "Der Stand aktualisiert sich, wenn du dich mit diesem Charakter anmeldest.",
	CODEX_SEARCH_OPENED = "Midnight Codex geöffnet.",
	CODEX_BETA_DISABLED = "Midnight Codex ist in den Einstellungen deaktiviert (Beta-Tabs).",

	CODEX_CAT_START = "Erste Schritte",
	CODEX_CAT_WEEKLY = "Wöchentlicher Ablauf",
	CODEX_CAT_CURRENCIES = "Currencies",
	CODEX_CAT_DELVES = "Delves",
	CODEX_CAT_DUNGEONS = "Dungeons & M+",
	CODEX_CAT_RAID = "Schlachtzug & Crests",
	-- ⚠️ Was "Void & Rituals" until 19 aug, and half of what sits under it is neither.
	-- The category holds Prey hunts, rares, Turbulent Timeways and Showdowns alongside
	-- the void and ritual articles. Rob went looking for Prey, read that button, and
	-- walked straight past it — the same class of fault as the twelve type-only commands
	-- on 18 aug: the feature was there, under a name nobody would guess.
	CODEX_CAT_WORLD = "World content",
	CODEX_CAT_COILEDISLE = "Coiled Isle",
	CODEX_ROUTE_BTN = "Der Route folgen",
	CODEX_CAT_PROFESSIONS = "Professions",

	CODEX_START_TITLE = "Erste Schritte — deine Midnight-Woche",
	CODEX_START_BODY = "|cffffcc00Denk in Schichten:|r ein Weekly-Reset, mehrere Belohnungspfade. Du brauchst nicht jedes System jeden Tag — wähle ein Ziel.|n|n|cffffff781) Account & Reset|r|n• Prüfe den Tab |cffffffffThis Week|r für Vault, Weltboss, Keys und Aufgaben.|n• |cffffffffAccount snapshot|r zeigt all deine Twinks (Vault, Delver's Call, Berufs-Weeklies).|n|n|cffffff782) Kampfinhalte|r|n• |cffffffffDelves|r — Haupt-Gear-Pfad (Keys, Stufen, Schatzkammer-Slots). Nutze |cffffffffDelve Coach|r für Tipps pro Tiefe.|n• |cffffffffMythic+|r und |cffffffffSchlachtzüge|r füllen weitere Schatzkammer-Slots (siehe Kategorien Dungeons & Schlachtzug).|n|n|cffffff783) Offene Welt|r|n• |cffffffffGewundene Insel|r — die Zone von Saison 2 aus Patch 12.1, mit einer eigenen Kategorie hier.|n• |cffffffffPrey|r-Jagden zählen für dieselbe Reihe der Großen Schatzkammer wie Delves.|n• Tab |cffffffffVoid & Rituals|r — Field Accolades, Ritual Sites, Void Assaults (gleicher Renown-Pfad).|n• Tab |cffffffffRares|r — wöchentliche Rare-Beute und Routen.|n|n|cffffff784) Crafting|r|n• Tab |cffffffffBerufe|r für KP / wöchentliche Mats; |cffffffffBasics|r für Crests.|n|n|cffffcc00Tipp:|r Öffne hier die Kategorie |cffffffffCurrencies|r, wenn du vergisst, wofür ein Token ist. Scrolle im Boss-Vorschaubild im Delve Coach zum Zoomen.",
	CODEX_MIDSTART_TITLE = "Die Midnight-Kampagne beginnen",
	CODEX_MIDSTART_BODY = "|cffffcc00Auf Stufe 80 kommt die Quest |r|cffffffffMidnight|r|cffffcc00 von allein.|r Du musst nichts suchen — sie liegt in deinem Questlog, sobald du 80 wirst. Unter 80 kannst du zwar schon nach Silbermond reisen, dort gibt es aber noch nichts anzunehmen.|n|n|cffffff78Wo es beginnt|r|n• Sprich mit dem |cffffffffImage of Lady Liadrin|r. Sie steht in mehreren Hauptstädten, also auch in deiner.|n• Sie bietet zweierlei: die Einführung ansehen, oder |cffffffffI have heard this tale before|r, um sie zu überspringen.|n|n|cffffff78Das Überspringen kostet dich nichts|r|n• Du kommst in |cffffffffSilbermond|r heraus und bekommst die nächste Quest sofort.|n• Hinter der Einführung ist nichts verschlossen — Routen, Stadtpins und die Wochenroutine laufen genau gleich.|n|n|cffffff78Wählen, wo du anfängst|r|n• Diese nächste Quest, |cffffffffAdventuring in Midnight|r, schickt dich zur |cffffffffScouting Map|r im Sanctum of Light.|n• Fünf Startpunkte: |cffffffffArator's Journey|r, |cffffffffEversong|r, |cffffffffZul'Aman|r, |cffffffffVoidstorm|r und |cffffffffHarandar|r.|n• Fahre über einen, um zu sehen, was dort wartet; ein Klick öffnet nur den Scouting Report. |cffffffffHinschauen kostet nichts.|r|n|n|cffffcc00Gewählt und es dir anders überlegt?|r Die Wahl blendet die anderen vier aus, solange die Quest in deinem Log liegt — aber |cffffffffbrich die Quest ab|r, und alle fünf sind wieder da. Sie bestimmt deine Reihenfolge, nicht deinen Weg.",
	CODEX_WARBAND_TITLE = "Kriegsmeute & die Kriegsmeutenbank",
	CODEX_WARBAND_BODY = "|cffffcc00Deine Kriegsmeute|r sind alle Charaktere deines Accounts, als ein Team behandelt. Vieles ist jetzt |cffffffffkriegsmeutengebunden|r — accountweit geteilt — sodass du viel weniger zwischen Twinks verschickst.|n|n|cffffff78Kriegsmeutengebundene Gegenstände & Währungen|r|n• Manche Währungen gelten für den ganzen Account oder lassen sich zwischen Charakteren verschieben — dein Währungsfenster zeigt, welche. Aufwertungs-Crests zählen pro Charakter.|n• Ausrüstung ist oft |cffffffffkriegsmeutengebunden bis angelegt|r — schick sie an einen Twink, aber einmal angelegt bleibt sie bei diesem Charakter.|n|n|cffffff78Die Kriegsmeutenbank|r — eine geteilte Bank, die all deine Charaktere nutzen.|n• Öffne sie bei |cffffffffjedem Bankier|r (oder Jeeves) — es ist ein Reiter an deiner normalen Bank, neben deiner Charakterbank.|n• Lagere jeden |cffffffffnicht-seelengebundenen|r Gegenstand und zahle |cffffffffGold|r über Charaktere hinweg ein oder aus (auch fraktionsübergreifend).|n• Crafte direkt daraus — sie zählt als Reagenzienquelle.|n|n|cffffff78Reiter & Kosten|r — 5 Reiter, je 98 Plätze (490 gesamt). Du startest mit keinem; kaufe sie mit Gold:|n• Reiter 1: |cffffffff1.000g|r|n• Reiter 2: |cffffffff25.000g|r|n• Reiter 3: |cffffffff100.000g|r|n• Reiter 4: |cffffffff500.000g|r|n• Reiter 5: |cffffffff2.500.000g|r  (alle fünf = 3.126.000g)|n|n|cffffcc00Tipp:|r 2-3 Reiter reichen den meisten Spielern. Verwechsle sie nicht mit deiner |cffffffffCharakterbank|r (seit Patch 11.2 auch mit Reitern, viel günstiger) — die ist pro Charakter; die Kriegsmeutenbank ist geteilt.",

	CODEX_WEEKLY_RESET_TITLE = "Weekly-Reset",
	CODEX_WEEKLY_RESET_BODY = "• Der meiste wöchentliche Fortschritt setzt sich am Wartungstag deiner Region zurück (EU Mittwochmorgen, US Dienstagmorgen).|n• Große-Schatzkammer-Auswahl, Weltboss-Beute und viele Wochen-Caps setzen sich zurück.|n• Der Tab |cffffffffThis Week|r zeigt die Zeit bis zum Reset, wenn die API sie liefert.|n• Plane Twinks: Der |cffffffffAccount snapshot|r vergleicht, wer noch eine Vault-Belohnung, Keys oder Delver's Calls offen hat.",

	CODEX_VAULT_TITLE = "Große Schatzkammer",
	CODEX_VAULT_BODY = "• Drei Reihen: |cffffffffWorld|r (Tiefen, Prey und andere Weltaktivitäten), |cffffffffDungeons|r (Heroisch, Mythisch, Mythic+ und Zeitwanderung), |cffffffffSchlachtzüge|r (Schlachtzugsbosse auf jeder Schwierigkeit und der Lair-Boss).|n• Jede Reihe schaltet bis zu drei Optionen frei: World bei 2/4/8 Aktivitäten, Dungeons bei 1/4/8, Schlachtzüge bei 2/4/6 Bossen.|n• Jede Option ist nur so gut wie der schwächste Lauf, den sie brauchte: Die 4-Lauf-Option nutzt deinen viertbesten Lauf der Woche, die 8-Lauf-Option deinen achtbesten. Ein schwerer Key hebt nur deine erste Dungeons-Option an.|n• Saison 2: Eine Schlachtzugsoption liegt eine Stufe über dem, was du besiegt hast — Normal-Kills geben einen Gegenstand der Held-Track, heroische Kills einen der Mythos-Track.|n• Nach dem Reset wählst du insgesamt |cffffffffeine|r Belohnung aus allen freigeschalteten Optionen, an der Großen Schatzkammer in Silbermond. SHIFT-J zeigt nur eine Übersicht.|n• Mit 3 oder mehr freigeschalteten Optionen, aus beliebigen Reihen, kannst du statt eines Gegenstands einen |cffffffffNebulous Voidcore|r (einen Bonuswurf) nehmen.|n• |cffffffffVault Advisor|r (auf Blizzards Vault-UI) bewertet Optionen gegen deine angelegte Ausrüstung.|n• In diesem Addon steht die World-Reihe im Tab |cffffffffTiefen & Kammer|r — klappe |cffffffffGroße Schatzkammer (Welt)|r auf. Fahre im |cffffffffAccount snapshot|r mit der Maus über einen Charakter, um alle drei Reihen zu sehen.|n• Zusammenfassung auch im Tab |cffffffffThis Week|r.",

	CODEX_WORLDBOSS_TITLE = "Weltboss (Midnight)",
	CODEX_WORLDBOSS_BODY = "• Ein rotierender Weltboss pro Woche (Lu'ashal, Cragpine, Thorm'belan, Predaxas), als Weltquest mit Totenkopf auf der Karte. Du musst nichts annehmen.|n• Lady Liadrin in Silbermond bietet manchmal |cffffffffMidnight: World Boss|r als eine ihrer vier Wochenoptionen an; den Boss dieser Woche zu besiegen schließt sie ab.|n• Kriegsmeuten-Beute: tötet ihn ein Charakter, zeigen Twinks ihn als erledigt.|n• Oben im Tab |cffffffffTiefen & Kammer|r mit TomTom-Route.|n• Auch über den SMC City Guide in Silbermond verlinkt.",
	CODEX_FOLIO_TITLE = "Omnium Folio (12.0.7)",
	CODEX_FOLIO_BODY = "• Machtsystem aus Patch 12.0.7, in 12.1 weiterhin aktiv — ein Minimap-Buch mit |cffffffffRunen|r, die du außerhalb des Kampfes frei tauschst (kein Slot-Verbrauch).|n• Macht kommt aus der Kette |cffffffff'Seeking Knowledge'|r (5 Schritte): The Omnium Folio, Ritualized Arcana, Ley Line Assaults, Magical Primessence, Off-World Magic.|n• Jeder Schritt belohnt dich mit einem |cffffffffMote of Omnial Inquiry|r, der die nächste Reihe Runen öffnet.|n• Schließe alle 5 ab für das Meta-Achievement und die Sunstrider-Omnium-Simulacrum-Dekoration.|n• Wochen verpasst? Mache die verpassten Quests direkt hintereinander zum Aufholen — kein Warten auf Resets.|n• Twinks: Hat ein Charakter die Einführung gemacht, können die anderen sie überspringen (12.1). Deine Runenwahl bleibt pro Charakter.",
	CODEX_TT_TITLE = "Turbulent Timeways (12.0.7)",
	CODEX_TT_BODY = "• Wiederkehrendes Zeitwanderungs-Event — diesmal ein |cffffffffDragonflight|r-Dungeonpool: Algeth'ar Academy, Halls of Infusion, Neltharus, Ruby Life Pools, The Azure Vault, Brackenhide Hollow.|n• Wöchentlich: laufe |cffffffff5 Zeitwanderungs-Dungeons|r für einen Gear-Cache; jeder Lauf stapelt |cffffffffKnowledge of Timeways|r (XP-Buff).|n• Verdiene |cffffffffMastery of Timeways|r in 4 von 6 Wochen für 'Master of the Turbulent Timeways' und das Reittier |cffffffffSpawn of Vyranoth|r.|n• Gib Zeitverlorene Abzeichen beim Event-Händler aus.|n• Läuft ~30. Juni – 11. Aug. (Datamined — beim Launch bestätigen.)",

	CODEX_DELVER_CALL_TITLE = "Delver's Call",
	CODEX_DELVER_CALL_BODY = "• Eine Quest pro Midnight-Tiefe: Schließ diese Tiefe einmal ab, auf einem beliebigen Tier. Jeder Charakter kann jede davon einmal machen — sie kommen nicht jede Woche wieder.|n• Sie geben viel XP, und die Belohnung wächst mit deinem Level. Beim Leveln: Schließ die Tiefen früh ab und gib die Quests spät ab (um Level 87-88).|n• |cffffffffAccount snapshot|r zeigt, welche Charaktere noch abgeschlossene Calls halten (gebankt).|n• Bewege den Cursor über die Delver's-Call-Zeile im Snapshot für Details pro Charakter.",

	CODEX_ACCOUNT_TITLE = "Account snapshot",
	CODEX_ACCOUNT_BODY = "• Schreibgeschützte Übersicht der Charaktere, mit denen du dich mit Midnight Helper angemeldet hast.|n• Sortiere/filtere nach Vault bereit, Keys, Shards-of-Dundun-Cap, inaktiv seit Reset usw.|n• Beantwortet: „Welcher Twink hat noch eine Vault-Belohnung, Keys oder Delver's Calls offen?“|n• Der Weltboss und die Wochenquests in Silbermond stehen im Tab |cffffffffThis Week|r, nicht hier.|n• Ersetzt nicht das Anmelden auf einem Twink für Gear- oder Quest-Checks.",

	CODEX_CUR_COFFER_KEY_TITLE = "Restored Coffer Key",
	CODEX_CUR_COFFER_KEY_BODY = "• Öffnet den |cffffffffBountiful Coffer|r am Ende einer Bountiful-Tiefe. Um eine Tiefe zu betreten, brauchst du keinen.|n• Wird aus 100 Coffer Key Shards gemacht — beim Betreten einer Tiefe werden sie für dich kombiniert. Ab Delver's Journey Rang 6 kannst du außerdem 2 pro Woche bei Naleidea Rivergleam im Delver's HQ kaufen.|n• Jeder Charakter hat seine eigenen Keys. Deinen Bestand siehst du im Tab |cffffffffTiefen & Kammer|r; die Account snapshot zeigt den Rest.",

	CODEX_CUR_SHARDS_TITLE = "Coffer Key Shards",
	CODEX_CUR_SHARDS_BODY = "• 100 Shards ergeben einen Restored Coffer Key. Beim Betreten einer Tiefe werden sie für dich kombiniert.|n• Sie kommen aus der offenen Welt: Das Spiel nennt Schätze, Weltquests und Welt-Events, und Rares geben sie auch.|n• Wöchentliches Verdienst-Cap von 600 — verfolge 'Weekly: X / Y' im Delves-Tab. Das sind etwa sechs Keys pro Woche. Ab Delver's Journey Rang 10 gibt jede Quelle mehr.",

	CODEX_CUR_UNDERCOIN_TITLE = "Undercoin",
	CODEX_CUR_UNDERCOIN_BODY = "• Tiefen-Währung. Sie fällt aus den Truhen am Ende einer Tiefe — am meisten aus Bountiful-Tiefen auf höheren Tiers.|n• Ausgeben kannst du sie bei |cffffffffNaleidea Rivergleam|r im Delver's HQ in Silbermond: Kosmetik, Dekor, Spielzeuge und der L00T RAID-R Mini. Ab Delver's Journey Rang 6 verkauft sie dir dafür auch deine 2 wöchentlichen Restored Coffer Keys.|n• Ab Delver's Journey Rang 5 erscheint |cffffffffZah'ran|r am Ende einer Tiefe ab Tier 6. Er verkauft Champion-Ausrüstung für Undercoin, und sein Angebot wechselt bei jedem Lauf.",

	CODEX_CUR_MANA_TITLE = "Untainted Mana-Crystals",
	CODEX_CUR_MANA_BODY = "• Kauft Hero-Ausrüstung bei |cffffffffZah'ran|r, dem Händler, der am Ende einer Tiefe ab Tier 6 erscheint.|n• Erst ab Delver's Journey Rang 9: dann können Bountiful Coffers auf Tier 11 sie enthalten (oder ein Hero-Item), und Tier 8-10 geben kleinere Mengen.|n• Account snapshot kann Summen pro Charakter zeigen.",

	CODEX_CUR_ACCOLADES_TITLE = "Field Accolades",
	CODEX_CUR_ACCOLADES_BODY = "• Geteilte Währung für die |cffffffffVoid & Rituals|r-Systeme: Du verdienst sie in Ritual Sites und Void Assaults.|n• Ausgeben im Basar in Silbermond: |cffffffffMaren Silverwing|r verkauft Ausrüstungs-Caches (Saison 2: Adventurer-Ausrüstung für 200, Veteran-Ausrüstung für 500 zufällig oder 750 für einen Platz deiner Wahl), |cffffffffTriam Dawnsetter|r verkauft Kosmetik.|n• Live-Anzeige im Tab |cffffffffVoid & Rituals|r.",

	CODEX_CUR_DAWN_TITLE = "Crests",
	CODEX_CUR_DAWN_BODY = "• Die Währung, mit der du Ausrüstung Rang für Rang aufwertest: 20 Crests pro Rang, und jede Track nimmt nur ihren eigenen Crest. Nicht an deine Schlachtzugsplätze in der Großen Schatzkammer gebunden.|n• Auch Handwerker nutzen sie: Crests bestimmen die Gegenstandsstufe eines hergestellten Teils.|n• Live-Crest-Stände stehen auf |cffffffffBasics -> Crests|r (nicht in dieser Liste).|n• Bis zur Woche des 20. Oktober gibt es ein Limit. Es zählt, wie viele du in dieser Saison verdient hast, nicht wie viele du gerade besitzt — Ausgeben schafft also keinen Platz. Es steigt jede Woche um 100. Ab der Woche des 20. Oktober fällt das Limit weg.|n• Nicht dasselbe wie Tiefen-Keys — siehe jenen Guide für die Ausgabeziele.",
	CODEX_TRACKS_TITLE = "Gear upgrade tracks",
	CODEX_TRACKS_BODY = "• Ausrüstung hat nicht nur eine Gegenstandsstufe — sie liegt auf einer |cfffffffftrack|r. Von niedrig nach hoch: |cffffffffAdventurer|r (grün), |cffffffffVeteran|r, |cffffffffChampion|r, |cffffffffHero|r, |cffffffffMyth|r.|n• Steht |cffffffffHero 3/6|r im Tooltip, heißt das: Hero-Track, Rang 3 von 6. Jeder gekaufte Rang bringt Gegenstandsstufe.|n• Die Track bestimmt deine Obergrenze — der Tooltip zeigt die erreichbare Gegenstandsstufen-Spanne. Höher kommst du nur mit einem Drop einer höheren Track.|n• Jede Track hat ihre eigene Crest-Farbe. Schwerere Inhalte lassen Ausrüstung auf einer höheren Track fallen — so steigst du auf.|n• Track entwachsen? Tausche niedrigere Crests bei |cffffffffVaskarn|r. Aufwerten bei |cffffffffCuzolth|r in Silbermond — ein Rang kostet die Crests dieser Track plus etwas Gold.|n• Jede Track hat einen Erfolg fürs Entwachsen, benannt nach dem Crest der Saison — in Season 2 die «…of the Mist»-Reihe. Er halbiert die Crest-Kosten dieser Track für deine anderen Charaktere und lässt diesen Charakter (Adventurer bis Hero) diesen Crest bei Vaskarn hochtauschen: 30 gegen 10 der nächsten Stufe.|n• Live-Stände und Wegpunkte: |cffffffffBasics -> Crests|r.",

	CODEX_DELVES_INTRO_TITLE = "Midnight-Tiefen — Übersicht",
	CODEX_DELVES_INTRO_BODY = "• Kurze instanzierte Läufe für 1 bis 5 Spieler, mit Valeera als Begleiterin — in Quel'Thalas und auf der Gewundenen Insel.|n• |cffffffffTier 1–11|r. Ab Tier 4 brauchst du Level 90 und die Midnight-Kampagne, einmal auf deiner Kriegsmeute abgeschlossen; danach schaltet jeder geschaffte Tier den nächsten frei.|n• Die Ausrüstung wird ab |cffffffffTier 8|r nicht mehr besser: Bountiful Coffer 295, Große Schatzkammer 305 (Hero 1/6). Tier 11 gibt trotzdem bessere Wappen.|n• Hineingehen kostet nichts — kein Key nötig. Eine |cffffffffGroßzügige|r Tiefe (bis zu vier am Tag) endet mit einem Bountiful Coffer, und diese Truhe braucht einen |cffffffffRestored Coffer Key|r (siehe Currencies).|n• Nutze 'Find Nearest Bountiful Delve' im Delves-Tab.",

	CODEX_DELVE_COACH_TITLE = "Delve Coach",
	CODEX_DELVE_COACH_BODY = "• Schwebendes Tipp-Panel: Route, Trash und Bossmechaniken pro Tiefe.|n• Öffnet sich von selbst, wenn du eine Tiefe betrittst, oder über |cffffffffDelve Coach (preview tips)|r / |cffffffff/mh coach|r.|n• Die Tipps stehen in der Sprache deines Spiels; `/mh lang` wechselt zwischen Englisch und Niederländisch.|n• Boss-Spotlight: scrolle auf dem Modell zum Zoomen (pro Boss gespeichert).|n• Blaue Zaubernamen verlinken echte Zauber-Tooltips, wenn die IDs bekannt sind.",

	CODEX_DELVE_CURIOS_TITLE = "Valeera & Tiefen-Curios",
	CODEX_DELVE_CURIOS_BODY = "• Valeera hat drei Plätze, die du selbst füllst: ein |cffffffffPoison|r, ein |cffffffffCombat Curio|r und ein |cffffffffUtility Curio|r. Ihre Rolle (Tank, Heiler oder DPS) ist eine eigene Wahl.|n• Du änderst sie bei den Vorräten am Anfang einer Tiefe und an ihrem Checkpoint, wo du auch reparierst.|n• Saison 2 hat sechs Gifte: drei von Anfang an, drei weitere nach Valeeras Einführungsquests für Saison 2 (Seasonal Refresher: Midnight, dann Slithering Spoils).|n• |cffffffff/mh curios|r zeigt in den eigenen Worten des Spiels, was jede Option tut, mit einem Stern bei dem, was die meisten Guides wählen. Neben ihrem Fenster öffnet sich ein kleines Feld mit dieser Auswahl.|n• Das Tiefen-Item-Popup verfolgt RAID-R Mini und Trovehunter's Bounty.",

	CODEX_TORMENTS_TITLE = "Venomfall Deeps (Nemesis-Tiefe)",
	CODEX_TORMENTS_BODY = "• Die Nemesis-Tiefe der Saison 2, im Norden der Gewundenen Insel: {WAY:2512:51.23:30.26:Venomfall Deeps}. Der Boss ist |cffffffffAzta'rec|r, auf Schwierigkeit |cffffffff?|r oder |cffffffff??|r.|n• Zum Freischalten schließe eine beliebige Tiefe auf Tier 7 mit mindestens einem übrigen Leben ab (für ?), oder eine beliebige Tiefe auf Tier 10 mit einem übrigen Leben (für ??).|n• Der Eingang empfiehlt Gegenstandsstufe 290 für ? und 309 für ??.|n• Nur in dieser Saison: Ihn zu besiegen gibt den Erfolg My Venomous Nemesis (ein Rücken-Transmog); auf ?? ohne andere Spieler Let Me Solo Him: Azta'rec (das Reittier Apophic Soul Crusher).|n• Torment's Rise und Nullaeus waren der Nemesis von Saison 1.|n• Der Delve Coach hat den Kampfplan.",

	CODEX_DELVE_LOG_TITLE = "Delve Log",
	CODEX_DELVE_LOG_BODY = "• Pro Charakter ein Protokoll jeder Midnight-Tiefe und jedes Ritual-Site-Laufs, den du abschließt: Tier, Zeit und Tode — bei Tiefen außerdem, ob du einen Key benutzt hast, und der Endboss.|n• Das läuft von selbst; der Tab muss nicht offen sein.|n• Praktisch, um zu sehen, welchen Tier du zuletzt geschafft hast und wie lange es gedauert hat.|n• Suchst du einen Eingang? |cffffffffFind Nearest Delve|r steht im Tab |cffffffffTiefen & Kammer|r.",

	CODEX_MPLUS_TITLE = "Mythic+ & Dungeon-Vault",
	CODEX_MPLUS_BODY = "• Mythic+ füllt die |cffffffffDungeons|r-Reihe der Großen Schatzkammer (getrennt von Tiefen-/Welt-Reihen). Heroische, Mythisch-0- und Zeitwanderungs-Dungeons zählen dort auch, mit geringerer Belohnung.|n• Ein höherer Key gibt ein höheres Item-Level im Vault. Ob in der Zeit oder nicht, jeder abgeschlossene Key zählt. Diese Saison steigt es ab +10 nicht mehr.|n• Deine drei Optionen nutzen deinen besten, viertbesten und achtbesten Key der Woche.|n• Vault Advisor hat nur für Heiler eigene M+-Stat-Gewichtungen; Tanks und Schadensverursacher bekommen für Schlachtzug und M+ dieselben Gewichtungen.|n• Midnight Helper ersetzt kein Routen-Addon — nutze MDT / Notizen für Affix-Wochen.",
	CODEX_MPLUS_START_TITLE = "Mythisch+ ab deinem ersten Key",
	CODEX_MPLUS_START_BODY = "Mythisch+ ist ein normaler Dungeon mit einem |cffffcc00Schlüsselstein|r: einem Key mit einer Stufe, etwa +2 oder +3. Höhere Keys sind schwerer und geben bessere Beute, und jeder Key, den du abschließt, zählt für deine |cffffcc00Große Schatzkammer|r.|n|n|cffffcc00Dein erster Key|r|n• Schließe einen Mythic 0-Dungeon ab: Der letzte Boss gibt dir einen Key.|n• Oder spiel beim Key von jemand anderem mit: Wenn er fertig ist, bekommst du auch einen.|n• Deinen verloren oder nie einen gehabt? |cffffffffLindormi|r in Silvermoon City, neben dem Portal zu The Timeways, gibt dir einen.|n• Du hast immer nur einen Key, und er beginnt bei +2.|n|n|cffffcc00Einer Gruppe beitreten|r|n• Drücke |cffffffffI|r, öffne |cffffffff{UI:GROUP_FINDER}|r, dann |cffffffff{UI:LFGLIST_NAME}|r und |cffffffffDungeons|r. Mythische Dungeons haben keine Warteschlange.|n• Wähle einen niedrigen Key, +2 bis +4. Gruppen mit |cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r rechnen mit neuen Spielern.|n• Klicke auf |cffffffff{UI:SIGN_UP}|r, hake deine Rolle an und warte, bis der Anführer dich einlädt.|n|n|cffffcc00Eigene Gruppe gründen|r|n• Am selben Ort: Klicke auf |cffffffff{UI:START_A_GROUP}|r, wähle den Dungeon deines Keys, wähle einen Spielstil (|cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r passt) und klicke auf |cffffffff{UI:LIST_GROUP}|r.|n• Stell den Dungeon-Schwierigkeitsgrad auf |cffffffffMythisch|r, bevor du hineingehst.|n• Drinnen klickt der Key-Besitzer auf den |cffffffffFont of Power|r nahe dem Eingang, legt den Key hinein und drückt |cffffffff{UI:CHALLENGE_MODE_START_CHALLENGE}|r. Nach einem 10-Sekunden-Countdown läuft die Zeit.|n|n|cffffcc00Während des Laufs|r|n• Auf +2 bis +5 kostet ein Tod keine Zeit, und markierte Gegner zeigen dir eine Route. Ab +6 kostet jeder Tod Zeit.|n• Ab +5 kommt eine zusätzliche Regel der Woche dazu. Der Reiter |cffffffff{UI:CHALLENGES}|r im Gruppenfinder zeigt, welche.|n• In der Zeit: Dein Key steigt um 1 bis 3 Stufen. Zu spät: Du bekommst trotzdem Beute, aber der Key sinkt um 1 Stufe. So oder so wechselt er zu einem anderen Dungeon.|n• Musst du aufhören? Tippe |cffffffff/abandon|r, um eine Abstimmung zu starten. Einfach zu gehen kann dich als Keystone Deserter markieren.|n• Am Ende öffnet jeder die Truhe für seine eigene Beute.|n|n|cffffcc00Hilfe|r|n• Sag es in der Gruppe: 'first time in this dungeon' (zum ersten Mal in diesem Dungeon). Auf niedrigen Keys erklären die meisten Spieler gern.|n• Frag deine Gilde oder schau in |cffffffff{UI:COMMUNITIES_GUILD_FINDER}|r und |cffffffffFind a Community|r im Fenster Gilde & Communitys (J).|n• Deine |cffffffff{UI:DUNGEON_SCORE}|r steht auf dem Reiter {UI:CHALLENGES}. Viele Anführer schauen auch auf die Raider.IO-Wertung.|n|nMidnight Helper hilft drinnen: Bosstipps öffnen sich, wenn du hineingehst, und |cffffffff/mh mplus|r zeigt deinen besten Lauf pro Dungeon und wo ein Key am meisten bringt.",
	CODEX_AGGRO_TITLE = "Aggro: wen greift der Gegner an?",
	CODEX_AGGRO_BODY = "Aggro heißt, dass ein Gegner dich angreift. Der Tank will das; ein DPS oder Healer, der es zieht, stirbt oft. Das Spiel kann dich schon warnen, aber bei vielen Spielern sind diese Warnungen ausgeschaltet. Midnight Helper stellt nichts davon für dich um: tippe |cffffffff/mh aggro|r, um zu sehen, wie sie bei dir eingestellt sind.|n|n• |cffffffff{UI:NAMEPLATE_OPTIONS_LABEL} > {UI:UNIT_NAMEPLATES_THREAT_DISPLAY}|r: hake |cffffffff{UI:UNIT_NAMEPLATES_THREAT_DISPLAY_FLASH}|r an. Die Namensplakette eines Gegners blinkt, wenn der Tank ihn verliert oder wenn ein DPS oder Healer ihn zieht.|n• |cffffffff{UI:COMPACT_UNIT_FRAME_PROFILE_DISPLAYAGGROHIGHLIGHT}|r (Schlachtzugsfenster): ein roter Rahmen um den, der Aggro hat. Praktisch für Healer.|n• |cffffffff{UI:ACCESSIBILITY_AUDIO_LABEL} > {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} > {UI:CAA_SAY_IF_TARGETED_LABEL}|r: eine Stimme sagt dir, wenn ein Gegner dich ins Ziel nimmt. Schalte zuerst {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} ein; diese Einstellung wird pro Spezialisierung gespeichert.|n|nNutzt du ein Addon für Namensplaketten wie Plater? Dann kommt das Blinken auf den Namensplaketten von diesem Addon, nicht vom Spiel: sieh in dessen eigenen Einstellungen nach.",

	CODEX_RAID_VAULT_TITLE = "Schlachtzug — Große Schatzkammer",
	CODEX_RAID_VAULT_BODY = "• Schlachtzugsbosse füllen die Schlachtzugsreihe der Schatzkammer: 2, 4 und 6 Bosse schalten eine, zwei und drei Optionen frei. Jede Schwierigkeit zählt, auch der Schlachtzugsbrowser, und ebenso der Lair-Boss.|n• In Saison 2 kommt jede Option aus einer Schwierigkeit höher als die, auf der du die Bosse getötet hast: Schlachtzugsbrowser gibt Champion, Normal gibt Hero, Heroisch gibt Myth, Mythisch gibt Myth auf höherer Stufe.|n• Gemischte Schwierigkeiten: Jede Option nutzt die höchste Schwierigkeit, auf der du diese Anzahl Bosse erreicht hast. Die Vault-UI zeigt, was du diese Woche hast.|n• Crests gibst du danach aus, um Schlachtzugsausrüstung aufzuwerten.",

	CODEX_VAULT_ADVISOR_TITLE = "Großer-Schatzkammer-Advisor",
	CODEX_VAULT_ADVISOR_BODY = "• Seitenpanel neben Blizzards Fenster der Großen Schatzkammer, wenn du deine Belohnung an der Großen Schatzkammer in Silbermond wählst — nicht in den Midnight-Helper-Tabs. SHIFT-J zeigt nur eine Übersicht, deshalb erscheint das Panel dort nicht.|n• Bewertet Vault-Stücke gegen angelegtes Gear anhand der Guide-Stat-Prioritäten (und optional Pawn).|n• Umschaltbar in den Minimap-Schnelleinstellungen / Esc -> AddOns -> Midnight Helper.|n• Profil Auto vs. Schlachtzug vs. M+ für Stat-Gewichtungen.",

	CODEX_WORLD_HUB_TITLE = "Void & Rituals — ein System",
	CODEX_WORLD_HUB_BODY = "• Seit Patch 12.0.5 funktionieren |cffffffffRitual Sites|r und |cffffffffVoid Assaults|r als ein System. Beide wechseln jede Woche zwischen Eversong Woods und Zul'Aman, und sie teilen sich eine Währung und einen Renown.|n• Gleiche |cffffffffField Accolades|r und Bazaar-Hub — farme sie nicht als zusammenhanglose Aktivitäten.|n• Saison 2 hat die Ausrüstung, die du mit Field Accolades kaufst, auf Abenteurer und Veteran gesenkt: praktisch für einen neuen Charakter, nicht für Top-Ausrüstung.|n• Öffne den kombinierten Tab für die aktive Site und Zone dieser Woche, deine Field Accolades und deinen Renown sowie Routen-Buttons.",

	CODEX_RITUAL_TITLE = "Ritual Sites",
	CODEX_RITUAL_BODY = "• Ein instanziertes Ritual für 1 bis 5 Spieler. Jede Woche findet es an einem von zwei Orten statt: Daggerspine Point in Eversong Woods oder der Broken Throne in Zul'Aman. Wähle einen Tier und schließe ihn ab für Accolades, Renown und Beute.|n• Nur eine Site ist gleichzeitig aktiv; das Addon hebt hervor, welche.|n• Der Ritual-Site-Pin im SMC City Guide setzt eine Route zur aktiven Site dieser Woche. Kennt das Addon sie noch nicht, öffnet der Pin den Tab Void & Rituals.",

	CODEX_VOID_TITLE = "Void Assaults",
	CODEX_VOID_BODY = "• Die Leere greift Eversong Woods oder Zul'Aman an — jede Woche eines von beiden. Erledige Void Strikes; genug davon starten eine größere Void Incursion. Beides bringt Field Accolades.|n• Teilt sich Field Accolades und den Ritual-Sites-Renown mit den Ritual Sites — du bringst beides gleichzeitig voran.|n• Der Tab Void & Rituals zeigt die Zone dieser Woche, die Zone der nächsten Woche und deine Wochenquest.",

	CODEX_RARES_TITLE = "Midnight-Rares",
	CODEX_RARES_BODY = "• Wöchentliche Rare-Mobs mit Account-/Charakter-Beute (prüfe die Regeln jedes Rares im Spiel).|n• Tab |cffffffffRares|r: verfolge Kills und baue eine Route, das nächstgelegene Rare zuerst. Der Routenpfeil (der von Midnight Helper oder der von TomTom, wenn du es nutzt) geht danach zum nächstgelegenen weiter.|n• Live-Warnung, wenn ein verfolgtes Rare in der Nähe ist (~500 yd) — umschaltbar in den Einstellungen.",

	CODEX_PROF_TITLE = "Berufe — wöchentlicher Ablauf",
	CODEX_PROF_BODY = "• Jeder Beruf hat seine eigenen |cffffffffWissenspunkte (KP)|r und seine eigene |cffffffffTatkraft des Handwerkers|r: Alchemie-Tatkraft kauft nur Alchemie-Sachen.|n• |cffffffffJede Woche, pro Beruf:|r die Wochenquest deines Lehrers in Silbermond (ab Fertigkeit 25), |cffffffffPatron orders|r am Crafting-Orders-Tisch, die Wissen geben (die größte wöchentliche Quelle), bis zu zwei Wissensgegenstände aus gewöhnlichen Schätzen in den Midnight-Zonen und ein Thalassian Treatise (hergestellt von Inschriftenkunde).|n• Sammler und Verzauberer bekommen außerdem Wissensgegenstände durch Sammeln oder Entzaubern. Damit holst du eine verpasste Woche auf; bei den meisten anderen wöchentlichen Quellen geht das nicht.|n• |cffffffffAbundance|r ist ein eigener Pfad: Ein Shard of Dundun (höchstens 8 pro Woche) startet eine Abundant Harvest, und die bringt Unalloyed Abundance.|n• Tab |cffffffffBerufe|r: nicht ausgegebene KP, deine Shards of Dundun und Kartenpins für Schätze und Bücher. Wo du KP ausgibst: der Basics-Guide.",

	CODEX_PROF_GUIDE_TITLE = "Berufe — Einsteiger-Guide",
	CODEX_PROF_GUIDE_BODY = "• Unter-Tab |cffffffffBasics -> Berufe|r: schrittweiser KP-Plan und Combo-Vorschläge.|n• Der Unter-Tab |cffffffffCrests|r handelt von Crests: der Währung, mit der du Ausrüstung aufwertest, verdient in vielen Aktivitäten — nicht nur in Schlachtzügen.|n• Nach Patches erneut lesen — Zahlen und Caps können sich ändern.",
	CODEX_PROFRESET_TITLE = "Berufsspezialisierungen zurücksetzen (12.1)",
	CODEX_PROFRESET_BODY = "• Patch 12.1 lässt dich deine Midnight-Spezialisierungen zurücksetzen — einmal pro Beruf.|n• |cffffffffBei wem:|r Theremis, im Basar von Silbermond neben den Handwerksaufträgen. Er bietet pro Beruf eine eigene Zeile, du kannst also Schmiedekunst zurücksetzen und Verzauberkunst unangetastet lassen.|n• |cffffffffWas du zurückbekommst:|r jeden Wissenspunkt, den du in den Midnight-Bäumen dieses Berufs ausgegeben hast, frei neu verteilbar.|n• |cffffffffWas es kostet:|r die Warnung des Spiels lautet „You will lose all associated recipes“.|n• |cffffffffZugehörige, nicht alle.|r Weg ist, was diese Spezialisierungen freigeschaltet hatten. Rezepte von einem Lehrer, aus Beute oder aus einer Quest liegen außerhalb der Bäume und bleiben. Bei einer zurückgesetzten Verzauberkunst beobachtet: die Rezeptliste war unberührt und das ausgegebene Wissen stand wieder auf dem Zähler.|n• |cffffffffEs ist einmalig.|r Die Bestätigung sagt ONCE in Großbuchstaben, und zwar pro Beruf — einen zweiten Versuch gibt es nicht, wenn der neue Weg enttäuscht.|n• Entscheide also |cffffffffvorher|r, wohin die Punkte gehen. Die Berufe-Seite nennt den zu füllenden Baum und den genauen Knoten.|n• Kommen die genommenen Rezepte zurück, wenn du identisch neu verteilst? Das Spiel sagt es nirgends. Plane so, als würden sie es nicht.",
	CODEX_CORRPOWER_TITLE = "Corrosive Codex — welches Gift nehme ich zuerst?",
	CODEX_CORRPOWER_BODY = "|cffffcc00Zwölf Gifts, und benutzen darfst du eins.|r Jedes kostet |cffffffff8 Corrosive Souls|r, alle zwölf zusammen also 96. Weil der Preis überall gleich ist, geht es bei deiner ersten Wahl um |cffffffffdas, was du brauchst|r — nie darum, was du dir leisten kannst.|n|n|cffffff78Eine Sache erklärt das ganze System|r|n• Es ist ein |cffffffffGiftkreislauf|r. Die Hälfte der Gifts wird stärker gegen einen Gegner, der Poisoned ist, oder während |cffffffffdu selbst|r vergiftet bist.|n• Deshalb besteht jedes gute Paar aus |cffffffffeinem Gift, das vergiftet + einem, das davon profitiert|r. Hast du das einmal gesehen, wirken die Kombinationen nicht mehr zufällig.|n|n|cffffff78Welches zuerst? Wähle nach deinem Problem, nicht nach einer Liste|r|n• |cffffffffIch will einfach mehr Schaden|r → |cffffffffUla'tek's Gift|r. Wirkt für sich allein, ohne zweites Gift und ohne Vorbereitung. Jeder Guide, den wir gelesen haben, nennt dieses zuerst.|n• |cffffffffGruppen von Gegnern dauern zu lange|r → |cffffffffPlague of Corrosion|r oder |cffffffffOphidian Maw|r.|n• |cffffffffIch sterbe ständig in Tiefen|r → |cffffffffVirulent Mucus|r fängt die großen Treffer ab, |cffffffffGorgoneion Gaze|r versteinert alles um dich herum, sobald du unter die Hälfte deines Lebens fällst.|n• |cffffffffZauberer bringen ihren Spruch durch|r → |cffffffffAccursed Poison|r. Das unterbricht einen für dich.|n|n|cffffcc00Vorsicht bei Mephitic Cloud.|r Es lässt betroffene |cffffffffGegner|r heilen, was sie angreifen. In einer Gruppe arbeitet das gegen dich.|n|n|cffffff78Was wir selbst gemessen haben, und was nicht|r|n• |cffffffffAus dem Spiel:|r der Preis von 8 und der vollständige Text von Ula'tek's Gift. Die gehören uns.|n• |cffffffffAus Guides:|r die Reihenfolge oben und wie viele Gifts den zweiten Platz öffnen. Das Spiel selbst sagt nur \"until your offerings are sufficient\" und nennt keine Zahl. |cffffffffSechs Quellen sagen 8|r — darunter Wowheads eigene Zauber-Seite, die es in einer Tabelle festhält — und ein Blog sagt 6. 8 stimmt also mit ziemlicher Sicherheit; wir haben es nur selbst noch nicht gesehen. Du weißt es in dem Moment, in dem dein zweiter Platz erscheint.|n• Ula'tek's Gift wurde |cffffffffbereits einmal abgeschwächt|r. Eine Rangliste vom August ist also nicht automatisch heute noch wahr — genau deshalb ist der Giftkreislauf oben der Teil, den du dir merken solltest.",
	CODEX_ATALUTEK_TITLE = "Die Vaults of Atal'Utek — was es dort gibt, und wo",
	CODEX_ATALUTEK_BODY = "|cff8fd3ffZum Einstieg|r|n|n• |cffffffffWas es ist:|r ein 12.1-Gebiet auf der Coiled Isle mit eigener Karte, und darunter eine zweite Karte, die Underbelly. Es ist bereits offen — kein Saisontor davor.|n|n• |cffffffffWie du hineinkommst:|r eine Kette aus vier Quests — |cffffffffInto the Vaults of Atal'Utek|r, dann |cffffffffVaults of Atal'Utek: One Coin Too Many|r und |cffffffffVaults of Atal'Utek: A Toxic Tour|r, die du zusammen bekommst, dann |cffffffffVaults of Atal'Utek: The Altar of Corrosion|r. Alles Weitere liegt dahinter, also mach die zuerst. |cffffffffA Toxic Tour ist eine einmalige Story-Quest, keine Daily|r — sie verlangt eine Patrol, einen Strike, eine Incursion und einen Ancient Foe und erledigt sich damit von selbst, während du die unten beschriebene Runde drehst.|n|n|cff8fd3ffWas du hier machst|r|n|n• |cffffffffWas du hier wirklich tust — vier Dinge, und sie füttern einander.|r |cffffffffTemple Patrols|r ziehen über die Karte und wechseln etwa alle zehn Minuten; am leichtesten einzusteigen, und fast immer läuft eine. |cffffffffTemple Strikes|r sind größer und bauen auf eine Incursion hin. Sind genug Strikes erledigt, beginnt eine |cffffffffTemple Incursion|r, und jede Incursion endet damit, dass ein |cffffffffAncient Foe|r erwacht — daher kommen die drei seltenen Elitegegner: nur einer davon pro Woche, mit einer Zehn-Minuten-Uhr. Münzen, Schlüssel, Ausrüstung und Ruf kommen alle aus dieser Schleife. Wenn du dich fragst, was du tun sollst: Schließ dich dem an, was gerade läuft.|n|n• |cffffffffWie finde ich denn nun einen Temple Strike?|r Öffne in den Vaults deine Karte und achte auf die Event-Symbole — ein Strike ist dort markiert wie jedes Weltereignis, und |cffffffffer hat keine Uhr|r: Er bleibt stehen, bis eine Gruppe ihn beendet, du kannst also in Ruhe hinlaufen. |cffffffffEin paar Spieler reichen|r; du brauchst keine vorgefertigte Gruppe, und meist ist schon jemand dran. Es gibt sechs, jeder mit festem Startpunkt — klick einen an für einen Wegpunkt: {WAY:2509:50.55:15.70:Cursed Depths} · {WAY:2509:47.36:46.17:Overflowing Venom} · {WAY:2509:47.67:46.34:Profane Pyres} · {WAY:2509:47.26:26.69:Purifying Earth and Sky} · {WAY:2509:39.32:39.92:Ruuk’Jar’s Clutch} · {WAY:2613:52.25:36.27:The Underbelly}.|nZeigt die Karte keinen Strike, läuft wahrscheinlich gerade eine Incursion oder ihr Ancient Foe — schließ dich stattdessen dem an. Ein neuer Strike erscheint, sobald das vorbei ist.|n|n• |cffffffffFortbewegung im Inneren.|r Die |cffffffffAmani Windcallers|r fliegen dich zwischen drei Punkten in den Vaults — dem Knotenpunkt |cffffffffAmani Foothold|r, dem Eastern Amani Outpost und dem Northern Amani Bulwark. Flugmeister |cffffffffEagletender Mal’Tiki|r steht bei {WAY:2509:44.42:62.21:Amani Foothold}. Fliegen geht in den Vaults nicht, und genau deshalb gibt es sie — es ist größer, als es aussieht, und laufen ist der langsame Weg.|n|n• |cffffffffDie wiederholbaren Quests — eine Weekly und acht Dailies.|r |cffffffffPurging the Vaults|r bei |cffffffffWarleader Abdumati|r im Amani Foothold ist die Weekly, die du nicht auslassen willst. Die acht Dailies sind |cffffffffPatrolling the Temple|r, |cffffffffBounty of the Cursed|r, |cffffffffRelentless Strikes|r, |cffffffffDecisive Incursions|r, |cffffffffFrom Whence it Came|r, |cffffffffEssence of Malice|r, |cffffffffWhat's Out There?|r und |cffffffffShoulder to Shoulder|r — nimm, was deine Karte dir heute anbietet. Die meisten verlangen die Aktivitäten von oben, sie haken sich also von selbst ab, während du spielst. Zwei wollen, dass du in einer Gruppe bist (What's Out There? und Shoulder to Shoulder): Die Leute, die ohnehin neben dir stehen, reichen, keine Premade. Und eine, die du hier nie finden würdest: |cffffffffMidnight: Vaults of Atal'Utek|r ist eine Wochen-Meta für diesen Ort, die du in |cffffffffSilvermoon|r abholst.|n|n|cff8fd3ffCoin and Soul|r|n|n• |cffffffffCorrosive Coin|r ist die Währung der Zone. Mit den Worten des Spiels: „Spirits of the Amani within the Vaults of Atal'Utek deal exclusively in this phantasmal token.“ Dein Bestand ist die Zahl über diesem Artikel.|n|n• |cffffffffCorrosive Soul ist das nicht.|r Es ist überhaupt keine Währung, sondern ein |cffffffffGegenstand|r in deinen Taschen, und genau das will der Corrosive Codex als Opfergabe von dir. Guides vertauschen die beiden Namen ständig; das Spiel nie. Wenn dir etwas sagt, du sollst Corrosive Coins am Codex ausgeben, ist das die Verwechslung.|n|n• |cffffffffWohin die Münzen gehen — zwei Stellen, beide bei Er’inye|r bei {WAY:2509:51.10:62.76:Er'inye}. Mit ihr zu reden kauft |cffffffffCorrode Spirit|r, und das speist den Altar-Baum; neben ihr ist der |cffffffffSkull of Er’inye|r ein Händler mit drei Seiten Reittiere, Haustiere, Ensembles und Rezepte, von 500 bis 25.000 Münzen. |cffffffffDer Corrode-Preis steigt bei jedem Kauf|r — bei einem Besuch 1.500 und dann 2.000 gesehen — lies also das Fenster, statt auf eine Zahl zu sparen.",
	CODEX_ATALUTEK_DISC_TITLE = "Altar of Corrosion: die vier Schlüssel",
	CODEX_ATALUTEK_DISC_BODY = "• |cffffffffDer Altar of Corrosion|r ist der Knotenbaum, den die letzte Quest der Kette öffnet. Das meiste öffnet sich beim Ausgeben, aber |cffffffffvier Knoten liegen hinter einem Schlüssel, den du selbst finden musst|r — und alle vier funktionieren gleich: Ein Gegenstand fällt, du benutzt ihn an einem Objekt irgendwo in den Vaults, das gibt einen Questgegenstand, und Er’inye macht den Rest.|n|cffffffffCorroded Key|r → die Venom-Worn Coffer → |cffffffffRun of the Vaults|r (Glideways, oder Swift Steps) · |cffffffffSpirit Loupe|r → die Feather of Tok’jara bei {WAY:2509:48.46:25.80:Feather of Tok'jara} → |cffffffffSpectral Winds|r (Spirit Walk, oder Spectral Shipping) · |cffffffffExcising Knife|r → das Eye of Szarith, in einem Gifttümpel in der Underbelly → |cffffffffBroodmaster|r (+100% Schaden an Eiern, oder −75% Schaden durch Eierexplosionen) · |cffffffffDispelling Charm|r → Jin’tal’s Reliquary im Profaned Mausoleum → |cffffffffSpiritual Protection|r (geisterhafte Verbündete bei Curse Surges, oder sofort wieder aufstehen, wenn du außerhalb der Vaults stirbst).|n|cffffffffEr’inye einen Schlüssel zu zeigen schaltet nichts frei.|r Sie ist blind und sagt dir, was sie fühlt — das ist ein Hinweis darauf, wohin der Gegenstand gehört. |cffffffffWoher die Schlüssel kommen|r — da sind sich die Guides inzwischen einig: der Corroded Key aus Temple Strikes, das Excising Knife aus einer Temple Incursion, die Spirit Loupe von einem Ancient Foe. Der |cffffffffDispelling Charm|r ist die Ausnahme: Er kommt nicht aus den Events, sondern von Jin’tal im Vault of Restless Bones, während einer Nebenquestreihe über die Med’jai.|n|n• |cffffffffGib deine ersten Münzen sofort im Baum aus.|r Seine ersten vier Knoten kosten nichts und öffnen sich, während du anderswo ausgibst, und sie erhöhen die Corrosive Coin, die du verdienst, um |cffffffff25, 50, 75 und schließlich 100 Prozent|r. Der Baum zahlt sich selbst, also ist jede Runde nach der ersten ergiebiger — sparen ist die teure Wahl. Und beachte die Schieflage, die das Tempo dieser Zone bestimmt: |cffffffffMünzen haben keine Grenze|r, Corrosive Souls dagegen schon. Farme Münzen frei; plane keinen Abend um Souls herum.",
	CODEX_ATALUTEK_DEAD_TITLE = "The Honored Dead & die Rares",
	CODEX_ATALUTEK_DEAD_BODY = "• |cffffffff„The Honored Dead“ — zwölf Gedenkstätten|r auf der Vaults-Karte, ein Erfolg, und das Klarste, was man hier einfach tun kann. In einer Laufreihenfolge, von oben auf der Karte nach unten:|n{WAY:2509:46.79:7.51:To a sister 46.79, 7.51} · {WAY:2509:56.49:22.88:To a shield-bearer 56.49, 22.88} · {WAY:2509:47.22:28.77:To a father 47.22, 28.77} · {WAY:2509:42.57:33.18:To a stranger 42.57, 33.18} (unter der Brücke) · {WAY:2509:52.91:33.90:To a captain 52.91, 33.90} · {WAY:2509:55.62:40.60:To a dream 55.62, 40.60} · {WAY:2509:42.84:39.93:To sons 42.84, 39.93} · {WAY:2509:52.21:45.12:To a lover 52.21, 45.12} · {WAY:2509:38.50:47.66:To Comrades 38.50, 47.66} · {WAY:2509:55.31:48.45:To parents 55.31, 48.45} · {WAY:2509:49.50:56.59:To a daughter 49.50, 56.59} · {WAY:2509:45.81:61.79:To Failure 45.81, 61.79}|n|n• |cffffffffDie Underbelly|r ist die Karte darunter, Eingang bei {WAY:2509:47.30:11.20:The Underbelly} auf der Vaults-Karte. Dort unten lebt ein Rarer, |cffffffffSzarith the Fanged|r bei {WAY:2613:38.40:17.69:Szarith the Fanged}, und die Underbelly hat einen eigenen Erfolg: |cffffffffSoft Underbelly|r. |cffffffffSzarith allein reicht dafür nicht:|r Laut Guides verlangt der Erfolg außerdem mehrere benannte Elitegegner, die nur erscheinen, während der Temple Strike |cffffffffThe Underbelly|r läuft.|n|n• |cffffffffDrei seltene Elitegegner auf der Hauptkarte|r — Congealed Malice, Khu'tulak und Susarikk — bilden einen dritten: |cffffffffOppose the Foes|r. |cffffffffSie haben keinen festen Ort, und das ist die Antwort, keine Lücke|r: Einer der drei erwacht in dem Moment, in dem eine |cffffffffTemple Incursion|r abgeschlossen wird, und du hast etwa zehn Minuten, um ihn zu töten. |cffffffffNur einer der drei ist jede Woche in der Rotation|r, dieser Erfolg dauert also mindestens drei Wochen. Du jagst sie nicht — du beendest Incursions, und der dieser Woche kommt zu dir.",
})

merge(ns._mhLocales and ns._mhLocales.frFR, {
	TAB_CODEX = "Midnight Codex",
	CODEX_PANEL_TITLE = "Midnight Codex",
	CODEX_PANEL_INTRO = "Ton manuel pour Midnight — ce qu'est chaque système, à quoi sert chaque monnaie et où cliquer dans cet addon. Survole les icônes de monnaie pour les infobulles de Blizzard.",
	CODEX_OPEN_TAB_FMT = "Ouvrir : %s",
	CODEX_NAV_DELVES_VAULT = "Onglet Delves & Vault (bloc Grande chambre forte)",
	CODEX_NAV_DELVES_MIDNIGHT = "Onglet Delves & Vault (liste des gouffres)",
	CODEX_NAV_BASICS_DAWN = "Catégorie Basics (Crests)",
	CODEX_NAV_BASICS_PROF = "Onglet Basics (guide Métiers)",
	CODEX_BALANCE_FMT = "Tu as : |cffffffff%d|r",
	CODEX_BALANCE_UNKNOWN = "Le solde se met à jour quand tu te connectes sur ce personnage.",
	CODEX_SEARCH_OPENED = "Midnight Codex ouvert.",
	CODEX_BETA_DISABLED = "Midnight Codex est désactivé dans les Réglages (onglets bêta).",

	CODEX_CAT_START = "Pour commencer",
	CODEX_CAT_WEEKLY = "Boucle hebdomadaire",
	CODEX_CAT_CURRENCIES = "Currencies",
	CODEX_CAT_DELVES = "Delves",
	CODEX_CAT_DUNGEONS = "Dungeons & M+",
	CODEX_CAT_RAID = "Raid & Crests",
	-- ⚠️ Was "Void & Rituals" until 19 aug, and half of what sits under it is neither.
	-- The category holds Prey hunts, rares, Turbulent Timeways and Showdowns alongside
	-- the void and ritual articles. Rob went looking for Prey, read that button, and
	-- walked straight past it — the same class of fault as the twelve type-only commands
	-- on 18 aug: the feature was there, under a name nobody would guess.
	CODEX_CAT_WORLD = "World content",
	CODEX_CAT_COILEDISLE = "Coiled Isle",
	CODEX_ROUTE_BTN = "Suivre la route",
	CODEX_CAT_PROFESSIONS = "Professions",

	CODEX_START_TITLE = "Pour commencer — ta semaine Midnight",
	CODEX_START_BODY = "|cffffcc00Pense en couches :|r un reset hebdo, plusieurs pistes de récompenses. Tu n'as pas besoin de chaque système chaque jour — choisis un objectif.|n|n|cffffff781) Compte & reset|r|n• Vérifie l'onglet |cffffffffThis Week|r pour la vault, le boss de monde, les keys et les corvées.|n• |cffffffffAccount snapshot|r montre tous tes rerolls (vault, Delver's Call, hebdos de métier).|n|n|cffffff782) Contenu de combat|r|n• |cffffffffDelves|r — piste d'équipement principale (keys, paliers, slots de Grande chambre forte). Utilise |cffffffffDelve Coach|r pour des conseils par gouffre.|n• |cffffffffMythic+|r et |cffffffffRaid|r remplissent les autres slots de la Grande chambre forte (voir catégories Dungeons & Raid).|n|n|cffffff783) Monde ouvert|r|n• |cffffffffÎle Annelée|r — la zone de la Saison 2, arrivée avec le patch 12.1, avec sa propre catégorie ici.|n• Les chasses |cffffffffPrey|r comptent pour la même rangée de Grande chambre forte que les gouffres.|n• Onglet |cffffffffVoid & Rituals|r — Field Accolades, Ritual Sites, Void Assaults (même piste de renom).|n• Onglet |cffffffffRares|r — butin rare hebdo et itinéraires.|n|n|cffffff784) Artisanat|r|n• Onglet |cffffffffMétiers|r pour les KP / mats hebdo ; |cffffffffBasics|r pour les Crests.|n|n|cffffcc00Astuce :|r ouvre la catégorie |cffffffffCurrencies|r ici quand tu oublies à quoi sert un jeton. Fais défiler l'aperçu du boss dans Delve Coach pour zoomer.",
	CODEX_MIDSTART_TITLE = "Commencer la campagne Midnight",
	CODEX_MIDSTART_BODY = "|cffffcc00Au niveau 80, la quête |r|cffffffffMidnight|r|cffffcc00 arrive toute seule.|r Rien à chercher — elle tombe dans ton journal dès que tu passes 80. En dessous de 80 tu peux déjà voyager jusqu'à Lune-d'Argent, mais il n'y a encore rien à accepter là-bas.|n|n|cffffff78Où ça commence|r|n• Parle à l'|cffffffffImage of Lady Liadrin|r. Elle se tient dans plusieurs capitales, donc aussi dans la tienne.|n• Elle propose deux choses : regarder l'introduction, ou |cffffffffI have heard this tale before|r pour la passer.|n|n|cffffff78Passer l'intro ne te coûte rien|r|n• Tu ressors à |cffffffffLune-d'Argent|r et la quête suivante t'est donnée aussitôt.|n• Rien n'est verrouillé derrière l'introduction — itinéraires, points de la ville et routine hebdomadaire fonctionnent pareil.|n|n|cffffff78Choisir où commencer|r|n• Cette quête suivante, |cffffffffAdventuring in Midnight|r, t'envoie à la |cffffffffScouting Map|r du Sanctum of Light.|n• Cinq points de départ : |cffffffffArator's Journey|r, |cffffffffEversong|r, |cffffffffZul'Aman|r, |cffffffffVoidstorm|r et |cffffffffHarandar|r.|n• Survole-en un pour savoir ce qui t'y attend ; cliquer n'ouvre que son scouting report. |cffffffffRegarder ne coûte rien.|r|n|n|cffffcc00Choisi puis changé d'avis ?|r Le choix masque les quatre autres tant que la quête est dans ton journal — mais |cffffffffabandonne la quête|r et les cinq reviennent. Il fixe ton ordre, pas ton chemin.",
	CODEX_WARBAND_TITLE = "Bande de guerre & sa banque",
	CODEX_WARBAND_BODY = "|cffffcc00Ta bande de guerre|r, ce sont tous les personnages de ton compte, traités comme une seule équipe. Beaucoup de choses sont désormais |cffffffffliées à la bande de guerre|r — partagées sur tout le compte — donc tu envoies bien moins de courrier entre rerolls.|n|n|cffffff78Objets & monnaies liés à la bande de guerre|r|n• Certaines monnaies sont partagées par tout le compte ou peuvent être transférées entre personnages — ta fenêtre de monnaies indique lesquelles. Les crests d'amélioration comptent par personnage.|n• L'équipement est souvent |cfffffffflié à la bande de guerre jusqu'à équipé|r — envoie-le à un reroll, mais une fois équipé il reste sur ce personnage.|n|n|cffffff78La banque de bande de guerre|r — une banque partagée par tous tes personnages.|n• Ouvre-la chez |cffffffffn'importe quel banquier|r (ou Jeeves) — c'est un onglet de ta banque normale, à côté de ta banque de personnage.|n• Stocke tout objet |cffffffffnon lié à l'âme|r, et dépose ou retire de l'|cffffffffor|r entre personnages (même inter-factions).|n• Fabrique directement depuis elle — elle compte comme source de composants.|n|n|cffffff78Onglets & coût|r — 5 onglets, 98 emplacements chacun (490 au total). Tu commences sans aucun ; achète-les avec de l'or :|n• Onglet 1 : |cffffffff1 000 po|r|n• Onglet 2 : |cffffffff25 000 po|r|n• Onglet 3 : |cffffffff100 000 po|r|n• Onglet 4 : |cffffffff500 000 po|r|n• Onglet 5 : |cffffffff2 500 000 po|r  (les cinq = 3 126 000 po)|n|n|cffffcc00Astuce :|r 2-3 onglets suffisent à la plupart des joueurs. Ne la confonds pas avec ta |cffffffffbanque de personnage|r (à onglets depuis le patch 11.2, bien moins chère) — celle-là est par personnage ; la banque de bande de guerre est partagée.",

	CODEX_WEEKLY_RESET_TITLE = "Reset hebdomadaire",
	CODEX_WEEKLY_RESET_BODY = "• La plupart des progrès hebdomadaires se réinitialisent le jour de maintenance de ta région (EU mercredi matin, US mardi matin).|n• Les choix de Grande chambre forte, le butin du boss de monde et de nombreux plafonds hebdo se réinitialisent.|n• L'onglet |cffffffffThis Week|r affiche le temps avant le reset quand l'API le fournit.|n• Planifie les rerolls : l'|cffffffffAccount snapshot|r compare qui a encore une récompense de vault, des keys ou des Delver's Calls en attente.",

	CODEX_VAULT_TITLE = "Grande chambre forte",
	CODEX_VAULT_BODY = "• Trois lignes : |cffffffffWorld|r (gouffres, Prey et autres activités de monde), |cffffffffDungeons|r (Héroïque, Mythique, Mythic+ et Timewalking), |cffffffffRaid|r (boss de raid dans toutes les difficultés, et le boss du Lair).|n• Chaque ligne débloque jusqu'à trois choix : World à 2/4/8 activités, Dungeons à 1/4/8, Raid à 2/4/6 boss.|n• Chaque choix ne vaut que la plus faible des runs qu'il demande : le choix à 4 runs utilise ta 4e meilleure run de la semaine, le choix à 8 runs ta 8e meilleure. Une seule key difficile n'améliore que ton premier choix Dungeons.|n• Saison 2 : un choix de raid vient un cran au-dessus de ce que tu as tué — les kills en Normal donnent un objet de la track héros, les kills en Héroïque un objet de la track mythique.|n• Après le reset tu choisis |cffffffffune seule|r récompense au total parmi tous tes choix débloqués, à la Grande chambre forte de Lune-d'argent. SHIFT-J ne montre qu'un résumé.|n• Avec 3 choix débloqués ou plus, dans n'importe quelles lignes, tu peux prendre un |cffffffffNebulous Voidcore|r (un jet bonus) au lieu d'un objet.|n• |cffffffffVault Advisor|r (sur l'UI de vault de Blizzard) classe les options par rapport à ton équipement.|n• Dans cet addon, la ligne World est dans l'onglet |cffffffffGouffres & Chambre|r — déploie |cffffffffGrande chambre forte (Monde)|r. Survole un personnage dans l'|cffffffffAccount snapshot|r pour voir les trois lignes.|n• Résumé aussi dans l'onglet |cffffffffThis Week|r.",

	CODEX_WORLDBOSS_TITLE = "Boss de monde (Midnight)",
	CODEX_WORLDBOSS_BODY = "• Un boss de monde en rotation par semaine (Lu'ashal, Cragpine, Thorm'belan, Predaxas), sous forme d'expédition avec une tête de mort sur la carte. Tu n'as rien à récupérer.|n• Lady Liadrin à Lune-d'argent propose parfois |cffffffffMidnight: World Boss|r parmi ses quatre choix hebdomadaires ; tuer le boss de la semaine la termine.|n• Butin de bande de guerre : dès qu'un personnage le tue, les rerolls apparaissent comme terminés.|n• Suivi en haut de l'onglet |cffffffffGouffres & Chambre|r avec itinéraire TomTom.|n• Aussi lié depuis le SMC City Guide quand tu es à Lune-d'argent.",
	CODEX_FOLIO_TITLE = "Omnium Folio (12.0.7)",
	CODEX_FOLIO_BODY = "• Système de puissance du patch 12.0.7, toujours actif en 12.1 — un livre de minimap de |cffffffffrunes|r que tu échanges librement hors combat (aucun coût de slot).|n• La puissance vient de la chaîne |cffffffff'Seeking Knowledge'|r (5 étapes) : The Omnium Folio, Ritualized Arcana, Ley Line Assaults, Magical Primessence, Off-World Magic.|n• Chaque étape rapporte un |cffffffffMote of Omnial Inquiry|r qui ouvre la rangée de runes suivante.|n• Termine les 5 pour le haut fait méta et la décoration Sunstrider Omnium Simulacrum.|n• Des semaines manquées ? Fais les quêtes manquées à la suite pour rattraper — sans attendre les resets.|n• Rerolls : dès qu'un personnage a fait l'introduction, les autres peuvent la passer (12.1). Tes choix de runes restent propres à chaque personnage.",
	CODEX_TT_TITLE = "Turbulent Timeways (12.0.7)",
	CODEX_TT_BODY = "• Événement Marche du temps de retour — cette fois un pool de donjons |cffffffffDragonflight|r : Algeth'ar Academy, Halls of Infusion, Neltharus, Ruby Life Pools, The Azure Vault, Brackenhide Hollow.|n• Hebdo : fais |cffffffff5 donjons Marche du temps|r pour un cache d'équipement ; chaque run empile |cffffffffKnowledge of Timeways|r (buff d'XP).|n• Gagne |cffffffffMastery of Timeways|r sur 4 semaines sur 6 pour 'Master of the Turbulent Timeways' et la monture |cffffffffSpawn of Vyranoth|r.|n• Dépense les Insignes temporels chez le marchand de l'événement.|n• Du ~30 juin au 11 août. (Datamined — à confirmer au lancement.)",

	CODEX_DELVER_CALL_TITLE = "Delver's Call",
	CODEX_DELVER_CALL_BODY = "• Une quête par gouffre Midnight : termine ce gouffre une fois, à n'importe quel Tier. Chaque personnage peut faire chacune une seule fois — elles ne reviennent pas chaque semaine.|n• Elles donnent beaucoup d'XP, et le gain augmente avec ton niveau. Pendant la montée de niveau : finis les gouffres tôt, rends les quêtes tard (vers le niveau 87-88).|n• |cffffffffAccount snapshot|r montre quels personnages ont encore des calls terminés (en banque).|n• Survole la ligne Delver's Call dans le snapshot pour le détail par personnage.",

	CODEX_ACCOUNT_TITLE = "Account snapshot",
	CODEX_ACCOUNT_BODY = "• Vue en lecture seule des personnages avec lesquels tu t'es connecté avec Midnight Helper.|n• Trie/filtre par vault prête, keys, plafond de Shards of Dundun, inactif depuis le reset, etc.|n• Sert à répondre : « Quel reroll a encore une récompense de vault, des keys ou des Delver's Calls en attente ? »|n• Le boss de monde et les quêtes hebdomadaires de Lune-d'argent sont dans l'onglet |cffffffffThis Week|r, pas ici.|n• Ne remplace pas la connexion sur un reroll pour vérifier l'équipement ou les quêtes.",

	CODEX_CUR_COFFER_KEY_TITLE = "Restored Coffer Key",
	CODEX_CUR_COFFER_KEY_BODY = "• Ouvre le |cffffffffBountiful Coffer|r à la fin d'un gouffre Bountiful. Il n'en faut pas pour entrer dans un gouffre.|n• Se fabrique avec 100 Coffer Key Shards — entrer dans un gouffre les combine pour toi. Dès le rang 6 du Delver's Journey, tu peux aussi en acheter 2 par semaine chez Naleidea Rivergleam au Delver's HQ.|n• Chaque personnage a ses propres keys. Ton total est dans |cffffffffGouffres & Chambre|r ; l'Account snapshot montre le reste.",

	CODEX_CUR_SHARDS_TITLE = "Coffer Key Shards",
	CODEX_CUR_SHARDS_BODY = "• 100 shards font un Restored Coffer Key. Entrer dans un gouffre les combine pour toi.|n• Ils viennent du monde extérieur : le jeu cite les trésors, les expéditions et les événements en extérieur, et les rares en donnent aussi.|n• Plafond de gain hebdomadaire de 600 — suis 'Weekly: X / Y' dans l'onglet Delves. Ça fait environ six keys par semaine. Le rang 10 du Delver's Journey fait rapporter plus à chaque source.",

	CODEX_CUR_UNDERCOIN_TITLE = "Undercoin",
	CODEX_CUR_UNDERCOIN_BODY = "• Monnaie des gouffres. Elle tombe des coffres à la fin d'un gouffre — le plus dans les gouffres Bountiful de Tier élevé.|n• Dépense-la chez |cffffffffNaleidea Rivergleam|r au Delver's HQ de Lune-d'argent : cosmétiques, décorations, jouets et le L00T RAID-R Mini. Dès le rang 6 du Delver's Journey, elle te vend aussi tes 2 Restored Coffer Keys hebdomadaires contre cette monnaie.|n• Dès le rang 5 du Delver's Journey, |cffffffffZah'ran|r apparaît à la fin d'un gouffre de Tier 6 ou plus. Il vend de l'équipement champion contre de l'Undercoin, et son stock change à chaque run.",

	CODEX_CUR_MANA_TITLE = "Untainted Mana-Crystals",
	CODEX_CUR_MANA_BODY = "• Achète de l'équipement Héros chez |cffffffffZah'ran|r, le marchand qui apparaît à la fin d'un gouffre de Tier 6 ou plus.|n• Seulement dès le rang 9 du Delver's Journey : les Bountiful Coffers de Tier 11 peuvent alors en contenir (ou un objet Héros), et les Tiers 8-10 en donnent de plus petites quantités.|n• Account snapshot peut montrer les totaux par personnage.",

	CODEX_CUR_ACCOLADES_TITLE = "Field Accolades",
	CODEX_CUR_ACCOLADES_BODY = "• Monnaie partagée des systèmes |cffffffffVoid & Rituals|r : tu la gagnes via les Ritual Sites et les Void Assaults.|n• Dépense-la au Bazar de Lune-d'argent : |cffffffffMaren Silverwing|r vend des caches d'équipement (Saison 2 : équipement Aventurier pour 200, équipement Vétéran pour 500 au hasard ou 750 pour l'emplacement de ton choix), |cffffffffTriam Dawnsetter|r vend des cosmétiques.|n• Compteur en direct dans l'onglet |cffffffffVoid & Rituals|r.",

	CODEX_CUR_DAWN_TITLE = "Crests",
	CODEX_CUR_DAWN_BODY = "• La monnaie que tu dépenses pour améliorer ton équipement rang par rang : 20 crests par rang, et chaque track ne prend que son propre crest. Sans lien avec tes slots raid de la Grande chambre forte.|n• Les artisans les utilisent aussi : les crests fixent le niveau d'objet d'une pièce fabriquée.|n• Les totaux de crests en direct sont sur |cffffffffBasics -> Crests|r (pas dans cette liste).|n• Jusqu'à la semaine du 20 octobre, il y a un plafond. Il compte ce que tu as gagné cette saison, pas ce que tu détiens — dépenser ne libère donc pas de place. Il augmente de 100 chaque semaine. À partir de la semaine du 20 octobre, le plafond disparaît.|n• Pas la même chose que les keys de gouffre — vois ce guide pour les objectifs de dépense.",
	CODEX_TRACKS_TITLE = "Gear upgrade tracks",
	CODEX_TRACKS_BODY = "• L'équipement n'a pas qu'un niveau d'objet — il se trouve sur une |cfffffffftrack|r. Du bas vers le haut : |cffffffffAdventurer|r (vert), |cffffffffVeteran|r, |cffffffffChampion|r, |cffffffffHero|r, |cffffffffMyth|r.|n• Un infobulle indiquant |cffffffffHero 3/6|r signifie : track Hero, rang 3 sur 6. Chaque rang acheté ajoute du niveau d'objet.|n• La track fixe votre plafond — l'infobulle montre la plage de niveau d'objet qu'elle peut atteindre. Pour aller au-delà, il vous faut un butin d'une track supérieure.|n• Chaque track a sa propre couleur de crest. Le contenu plus difficile fait tomber de l'équipement sur une track supérieure — c'est ainsi que vous progressez.|n• Track dépassée ? Échangez les crests inférieurs chez |cffffffffVaskarn|r. Améliorez chez |cffffffffCuzolth|r à Lune-d'Argent — un rang coûte les crests de cette track plus un peu d'or.|n• Chaque track a un haut fait pour l'avoir dépassée, nommé d'après le crest de la saison — en Season 2 la série «…of the Mist». Il divise par deux le coût en crests de cette track pour tes autres personnages et (de Adventurer à Hero) permet à ce personnage d'échanger ce crest vers le haut chez Vaskarn : 30 contre 10 du palier suivant.|n• Comptes en direct et points de passage : |cffffffffBasics -> Crests|r.",

	CODEX_DELVES_INTRO_TITLE = "Gouffres Midnight — aperçu",
	CODEX_DELVES_INTRO_BODY = "• De courtes instances pour 1 à 5 joueurs, avec Valeera comme compagne — à travers Quel'Thalas et l'Île Annelée.|n• |cffffffffTiers 1–11|r. Le Tier 4 et plus demande le niveau 90 et la campagne Midnight terminée une fois sur ton bataillon ; ensuite, finir un Tier ouvre le suivant.|n• L'équipement ne s'améliore plus après le |cffffffffTier 8|r : Bountiful Coffer 295, Grande chambre forte 305 (Héros 1/6). Le Tier 11 rapporte quand même de meilleurs écus.|n• Entrer est gratuit — aucune clé nécessaire. Un gouffre |cffffffffBountiful|r (jusqu'à quatre par jour) se termine par un Bountiful Coffer, et ce coffre demande un |cffffffffRestored Coffer Key|r (voir Currencies).|n• Utilise 'Find Nearest Bountiful Delve' dans l'onglet Delves.",

	CODEX_DELVE_COACH_TITLE = "Delve Coach",
	CODEX_DELVE_COACH_BODY = "• Panneau de conseils flottant : itinéraire, trash et mécaniques de boss par gouffre.|n• S'ouvre tout seul quand tu entres dans un gouffre, ou via |cffffffffDelve Coach (preview tips)|r / |cffffffff/mh coach|r.|n• Les conseils sont dans la langue de ton jeu ; `/mh lang` bascule entre l'anglais et le néerlandais.|n• Pleins feux sur le boss : fais défiler sur le modèle pour zoomer (sauvegardé par boss).|n• Les noms de sorts en bleu renvoient aux vraies infobulles de sorts quand les ID sont connus.",

	CODEX_DELVE_CURIOS_TITLE = "Valeera & curios de gouffre",
	CODEX_DELVE_CURIOS_BODY = "• Valeera a trois emplacements que tu remplis toi-même : un |cffffffffPoison|r, un |cffffffffCombat Curio|r et un |cffffffffUtility Curio|r. Son rôle (Tank, Soigneur ou DPS) est un choix à part.|n• Change-les aux fournitures au début d'un gouffre et à son point de contrôle, où tu peux aussi réparer.|n• La Saison 2 a six poisons : trois dès le début, trois de plus après les quêtes d'intro de Saison 2 de Valeera (Seasonal Refresher: Midnight, puis Slithering Spoils).|n• |cffffffff/mh curios|r montre ce que fait chaque option avec les mots du jeu, avec une étoile sur ce que la plupart des guides choisissent. Un petit panneau avec ces choix s'ouvre à côté de sa fenêtre.|n• Le popup d'objets de gouffre suit RAID-R Mini et Trovehunter's Bounty.",

	CODEX_TORMENTS_TITLE = "Venomfall Deeps (gouffre Némésis)",
	CODEX_TORMENTS_BODY = "• Le gouffre Némésis de la Saison 2, au nord de l'Île Annelée : {WAY:2512:51.23:30.26:Venomfall Deeps}. Le boss est |cffffffffAzta'rec|r, en difficulté |cffffffff?|r ou |cffffffff??|r.|n• Pour le débloquer, termine n'importe quel gouffre de Tier 7 avec au moins une vie restante (pour ?), ou n'importe quel gouffre de Tier 10 avec une vie restante (pour ??).|n• L'entrée conseille un niveau d'objet de 290 pour ? et de 309 pour ??.|n• Uniquement cette saison : le vaincre donne le haut fait My Venomous Nemesis (une transmo de dos) ; en ?? sans autre joueur, Let Me Solo Him: Azta'rec (la monture Apophic Soul Crusher).|n• Torment's Rise et Nullaeus étaient le Némésis de la Saison 1.|n• Delve Coach a le plan du combat.",

	CODEX_DELVE_LOG_TITLE = "Delve Log",
	CODEX_DELVE_LOG_BODY = "• Un registre par personnage de chaque gouffre Midnight et de chaque run de Ritual Site que tu termines : Tier, temps et morts — pour les gouffres, aussi si tu as utilisé une key, et le boss de fin.|n• Ça se remplit tout seul ; l'onglet n'a pas besoin d'être ouvert.|n• Pratique pour voir quel Tier tu as réussi en dernier, et combien de temps ça a pris.|n• Tu cherches une entrée ? |cffffffffFind Nearest Delve|r est dans l'onglet |cffffffffGouffres & Chambre|r.",

	CODEX_MPLUS_TITLE = "Mythic+ & vault des donjons",
	CODEX_MPLUS_BODY = "• Mythic+ remplit la rangée |cffffffffDungeons|r de la Grande chambre forte (séparée des rangées gouffre/monde). Les donjons Héroïque, Mythic 0 et Timewalking y comptent aussi, avec une récompense plus faible.|n• Une key plus haute donne un niveau d'objet plus haut dans la vault. À temps ou non, chaque key terminée compte. Cette saison, ça cesse de monter à +10.|n• Tes trois choix utilisent ta meilleure, ta 4e meilleure et ta 8e meilleure key de la semaine.|n• Vault Advisor n'a des poids de stats M+ séparés que pour les soigneurs ; les tanks et les DPS ont les mêmes poids en raid et en M+.|n• Midnight Helper ne remplace pas un addon d'itinéraire — utilise MDT / des notes pour les semaines d'affixe.",
	CODEX_MPLUS_START_TITLE = "Mythique+, dès ta première clé",
	CODEX_MPLUS_START_BODY = "Le Mythique+, c'est un donjon normal avec une |cffffcc00clé mythique|r : une clé avec un niveau, comme +2 ou +3. Plus la clé est haute, plus c'est dur et meilleur est le butin, et chaque clé terminée compte pour ta |cffffcc00Grande chambre forte|r.|n|n|cffffcc00Ta première clé|r|n• Termine un donjon Mythic 0 : le dernier boss te donne une clé.|n• Ou rejoins la clé de quelqu'un d'autre : à la fin, tu en reçois une aussi.|n• Tu as perdu la tienne, ou tu n'en as jamais eu ? |cffffffffLindormi|r, à Silvermoon City, à côté du portail vers The Timeways, t'en donne une.|n• Tu n'as qu'une clé à la fois, et elle commence à +2.|n|n|cffffcc00Rejoindre un groupe|r|n• Appuie sur |cffffffffI|r, ouvre |cffffffff{UI:GROUP_FINDER}|r, puis |cffffffff{UI:LFGLIST_NAME}|r et |cffffffffDonjons|r. Les donjons mythiques n'ont pas de file d'attente.|n• Choisis une clé basse, de +2 à +4. Les groupes marqués |cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r attendent des nouveaux joueurs.|n• Clique sur |cffffffff{UI:SIGN_UP}|r, coche ton rôle et attends que le chef t'invite.|n|n|cffffcc00Créer ton propre groupe|r|n• Même endroit : clique sur |cffffffff{UI:START_A_GROUP}|r, choisis le donjon de ta clé, un style de jeu (|cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r convient) et clique sur |cffffffff{UI:LIST_GROUP}|r.|n• Mets la difficulté du donjon sur |cffffffffMythique|r avant d'entrer.|n• À l'intérieur, celui qui a la clé clique sur la |cffffffffFont of Power|r près de l'entrée, y place la clé et appuie sur |cffffffff{UI:CHALLENGE_MODE_START_CHALLENGE}|r. Après un compte à rebours de 10 secondes, le chrono démarre.|n|n|cffffcc00Pendant le run|r|n• De +2 à +5, une mort ne coûte pas de temps, et les ennemis marqués t'indiquent un itinéraire. À partir de +6, chaque mort coûte du temps.|n• À partir de +5, une règle de la semaine s'ajoute. L'onglet |cffffffff{UI:CHALLENGES}|r de la recherche de groupe montre laquelle.|n• Dans les temps : ta clé monte de 1 à 3 niveaux. Trop tard : tu as quand même du butin, mais la clé baisse d'1 niveau. Dans les deux cas, elle passe à un autre donjon.|n• Besoin d'arrêter ? Tape |cffffffff/abandon|r pour lancer un vote. Partir comme ça peut te marquer comme Keystone Deserter.|n• À la fin, chacun ouvre le coffre pour son propre butin.|n|n|cffffcc00Aide|r|n• Dis-le au groupe : « first time in this dungeon » (première fois dans ce donjon). Sur les clés basses, la plupart des joueurs expliquent volontiers.|n• Demande à ta guilde, ou regarde dans |cffffffff{UI:COMMUNITIES_GUILD_FINDER}|r et |cffffffffFind a Community|r dans la fenêtre Guilde et communautés (J).|n• Ton |cffffffff{UI:DUNGEON_SCORE}|r est dans l'onglet {UI:CHALLENGES}. Beaucoup de chefs regardent aussi le score Raider.IO.|n|nMidnight Helper t'aide à l'intérieur : les conseils de boss s'ouvrent dès que tu entres, et |cffffffff/mh mplus|r montre ton meilleur run par donjon et où une clé rapporte le plus.",
	CODEX_AGGRO_TITLE = "Aggro : qui l'ennemi frappe-t-il ?",
	CODEX_AGGRO_BODY = "L'aggro, c'est quand un ennemi t'attaque. Le tank la veut ; un DPS ou un healer qui la prend meurt souvent. Le jeu peut déjà te prévenir, mais chez beaucoup de joueurs ces alertes sont désactivées. Midnight Helper n'en modifie aucune pour toi : tape |cffffffff/mh aggro|r pour voir comment elles sont réglées chez toi.|n|n• |cffffffff{UI:NAMEPLATE_OPTIONS_LABEL} > {UI:UNIT_NAMEPLATES_THREAT_DISPLAY}|r : coche |cffffffff{UI:UNIT_NAMEPLATES_THREAT_DISPLAY_FLASH}|r. La barre d'info d'un ennemi clignote quand le tank le perd ou quand un DPS ou un healer le prend.|n• |cffffffff{UI:COMPACT_UNIT_FRAME_PROFILE_DISPLAYAGGROHIGHLIGHT}|r (fenêtres de raid) : un contour rouge autour de celui qui a l'aggro. Pratique pour les healers.|n• |cffffffff{UI:ACCESSIBILITY_AUDIO_LABEL} > {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} > {UI:CAA_SAY_IF_TARGETED_LABEL}|r : une voix te prévient quand un ennemi te prend pour cible. Active d'abord {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} ; ce réglage est enregistré par spécialisation.|n|nTu utilises un addon de barres d'info comme Plater ? Alors le clignotement sur les barres d'info vient de cet addon, pas du jeu : regarde dans ses propres réglages.",

	CODEX_RAID_VAULT_TITLE = "Raid — Grande chambre forte",
	CODEX_RAID_VAULT_BODY = "• Les boss de raid remplissent la rangée Raid de la vault : 2, 4 et 6 boss ouvrent un, deux et trois choix. Toutes les difficultés comptent, la Recherche de raid aussi, et le boss du Lair aussi.|n• En Saison 2, chaque choix vient d'une difficulté au-dessus de celle où tu as tué les boss : la Recherche de raid donne Champion, le Normal donne Hero, l'Héroïque donne Myth, le Mythique donne Myth à un niveau plus haut.|n• Difficultés mélangées : chaque choix utilise la difficulté la plus haute sur laquelle tu as atteint ce nombre de boss. L'UI de vault montre ce que tu as cette semaine.|n• Les crests sont ce que tu dépenses ensuite pour améliorer l'équipement de raid.",

	CODEX_VAULT_ADVISOR_TITLE = "Conseiller de Grande chambre forte",
	CODEX_VAULT_ADVISOR_BODY = "• Panneau latéral à côté de la fenêtre de Grande chambre forte de Blizzard quand tu choisis ta récompense à la Grande chambre forte de Lune-d'argent — pas dans les onglets de Midnight Helper. SHIFT-J ne montre qu'un résumé, donc le panneau n'y apparaît pas.|n• Classe les pièces de vault par rapport à l'équipement porté selon les priorités de stats du guide (et Pawn en option).|n• Activable dans les réglages rapides de minimap / Échap -> AddOns -> Midnight Helper.|n• Profil Auto vs Raid vs M+ pour les poids de stats.",

	CODEX_WORLD_HUB_TITLE = "Void & Rituals — un seul système",
	CODEX_WORLD_HUB_BODY = "• Depuis le patch 12.0.5, les |cffffffffRitual Sites|r et les |cffffffffVoid Assaults|r fonctionnent comme un seul système. Les deux alternent chaque semaine entre Eversong Woods et Zul'Aman, et ils partagent une même monnaie et un même renom.|n• Mêmes |cffffffffField Accolades|r et hub du Bazaar — ne les farme pas comme des activités séparées.|n• La Saison 2 a abaissé l'équipement que tu achètes avec les Field Accolades à aventurier et vétéran : pratique pour un nouveau personnage, pas pour l'équipement de pointe.|n• Ouvre l'onglet combiné pour le site et la zone actifs de la semaine, tes Field Accolades et ton renom, et les boutons d'itinéraire.",

	CODEX_RITUAL_TITLE = "Ritual Sites",
	CODEX_RITUAL_BODY = "• Un rituel instancié pour 1 à 5 joueurs. Chaque semaine, il se trouve à l'un de deux endroits : Daggerspine Point à Eversong Woods ou le Broken Throne à Zul'Aman. Choisis un Tier et termine-le pour des accolades, du renom et du butin.|n• Un seul site est actif à la fois ; l'addon met en évidence lequel.|n• Le pin Ritual Site du SMC City Guide pose un itinéraire vers le site actif de la semaine. Si l'addon ne le connaît pas encore, le pin ouvre l'onglet Void & Rituals.",

	CODEX_VOID_TITLE = "Void Assaults",
	CODEX_VOID_BODY = "• Le Vide attaque Eversong Woods ou Zul'Aman — l'une des deux chaque semaine. Fais les Void Strikes ; assez d'entre elles lancent une Void Incursion plus grande. Les deux rapportent des Field Accolades.|n• Partage les Field Accolades et le renom des Ritual Sites avec les Ritual Sites — tu fais progresser les deux à la fois.|n• L'onglet Void & Rituals montre la zone de cette semaine, celle de la semaine prochaine et ta quête hebdomadaire.",

	CODEX_RARES_TITLE = "Rares Midnight",
	CODEX_RARES_BODY = "• Mobs rares hebdomadaires avec butin compte/personnage (vérifie les règles de chaque rare en jeu).|n• Onglet |cffffffffRares|r : suis les kills et construis un itinéraire, le rare le plus proche en premier. La flèche d'itinéraire (celle de Midnight Helper, ou celle de TomTom si tu l'utilises) passe ensuite au plus proche suivant.|n• Alerte en direct quand un rare suivi est à proximité (~500 yd) — activable dans les réglages.",

	CODEX_PROF_TITLE = "Métiers — boucle hebdomadaire",
	CODEX_PROF_BODY = "• Chaque métier a ses propres |cffffffffpoints de connaissance (KP)|r et son propre |cffffffffAplomb artisanal|r : l'Aplomb d'Alchimie n'achète que des choses d'Alchimie.|n• |cffffffffChaque semaine, par métier :|r la quête hebdomadaire de ton maître à Lune-d'argent (dès la compétence 25), les |cffffffffPatron orders|r à la table des commandes d'artisanat qui rapportent des connaissances (la plus grosse source hebdomadaire), jusqu'à deux objets de connaissance dans des trésors ordinaires des zones Midnight, et un Thalassian Treatise (fabriqué par la Calligraphie).|n• Les récolteurs et les enchanteurs obtiennent aussi des objets de connaissance en récoltant ou en désenchantant. Ceux-là permettent de rattraper une semaine manquée ; la plupart des autres sources hebdomadaires, non.|n• |cffffffffAbundance|r est une piste à part : un Shard of Dundun (8 par semaine au maximum) lance une Abundant Harvest, qui rapporte de l'Unalloyed Abundance.|n• Onglet |cffffffffMétiers|r : KP non dépensés, tes Shards of Dundun, et des pins de carte pour les trésors et les livres. Où dépenser les KP : le guide Basics.",

	CODEX_PROF_GUIDE_TITLE = "Métiers — guide débutant",
	CODEX_PROF_GUIDE_BODY = "• Sous-onglet |cffffffffBasics -> Métiers|r : plan de KP pas à pas et suggestions de combos.|n• Le sous-onglet |cffffffffCrests|r parle des crests : la monnaie qui sert à améliorer l'équipement, gagnée dans de nombreuses activités — pas seulement en raid.|n• Relis après les patchs — les chiffres et les plafonds peuvent changer.",
	CODEX_PROFRESET_TITLE = "Réinitialiser les spécialisations d’un métier (12.1)",
	CODEX_PROFRESET_BODY = "• Le patch 12.1 permet d’annuler tes choix de spécialisation Midnight — une fois par métier.|n• |cffffffffChez qui :|r Theremis, au Bazar de Lune-d’argent, à côté des commandes d’artisanat. Il propose une ligne par métier : tu peux réinitialiser le Forgeage et laisser l’Enchantement intact.|n• |cffffffffCe que tu récupères :|r chaque point de Connaissance dépensé dans les arbres Midnight de ce métier, libre de le replacer.|n• |cffffffffCe que ça coûte :|r l’avertissement du jeu dit « You will lose all associated recipes ».|n• |cffffffffAssociées, pas toutes.|r Ce qui part, c’est ce que ces spécialisations avaient débloqué. Les recettes apprises d’un maître, d’un butin ou d’une quête sont hors des arbres et restent. Observé sur un Enchantement réinitialisé : la liste de recettes était intacte et la Connaissance dépensée était revenue au compteur.|n• |cffffffffC’est une seule fois.|r La confirmation écrit ONCE en majuscules, et c’est par métier — pas de deuxième essai si la nouvelle voie te déçoit.|n• Décide donc |cffffffffavant|r de confirmer. La page Métiers indique l’arbre à remplir et le nœud exact.|n• Les recettes reprises reviennent-elles si tu redépenses à l’identique ? Le jeu ne le dit nulle part. Prévois que non.",
	CODEX_CORRPOWER_TITLE = "Corrosive Codex — quel gift prendre en premier ?",
	CODEX_CORRPOWER_BODY = "|cffffcc00Douze gifts, et tu peux en utiliser un.|r Chacun coûte |cffffffff8 Corrosive Souls|r, donc les douze ensemble en coûtent 96. Comme le prix est le même pour tous, ton premier choix porte sur |cffffffffce dont tu as besoin|r — jamais sur ce que tu peux te payer.|n|n|cffffff78Une seule chose explique tout le système|r|n• C'est une |cffffffffboucle de poison|r. La moitié des gifts devient plus forte contre un ennemi Poisoned, ou pendant que |cfffffffftoi-même|r es empoisonné.|n• C'est pourquoi chaque bonne paire est |cffffffffun gift qui empoisonne + un gift qui en profite|r. Une fois que tu vois ça, les combinaisons n'ont plus rien d'aléatoire.|n|n|cffffff78Lequel en premier ? Choisis selon ton problème, pas selon un classement|r|n• |cffffffffJe veux juste taper plus fort|r → |cffffffffUla'tek's Gift|r. Il fonctionne seul, sans deuxième gift et sans préparation. Tous les guides que nous avons lus le citent en premier.|n• |cffffffffLes groupes d'ennemis prennent trop de temps|r → |cffffffffPlague of Corrosion|r ou |cffffffffOphidian Maw|r.|n• |cffffffffJe meurs sans arrêt dans les gouffres|r → |cffffffffVirulent Mucus|r encaisse les gros coups, |cffffffffGorgoneion Gaze|r pétrifie tout autour de toi dès que tu passes sous la moitié de ta vie.|n• |cffffffffLes lanceurs de sorts finissent toujours leur incantation|r → |cffffffffAccursed Poison|r. Il en interrompt une pour toi.|n|n|cffffcc00Attention à Mephitic Cloud.|r Il permet aux |cffffffffennemis|r touchés de soigner ce qu'ils attaquent. En groupe, ça joue contre toi.|n|n|cffffff78Ce que nous avons mesuré nous-mêmes, et ce que non|r|n• |cffffffffDu jeu :|r le prix de 8 et le texte complet d'Ula'tek's Gift. Ceux-là sont à nous.|n• |cffffffffDes guides :|r l'ordre ci-dessus, et combien de gifts ouvrent le deuxième emplacement. Le jeu dit seulement \"until your offerings are sufficient\" et ne donne aucun chiffre. |cffffffffSix sources disent 8|r — dont la page de sort de Wowhead, qui le met dans un tableau — et un blog dit 6. Donc 8 est très probablement juste ; nous ne l'avons simplement pas encore vu nous-mêmes. Tu le sauras au moment où ton deuxième emplacement apparaîtra.|n• Ula'tek's Gift a |cffffffffdéjà été affaibli une fois|r. Un classement d'août n'est donc pas automatiquement vrai aujourd'hui — c'est précisément pour ça que la boucle de poison ci-dessus est la partie à retenir.",
	CODEX_ATALUTEK_TITLE = "Les Vaults of Atal'Utek — ce qu'on y trouve, et où",
	CODEX_ATALUTEK_BODY = "|cff8fd3ffPour commencer|r|n|n• |cffffffffCe que c'est :|r une zone de la 12.1 sur la Coiled Isle avec sa propre carte, et en dessous une seconde carte, l'Underbelly. C'est déjà ouvert — aucune barrière de saison.|n|n• |cffffffffComment y entrer :|r une chaîne de quatre quêtes — |cffffffffInto the Vaults of Atal'Utek|r, puis |cffffffffVaults of Atal'Utek: One Coin Too Many|r et |cffffffffVaults of Atal'Utek: A Toxic Tour|r, que l'on te donne ensemble, puis |cffffffffVaults of Atal'Utek: The Altar of Corrosion|r. Tout le reste se trouve derrière, alors fais-les d'abord. |cffffffffA Toxic Tour est une quête d'histoire unique, pas une quotidienne|r — elle demande une Patrol, un Strike, une Incursion et un Ancient Foe, donc elle se termine d'elle-même pendant la boucle décrite ci-dessous.|n|n|cff8fd3ffCe que tu fais ici|r|n|n• |cffffffffCe que tu fais vraiment ici — quatre choses, et elles s’alimentent.|r Les |cffffffffTemple Patrols|r parcourent la carte et tournent environ toutes les dix minutes ; c’est le plus simple à rejoindre et il y en a presque toujours une. Les |cffffffffTemple Strikes|r sont plus grosses et préparent une incursion. Quand assez de Strikes sont faites, une |cffffffffTemple Incursion|r commence, et chaque Incursion se termine en réveillant un |cffffffffAncient Foe|r — d’où viennent les trois élites rares : un seul d’entre eux par semaine, avec dix minutes au compteur. Pièces, clés, équipement et réputation sortent tous de cette boucle. Si tu te demandes quoi faire : rejoins ce qui tourne.|n|n• |cffffffffComment trouver un Temple Strike, concrètement ?|r Ouvre ta carte dans les Vaults et cherche les icônes d’événement — un Strike y est marqué comme n’importe quel événement de zone, et |cffffffffil n’a pas de minuteur|r : il reste là jusqu’à ce qu’un groupe le termine, tu peux donc y aller tranquillement. |cffffffffQuelques joueurs suffisent|r ; pas besoin de groupe monté, et il y a généralement déjà du monde dessus. Il y en a six, chacun avec un point de départ fixe — clique pour poser un repère : {WAY:2509:50.55:15.70:Cursed Depths} · {WAY:2509:47.36:46.17:Overflowing Venom} · {WAY:2509:47.67:46.34:Profane Pyres} · {WAY:2509:47.26:26.69:Purifying Earth and Sky} · {WAY:2509:39.32:39.92:Ruuk’Jar’s Clutch} · {WAY:2613:52.25:36.27:The Underbelly}.|nSi la carte n’affiche aucun Strike, une Incursion ou son Ancient Foe est probablement en cours en ce moment — rejoins-la plutôt. Un nouveau Strike apparaît une fois qu’elle est terminée.|n|n• |cffffffffSe déplacer à l’intérieur.|r Les |cffffffffAmani Windcallers|r te transportent entre trois points des Vaults — le hub |cffffffffAmani Foothold|r, l’Eastern Amani Outpost et le Northern Amani Bulwark. Le maître de vol |cffffffffEagletender Mal’Tiki|r se tient à {WAY:2509:44.42:62.21:Amani Foothold}. On ne peut pas voler dans les Vaults, et c’est précisément pour ça qu’ils existent — c’est plus grand que ça n’en a l’air, et marcher est la manière lente.|n|n• |cffffffffLes quêtes répétables — une hebdomadaire et huit quotidiennes.|r |cffffffffPurging the Vaults|r chez |cffffffffWarleader Abdumati|r à l'Amani Foothold est l'hebdomadaire à ne pas manquer. Les huit quotidiennes sont |cffffffffPatrolling the Temple|r, |cffffffffBounty of the Cursed|r, |cffffffffRelentless Strikes|r, |cffffffffDecisive Incursions|r, |cffffffffFrom Whence it Came|r, |cffffffffEssence of Malice|r, |cffffffffWhat's Out There?|r et |cffffffffShoulder to Shoulder|r — prends celles que ta carte propose aujourd'hui. La plupart demandent les activités ci-dessus, elles se cochent donc toutes seules pendant que tu joues. Deux veulent que tu sois en groupe (What's Out There? et Shoulder to Shoulder) : les gens déjà à côté de toi suffisent, pas besoin d'un groupe monté. Et une que tu ne trouveras jamais en restant ici : |cffffffffMidnight: Vaults of Atal'Utek|r est une méta hebdomadaire pour cet endroit, à récupérer à |cffffffffSilvermoon|r.|n|n|cff8fd3ffCoin and Soul|r|n|n• |cffffffffCorrosive Coin|r est la monnaie de la zone. Selon les mots du jeu : « Spirits of the Amani within the Vaults of Atal'Utek deal exclusively in this phantasmal token. » Ton solde est le nombre affiché au-dessus de cet article.|n|n• |cffffffffCorrosive Soul, ce n'est pas ça.|r Ce n'est pas du tout une monnaie mais un |cffffffffobjet|r dans tes sacs, et c'est ce que le Corrosive Codex te demande d'offrir. Les guides intervertissent sans cesse les deux noms ; le jeu jamais. Si quelque chose te dit de dépenser des Corrosive Coins au Codex, c'est cette confusion-là.|n|n• |cffffffffOù vont les pièces — deux endroits, tous deux chez Er’inye|r en {WAY:2509:51.10:62.76:Er'inye}. Lui parler achète |cffffffffCorrode Spirit|r, qui alimente l’arbre de l’autel ; à côté d’elle, le |cffffffffSkull of Er’inye|r est un marchand avec trois pages de montures, mascottes, ensembles et recettes, de 500 à 25 000 pièces. |cffffffffLe prix du corrode monte à chaque achat|r — vu à 1 500 puis 2 000 en une visite — lis donc la fenêtre au lieu d’économiser pour un montant.",
	CODEX_ATALUTEK_DISC_TITLE = "Altar of Corrosion : les quatre clés",
	CODEX_ATALUTEK_DISC_BODY = "• |cffffffffL'Altar of Corrosion|r est l'arbre de nœuds qu'ouvre la dernière quête de la chaîne. L'essentiel s'ouvre en dépensant, mais |cffffffffquatre nœuds sont derrière une clé que tu dois aller chercher|r — et les quatre fonctionnent pareil : un objet tombe, tu l'utilises sur un objet fixe quelque part dans les Vaults, ça donne un objet de quête, et Er’inye fait le reste.|n|cffffffffCorroded Key|r → le Venom-Worn Coffer → |cffffffffRun of the Vaults|r (Glideways, ou Swift Steps) · |cffffffffSpirit Loupe|r → la Feather of Tok’jara en {WAY:2509:48.46:25.80:Feather of Tok'jara} → |cffffffffSpectral Winds|r (Spirit Walk, ou Spectral Shipping) · |cffffffffExcising Knife|r → l'Eye of Szarith, dans une mare de venin de l'Underbelly → |cffffffffBroodmaster|r (+100% de dégâts aux œufs, ou −75% de dégâts des explosions d'œufs) · |cffffffffDispelling Charm|r → Jin’tal’s Reliquary dans le Profaned Mausoleum → |cffffffffSpiritual Protection|r (alliés spectraux aux Curse Surges, ou te relever aussitôt si tu meurs hors des Vaults).|n|cffffffffMontrer une clé à Er’inye ne débloque rien.|r Elle est aveugle et te dit ce qu'elle ressent — c'est un indice sur l'endroit où va l'objet. |cffffffffD'où viennent les clés|r — les guides sont désormais d'accord : la Corroded Key vient des Temple Strikes, l'Excising Knife d'une Temple Incursion, la Spirit Loupe d'un Ancient Foe. Le |cffffffffDispelling Charm|r fait exception : il ne vient pas des événements, mais de Jin’tal dans le Vault of Restless Bones, pendant une suite de quêtes secondaires sur les Med’jai.|n|n• |cffffffffDépense tes premières pièces dans l’arbre tout de suite.|r Ses quatre premiers nœuds ne coûtent rien et s’ouvrent à mesure que tu dépenses ailleurs, et ils augmentent la Corrosive Coin que tu gagnes de |cffffffff25, 50, 75 puis 100 pour cent|r. L’arbre se rembourse tout seul : chaque tour après le premier rapporte plus — économiser est le choix coûteux. Note aussi l’asymétrie qui donne son rythme à la zone : |cffffffffles pièces n’ont pas de plafond|r, les Corrosive Souls si. Farme les pièces librement ; ne planifie pas une soirée autour des souls.",
	CODEX_ATALUTEK_DEAD_TITLE = "The Honored Dead & les rares",
	CODEX_ATALUTEK_DEAD_BODY = "• |cffffffff« The Honored Dead » — douze mémoriaux|r sur la carte des Vaults, un haut fait, et la chose la plus claire à aller faire ici. Dans un seul ordre de marche, du haut de la carte vers le bas :|n{WAY:2509:46.79:7.51:To a sister 46.79, 7.51} · {WAY:2509:56.49:22.88:To a shield-bearer 56.49, 22.88} · {WAY:2509:47.22:28.77:To a father 47.22, 28.77} · {WAY:2509:42.57:33.18:To a stranger 42.57, 33.18} (sous le pont) · {WAY:2509:52.91:33.90:To a captain 52.91, 33.90} · {WAY:2509:55.62:40.60:To a dream 55.62, 40.60} · {WAY:2509:42.84:39.93:To sons 42.84, 39.93} · {WAY:2509:52.21:45.12:To a lover 52.21, 45.12} · {WAY:2509:38.50:47.66:To Comrades 38.50, 47.66} · {WAY:2509:55.31:48.45:To parents 55.31, 48.45} · {WAY:2509:49.50:56.59:To a daughter 49.50, 56.59} · {WAY:2509:45.81:61.79:To Failure 45.81, 61.79}|n|n• |cffffffffL'Underbelly|r est la carte du dessous, entrée à {WAY:2509:47.30:11.20:The Underbelly} sur la carte des Vaults. Un rare y vit, |cffffffffSzarith the Fanged|r à {WAY:2613:38.40:17.69:Szarith the Fanged}, et l'Underbelly a son propre haut fait, |cffffffffSoft Underbelly|r. |cffffffffSzarith seul ne suffit pas :|r selon les guides, il faut aussi plusieurs élites nommés qui n'apparaissent que pendant le Temple Strike |cffffffffThe Underbelly|r.|n|n• |cffffffffTrois élites rares sur la carte principale|r — Congealed Malice, Khu'tulak et Susarikk — forment un troisième : |cffffffffOppose the Foes|r. |cffffffffIls n'ont pas de position fixe, et c'est la réponse, pas un manque|r : l'un des trois se réveille dès qu'une |cffffffffTemple Incursion|r est terminée, et tu as environ dix minutes pour le tuer. |cffffffffUn seul des trois est dans la rotation chaque semaine|r, donc ce haut fait prend au moins trois semaines. Tu ne pars donc pas les chasser — tu finis des Incursions, et celui de la semaine vient à toi.",
})

merge(ns._mhLocales and ns._mhLocales.esES, {
	TAB_CODEX = "Midnight Codex",
	CODEX_PANEL_TITLE = "Midnight Codex",
	CODEX_PANEL_INTRO = "Tu manual para Midnight: qué es cada sistema, para qué sirve cada moneda y dónde hacer clic en este addon. Pasa el cursor sobre los iconos de moneda para ver las descripciones de Blizzard.",
	CODEX_OPEN_TAB_FMT = "Abrir: %s",
	CODEX_NAV_DELVES_VAULT = "Pestaña Delves & Vault (bloque de Gran cámara)",
	CODEX_NAV_DELVES_MIDNIGHT = "Pestaña Delves & Vault (lista de profundidades)",
	CODEX_NAV_BASICS_DAWN = "Categoría Basics (Crests)",
	CODEX_NAV_BASICS_PROF = "Pestaña Basics (guía de Profesiones)",
	CODEX_BALANCE_FMT = "Tienes: |cffffffff%d|r",
	CODEX_BALANCE_UNKNOWN = "El saldo se actualiza cuando inicias sesión con este personaje.",
	CODEX_SEARCH_OPENED = "Midnight Codex abierto.",
	CODEX_BETA_DISABLED = "Midnight Codex está desactivado en los Ajustes (pestañas beta).",

	CODEX_CAT_START = "Para empezar",
	CODEX_CAT_WEEKLY = "Ciclo semanal",
	CODEX_CAT_CURRENCIES = "Currencies",
	CODEX_CAT_DELVES = "Delves",
	CODEX_CAT_DUNGEONS = "Dungeons & M+",
	CODEX_CAT_RAID = "Banda & Crests",
	-- ⚠️ Was "Void & Rituals" until 19 aug, and half of what sits under it is neither.
	-- The category holds Prey hunts, rares, Turbulent Timeways and Showdowns alongside
	-- the void and ritual articles. Rob went looking for Prey, read that button, and
	-- walked straight past it — the same class of fault as the twelve type-only commands
	-- on 18 aug: the feature was there, under a name nobody would guess.
	CODEX_CAT_WORLD = "World content",
	CODEX_CAT_COILEDISLE = "Coiled Isle",
	CODEX_ROUTE_BTN = "Seguir la ruta",
	CODEX_CAT_PROFESSIONS = "Professions",

	CODEX_START_TITLE = "Para empezar — tu semana Midnight",
	CODEX_START_BODY = "|cffffcc00Piensa por capas:|r un reset semanal, varias vías de recompensa. No necesitas cada sistema cada día: elige un objetivo.|n|n|cffffff781) Cuenta y reset|r|n• Revisa la pestaña |cffffffffThis Week|r para la cámara, el jefe de mundo, las keys y las tareas.|n• |cffffffffAccount snapshot|r muestra todos tus alts (cámara, Delver's Call, semanales de profesión).|n|n|cffffff782) Contenido de combate|r|n• |cffffffffDelves|r — vía principal de equipo (keys, niveles, ranuras de Gran cámara). Usa |cffffffffDelve Coach|r para consejos por profundidad.|n• |cffffffffMythic+|r y |cffffffffBandas|r llenan otras ranuras de la Gran cámara (ver categorías Dungeons & Banda).|n|n|cffffff783) Mundo abierto|r|n• |cffffffffIsla Serpenteante|r — la zona de la Temporada 2, del parche 12.1, con su propia categoría aquí.|n• Las cacerías de |cffffffffPrey|r cuentan para la misma fila de la Gran cámara que las profundidades.|n• Pestaña |cffffffffVoid & Rituals|r — Field Accolades, Ritual Sites, Void Assaults (misma vía de renombre).|n• Pestaña |cffffffffRares|r — botín raro semanal y rutas.|n|n|cffffff784) Artesanía|r|n• Pestaña |cffffffffProfesiones|r para KP / mats semanales; |cffffffffBasics|r para Crests.|n|n|cffffcc00Consejo:|r abre aquí la categoría |cffffffffCurrencies|r cuando olvides para qué sirve un vale. Desplázate por la vista previa del jefe en Delve Coach para hacer zoom.",
	CODEX_MIDSTART_TITLE = "Empezar la campaña Midnight",
	CODEX_MIDSTART_BODY = "|cffffcc00Al nivel 80 la misión |r|cffffffffMidnight|r|cffffcc00 llega sola.|r No hay que buscar nada: aparece en tu registro en cuanto subes a 80. Por debajo de 80 ya puedes viajar a Lunargenta, pero allí todavía no hay nada que aceptar.|n|n|cffffff78Dónde empieza|r|n• Habla con la |cffffffffImage of Lady Liadrin|r. Está en varias capitales, así que también en la tuya.|n• Ofrece dos cosas: ver la introducción, o |cffffffffI have heard this tale before|r para saltártela.|n|n|cffffff78Saltártela no te cuesta nada|r|n• Sales en |cffffffffLunargenta|r y la siguiente misión te la dan al momento.|n• No hay nada bloqueado detrás de la introducción: rutas, puntos de la ciudad y la rutina semanal funcionan igual.|n|n|cffffff78Elegir por dónde empezar|r|n• Esa siguiente misión, |cffffffffAdventuring in Midnight|r, te manda a la |cffffffffScouting Map|r del Sanctum of Light.|n• Cinco puntos de partida: |cffffffffArator's Journey|r, |cffffffffEversong|r, |cffffffffZul'Aman|r, |cffffffffVoidstorm|r y |cffffffffHarandar|r.|n• Pasa el ratón por uno para ver qué hay allí; al hacer clic solo se abre su scouting report. |cffffffffMirar no cuesta nada.|r|n|n|cffffcc00¿Elegiste y te arrepientes?|r Elegir oculta los otros cuatro mientras esa misión esté en tu registro, pero |cffffffffabandona la misión|r y vuelven los cinco. Decide tu orden, no tu camino.",
	CODEX_WARBAND_TITLE = "Banda de guerra y su banco",
	CODEX_WARBAND_BODY = "|cffffcc00Tu banda de guerra|r son todos los personajes de tu cuenta, tratados como un equipo. Muchas cosas ahora están |cffffffffvinculadas a la banda de guerra|r — compartidas en toda la cuenta — así que envías mucho menos correo entre alts.|n|n|cffffff78Objetos y monedas vinculados a la banda de guerra|r|n• Algunas monedas son de toda la cuenta o se pueden mover entre personajes: tu ventana de monedas muestra cuáles. Los crests de mejora cuentan por personaje.|n• El equipo suele estar |cffffffffvinculado a la banda de guerra hasta equipar|r — envíalo a un alt, pero una vez equipado queda con ese personaje.|n|n|cffffff78El banco de banda de guerra|r — un banco compartido que usan todos tus personajes.|n• Ábrelo con |cffffffffcualquier banquero|r (o Jeeves) — es una pestaña de tu banco normal, junto a tu banco de personaje.|n• Guarda cualquier objeto |cffffffffno ligado al alma|r, y deposita o retira |cfffffffforo|r entre personajes (incluso entre facciones).|n• Fabrica directamente desde él — cuenta como fuente de componentes.|n|n|cffffff78Pestañas y coste|r — 5 pestañas, 98 espacios cada una (490 en total). Empiezas sin ninguna; cómpralas con oro:|n• Pestaña 1: |cffffffff1.000o|r|n• Pestaña 2: |cffffffff25.000o|r|n• Pestaña 3: |cffffffff100.000o|r|n• Pestaña 4: |cffffffff500.000o|r|n• Pestaña 5: |cffffffff2.500.000o|r  (las cinco = 3.126.000o)|n|n|cffffcc00Consejo:|r 2-3 pestañas bastan para la mayoría. No lo confundas con tu |cffffffffbanco de personaje|r (también con pestañas desde el parche 11.2, mucho más barato) — ese es por personaje; el banco de banda de guerra es compartido.",

	CODEX_WEEKLY_RESET_TITLE = "Reset semanal",
	CODEX_WEEKLY_RESET_BODY = "• La mayoría del progreso semanal se reinicia el día de mantenimiento de tu región (EU miércoles por la mañana, US martes por la mañana).|n• Se reinician las elecciones de Gran cámara, el botín del jefe de mundo y muchos límites semanales.|n• La pestaña |cffffffffThis Week|r muestra el tiempo hasta el reset cuando la API lo da.|n• Planifica los alts: la |cffffffffAccount snapshot|r compara quién tiene aún pendiente una recompensa de cámara, keys o Delver's Calls.",

	CODEX_VAULT_TITLE = "Gran cámara",
	CODEX_VAULT_BODY = "• Tres filas: |cffffffffWorld|r (profundidades, Prey y otras actividades de mundo), |cffffffffDungeons|r (Heroico, Mítico, Mythic+ y Timewalking), |cffffffffBandas|r (jefes de banda en cualquier dificultad, y el jefe de la Lair).|n• Cada fila abre hasta tres opciones: World con 2/4/8 actividades, Dungeons con 1/4/8, Bandas con 2/4/6 jefes.|n• Cada opción vale lo que la carrera más floja que necesitó: la opción de 4 carreras usa tu 4.ª mejor carrera de la semana, la de 8 carreras tu 8.ª mejor. Una sola key difícil solo sube tu primera opción de Dungeons.|n• Temporada 2: una opción de banda llega un paso por encima de lo que mataste — los jefes muertos en Normal dan un objeto de track héroe, los de Heroico uno de track mito.|n• Tras el reset eliges |cffffffffuna|r recompensa en total entre todas tus opciones desbloqueadas, en la Gran cámara de Lunargenta. SHIFT-J solo muestra un resumen.|n• Con 3 o más opciones desbloqueadas, de cualquier fila, puedes llevarte un |cffffffffNebulous Voidcore|r (una tirada extra) en lugar de un objeto.|n• |cffffffffVault Advisor|r (en la UI de cámara de Blizzard) clasifica las opciones frente a tu equipo.|n• En este addon la fila World está en la pestaña |cffffffffProfundidades & Cámara|r — despliega |cffffffffGran cámara (mundo)|r. Pasa el cursor sobre un personaje en la |cffffffffAccount snapshot|r para ver las tres filas.|n• Resumen también en la pestaña |cffffffffThis Week|r.",

	CODEX_WORLDBOSS_TITLE = "Jefe de mundo (Midnight)",
	CODEX_WORLDBOSS_BODY = "• Un jefe de mundo rotatorio por semana (Lu'ashal, Cragpine, Thorm'belan, Predaxas), como misión de mundo con una calavera en el mapa. No tienes que recoger nada.|n• Lady Liadrin en Lunargenta a veces ofrece |cffffffffMidnight: World Boss|r como una de sus cuatro opciones semanales; matar al jefe de esta semana la completa.|n• Botín de banda de guerra: en cuanto un personaje lo mata, los alts aparecen como completados.|n• Seguido arriba en |cffffffffProfundidades & Cámara|r con ruta TomTom.|n• También enlazado desde el SMC City Guide cuando estás en Lunargenta.",
	CODEX_FOLIO_TITLE = "Omnium Folio (12.0.7)",
	CODEX_FOLIO_BODY = "• Sistema de poder del parche 12.0.7, aún activo en 12.1 — un libro de minimapa de |cffffffffrunas|r que cambias libremente fuera de combate (sin coste de ranura).|n• El poder viene de la cadena |cffffffff'Seeking Knowledge'|r (5 pasos): The Omnium Folio, Ritualized Arcana, Ley Line Assaults, Magical Primessence, Off-World Magic.|n• Cada paso recompensa un |cffffffffMote of Omnial Inquiry|r que abre la siguiente fila de runas.|n• Termina los 5 para el logro meta y la decoración Sunstrider Omnium Simulacrum.|n• ¿Te saltaste semanas? Haz las misiones perdidas seguidas para ponerte al día — sin esperar resets.|n• Alts: en cuanto un personaje ha hecho la introducción, los demás pueden saltársela (12.1). Tus elecciones de runas siguen siendo por personaje.",
	CODEX_TT_TITLE = "Turbulent Timeways (12.0.7)",
	CODEX_TT_BODY = "• Evento Paseo en el tiempo de vuelta — esta vez un grupo de mazmorras de |cffffffffDragonflight|r: Algeth'ar Academy, Halls of Infusion, Neltharus, Ruby Life Pools, The Azure Vault, Brackenhide Hollow.|n• Semanal: haz |cffffffff5 mazmorras de Paseo en el tiempo|r para un alijo de equipo; cada run acumula |cffffffffKnowledge of Timeways|r (buff de XP).|n• Gana |cffffffffMastery of Timeways|r en 4 de 6 semanas para 'Master of the Turbulent Timeways' y la montura |cffffffffSpawn of Vyranoth|r.|n• Gasta las Insignias temporales en el vendedor del evento.|n• Dura ~30 jun – 11 ago. (Datamined — confirmar en el lanzamiento.)",

	CODEX_DELVER_CALL_TITLE = "Delver's Call",
	CODEX_DELVER_CALL_BODY = "• Una misión por cada profundidad de Midnight: completa esa profundidad una vez, en cualquier tier. Cada personaje puede hacer cada una una sola vez — no vuelven cada semana.|n• Dan mucha XP, y la recompensa crece con tu nivel. Mientras subes de nivel: completa las profundidades pronto y entrega las misiones tarde (hacia el nivel 87-88).|n• |cffffffffAccount snapshot|r muestra qué personajes tienen aún calls completadas (guardadas).|n• Pasa el cursor por la línea Delver's Call en el snapshot para el detalle por personaje.",

	CODEX_ACCOUNT_TITLE = "Account snapshot",
	CODEX_ACCOUNT_BODY = "• Vista de solo lectura de los personajes con los que has iniciado sesión con Midnight Helper.|n• Ordena/filtra por cámara lista, keys, límite de Shards of Dundun, inactivo desde el reset, etc.|n• Sirve para responder: “¿Qué alt tiene aún pendiente una recompensa de cámara, keys o Delver's Calls?”|n• El jefe de mundo y las misiones semanales de Lunargenta están en la pestaña |cffffffffThis Week|r, no aquí.|n• No sustituye iniciar sesión en un alt para comprobar equipo o misiones.",

	CODEX_CUR_COFFER_KEY_TITLE = "Restored Coffer Key",
	CODEX_CUR_COFFER_KEY_BODY = "• Abre el |cffffffffBountiful Coffer|r al final de una profundidad pródiga. No necesitas una para entrar en una profundidad.|n• Se hace con 100 Coffer Key Shards — al entrar en una profundidad se combinan solos. Desde el rango 6 del Delver's Journey también puedes comprar 2 por semana a Naleidea Rivergleam en el Delver's HQ.|n• Cada personaje tiene sus propias keys. Tu cantidad está en |cffffffffProfundidades & Cámara|r; la Account snapshot muestra el resto.",

	CODEX_CUR_SHARDS_TITLE = "Coffer Key Shards",
	CODEX_CUR_SHARDS_BODY = "• 100 shards forman una Restored Coffer Key. Al entrar en una profundidad se combinan solos.|n• Vienen del mundo abierto: el juego nombra tesoros, misiones de mundo y eventos al aire libre, y los raros también los dan.|n• Límite semanal de ganancia de 600 — sigue 'Weekly: X / Y' en la pestaña Delves. Son unas seis keys por semana. El rango 10 del Delver's Journey hace que cada fuente dé más.",

	CODEX_CUR_UNDERCOIN_TITLE = "Undercoin",
	CODEX_CUR_UNDERCOIN_BODY = "• Moneda de profundidades. Cae de los cofres al final de una profundidad; la mayor cantidad, de las profundidades Bountiful en Tiers altos.|n• Gástala con |cffffffffNaleidea Rivergleam|r en el Delver's HQ de Lunargenta: cosméticos, decoración, juguetes y el L00T RAID-R Mini. Desde el rango 6 del Delver's Journey también te vende con ella tus 2 Restored Coffer Keys semanales.|n• Desde el rango 5 del Delver's Journey, |cffffffffZah'ran|r aparece al final de una profundidad de Tier 6 o más. Vende equipo de campeón por Undercoin, y su surtido cambia en cada run.",

	CODEX_CUR_MANA_TITLE = "Untainted Mana-Crystals",
	CODEX_CUR_MANA_BODY = "• Compra equipo Héroe a |cffffffffZah'ran|r, el vendedor que aparece al final de una profundidad de Tier 6 o más.|n• Solo desde el rango 9 del Delver's Journey: entonces los Bountiful Coffers de Tier 11 pueden contenerlos (o un objeto Héroe), y los Tiers 8-10 dan cantidades menores.|n• Account snapshot puede mostrar los totales por personaje.",

	CODEX_CUR_ACCOLADES_TITLE = "Field Accolades",
	CODEX_CUR_ACCOLADES_BODY = "• Moneda compartida de los sistemas |cffffffffVoid & Rituals|r: la ganas en Ritual Sites y Void Assaults.|n• Gástala en el Bazar de Ciudad de Lunargenta: |cffffffffMaren Silverwing|r vende alijos de equipo (Temporada 2: equipo Aventurero por 200, equipo Veterano por 500 al azar o 750 para la ranura que elijas), |cffffffffTriam Dawnsetter|r vende cosméticos.|n• Recuento en vivo en la pestaña |cffffffffVoid & Rituals|r.",

	CODEX_CUR_DAWN_TITLE = "Crests",
	CODEX_CUR_DAWN_BODY = "• La moneda que gastas para subir el equipo un rango cada vez: 20 crests por rango, y cada track solo acepta su propio crest. No está ligada a tus ranuras de banda de la Gran cámara.|n• Los artesanos también los usan: los crests fijan el nivel de objeto de una pieza fabricada.|n• Los recuentos de crests en vivo están en |cffffffffBasics -> Crests|r (no en esta lista).|n• Hasta la semana del 20 de octubre hay un límite. Cuenta cuántos has ganado esta temporada, no cuántos tienes — gastarlos no libera espacio. Sube 100 cada semana. A partir de la semana del 20 de octubre el límite desaparece.|n• No es lo mismo que las keys de profundidad — mira esa guía para saber en qué gastarlos.",
	CODEX_TRACKS_TITLE = "Gear upgrade tracks",
	CODEX_TRACKS_BODY = "• El equipo no solo tiene un nivel de objeto — está en una |cfffffffftrack|r. De menor a mayor: |cffffffffAdventurer|r (verde), |cffffffffVeteran|r, |cffffffffChampion|r, |cffffffffHero|r, |cffffffffMyth|r.|n• Un tooltip que dice |cffffffffHero 3/6|r significa: track Hero, rango 3 de 6. Cada rango que compras añade nivel de objeto.|n• La track fija tu techo — el tooltip muestra el rango de nivel de objeto que puede alcanzar. Para superarlo necesitas un botín de una track superior.|n• Cada track tiene su propio color de crest. El contenido más difícil suelta equipo en una track superior — así es como subes.|n• ¿Track superada? Cambia los crests inferiores con |cffffffffVaskarn|r. Mejora con |cffffffffCuzolth|r en Ciudad de Lunargenta — un rango cuesta los crests de esa track más un poco de oro.|n• Cada track tiene un logro por superarla, con el nombre del crest de la temporada — en la Season 2 la serie «…of the Mist». Reduce a la mitad el coste en crests de esa track para tus otros personajes y (de Adventurer a Hero) permite a este personaje cambiar ese crest por uno superior en Vaskarn: 30 por 10 del siguiente nivel.|n• Recuentos en vivo y puntos de ruta: |cffffffffBasics -> Crests|r.",

	CODEX_DELVES_INTRO_TITLE = "Profundidades Midnight — resumen",
	CODEX_DELVES_INTRO_BODY = "• Runs cortas en instancia para 1 a 5 jugadores, con Valeera como compañera — por Quel'Thalas y la Isla Serpenteante.|n• |cffffffffTiers 1–11|r. Desde el Tier 4 necesitas nivel 90 y haber terminado una vez la campaña de Midnight en tu Warband; después, superar un tier abre el siguiente.|n• El equipo deja de mejorar en el |cffffffffTier 8|r: Bountiful Coffer 295, Gran cámara 305 (Hero 1/6). El Tier 11 sigue pagando mejores blasones.|n• Entrar es gratis — no hace falta key. Una profundidad |cffffffffpródiga|r (hasta cuatro al día) acaba con un Bountiful Coffer, y ese cofre necesita una |cffffffffRestored Coffer Key|r (ver Currencies).|n• Usa 'Find Nearest Bountiful Delve' en la pestaña Delves.",

	CODEX_DELVE_COACH_TITLE = "Delve Coach",
	CODEX_DELVE_COACH_BODY = "• Panel de consejos flotante: ruta, basura y mecánicas de jefe por profundidad.|n• Se abre solo al entrar en una profundidad, o con |cffffffffDelve Coach (preview tips)|r / |cffffffff/mh coach|r.|n• Los consejos están en el idioma de tu juego; `/mh lang` cambia entre inglés y neerlandés.|n• Foco del jefe: desplázate sobre el modelo para hacer zoom (guardado por jefe).|n• Los nombres de hechizos en azul enlazan a descripciones reales cuando se conocen los ID.",

	CODEX_DELVE_CURIOS_TITLE = "Valeera y curios de profundidad",
	CODEX_DELVE_CURIOS_BODY = "• Valeera tiene tres ranuras que llenas tú: un |cffffffffPoison|r, un |cffffffffCombat Curio|r y un |cffffffffUtility Curio|r. Su rol (Tanque, Sanador o DPS) es una elección aparte.|n• Cámbialos en los suministros al inicio de una profundidad y en su punto de control, donde también reparas.|n• La Season 2 tiene seis venenos: tres desde el principio y tres más tras las misiones de introducción de la Season 2 de Valeera (Seasonal Refresher: Midnight y luego Slithering Spoils).|n• |cffffffff/mh curios|r muestra qué hace cada opción con las palabras del propio juego, con una estrella en lo que eligen la mayoría de las guías. Un pequeño panel con esas elecciones se abre junto a su ventana.|n• El popup de objetos de profundidad sigue RAID-R Mini y Trovehunter's Bounty.",

	CODEX_TORMENTS_TITLE = "Venomfall Deeps (profundidad Némesis)",
	CODEX_TORMENTS_BODY = "• La profundidad Némesis de la Season 2, en el norte de la Isla Serpenteante: {WAY:2512:51.23:30.26:Venomfall Deeps}. El jefe es |cffffffffAzta'rec|r, en dificultad |cffffffff?|r o |cffffffff??|r.|n• Para desbloquearla, completa cualquier profundidad de Tier 7 con al menos una vida restante (para ?), o cualquier profundidad de Tier 10 con una vida restante (para ??).|n• La entrada aconseja nivel de objeto 290 para ? y 309 para ??.|n• Solo esta temporada: derrotarlo da el logro My Venomous Nemesis (una transfiguración de espalda); en ?? sin otros jugadores, Let Me Solo Him: Azta'rec (la montura Apophic Soul Crusher).|n• Torment's Rise y Nullaeus fueron la Némesis de la Season 1.|n• Delve Coach tiene el plan del combate.",

	CODEX_DELVE_LOG_TITLE = "Delve Log",
	CODEX_DELVE_LOG_BODY = "• Un registro por personaje de cada profundidad de Midnight y cada run de Ritual Site que terminas: Tier, tiempo y muertes; en las profundidades, también si usaste una key, y el jefe final.|n• Se registra solo; la pestaña no tiene que estar abierta.|n• Útil para ver qué Tier superaste por última vez y cuánto tardaste.|n• ¿Buscas una entrada? |cffffffffFind Nearest Delve|r está en la pestaña |cffffffffProfundidades & Cámara|r.",

	CODEX_MPLUS_TITLE = "Mythic+ y cámara de mazmorras",
	CODEX_MPLUS_BODY = "• Mythic+ llena la fila |cffffffffDungeons|r de la Gran cámara (separada de las filas de profundidad/mundo). Las mazmorras en Heroico, Mítico 0 y Timewalking también cuentan ahí, con una recompensa menor.|n• Una key más alta da un nivel de objeto más alto en la cámara. A tiempo o no, cuenta cada key terminada. Esta temporada deja de subir en +10.|n• Tus tres opciones usan tu mejor key de la semana, la 4.ª mejor y la 8.ª mejor.|n• Vault Advisor tiene pesos de estadística M+ propios solo para los sanadores; tanques y DPS reciben los mismos pesos para banda y para M+.|n• Midnight Helper no sustituye un addon de ruta — usa MDT / notas para las semanas de afijo.",
	CODEX_MPLUS_START_TITLE = "Mythic+, desde tu primera key",
	CODEX_MPLUS_START_BODY = "Mythic+ es una mazmorra normal con una |cffffcc00key|r (piedra angular): una llave con un nivel, como +2 o +3. Las keys más altas son más difíciles y dan mejor botín, y cada key que terminas cuenta para tu |cffffcc00Gran cámara|r.|n|n|cffffcc00Tu primera key|r|n• Termina una mazmorra Mythic 0: el último jefe te da una key.|n• O únete a la key de otra persona: al terminar, tú también recibes una.|n• ¿Perdiste la tuya o nunca tuviste una? |cffffffffLindormi|r en Silvermoon City, junto al portal a The Timeways, te da una.|n• Solo tienes una key a la vez, y empieza en +2.|n|n|cffffcc00Únete a un grupo|r|n• Pulsa |cffffffffI|r, abre |cffffffff{UI:GROUP_FINDER}|r, luego |cffffffff{UI:LFGLIST_NAME}|r y |cffffffffMazmorras|r. Las mazmorras míticas no tienen cola.|n• Elige una key baja, de +2 a +4. Los grupos marcados con |cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r esperan jugadores nuevos.|n• Haz clic en |cffffffff{UI:SIGN_UP}|r, marca tu rol y espera a que el líder te invite.|n|n|cffffcc00Crea tu propio grupo|r|n• En el mismo sitio: haz clic en |cffffffff{UI:START_A_GROUP}|r, elige la mazmorra de tu key, elige un estilo de juego (|cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r está bien) y haz clic en |cffffffff{UI:LIST_GROUP}|r.|n• Pon la dificultad de mazmorra en |cffffffffMítica|r antes de entrar.|n• Dentro, quien tenga la key hace clic en la |cffffffffFont of Power|r cerca de la entrada, pone la key y pulsa |cffffffff{UI:CHALLENGE_MODE_START_CHALLENGE}|r. Tras una cuenta atrás de 10 segundos empieza el tiempo.|n|n|cffffcc00Durante la run|r|n• De +2 a +5 morir no cuesta tiempo, y los enemigos marcados te muestran una ruta. Desde +6 cada muerte cuesta tiempo.|n• Desde +5 se suma una regla extra de la semana. La pestaña |cffffffff{UI:CHALLENGES}|r del buscador de grupos te dice cuál.|n• A tiempo: tu key sube de 1 a 3 niveles. Tarde: sigues recibiendo botín, pero la key baja 1 nivel. En ambos casos pasa a otra mazmorra.|n• ¿Tienes que parar? Escribe |cffffffff/abandon|r para iniciar una votación. Si simplemente te vas, te pueden marcar como Keystone Deserter.|n• Al final, cada uno abre el cofre para su propio botín.|n|n|cffffcc00Ayuda|r|n• Dilo en el grupo: 'first time in this dungeon' (primera vez en esta mazmorra). En keys bajas, la mayoría de jugadores te lo explica con gusto.|n• Pregunta a tu hermandad, o mira en |cffffffff{UI:COMMUNITIES_GUILD_FINDER}|r y |cffffffffBuscar una comunidad|r en la ventana de Hermandad y comunidades (J).|n• Tu |cffffffff{UI:DUNGEON_SCORE}|r está en la pestaña {UI:CHALLENGES}. Muchos líderes también miran la puntuación de Raider.IO.|n|nMidnight Helper te ayuda dentro: los consejos de jefe se abren al entrar, y |cffffffff/mh mplus|r muestra tu mejor run por mazmorra y dónde una key suma más.",
	CODEX_AGGRO_TITLE = "Aggro: ¿a quién golpea el enemigo?",
	CODEX_AGGRO_BODY = "Aggro significa que un enemigo te está atacando. El tank lo quiere; un DPS o healer que lo atrae suele morir. El juego ya puede avisarte, pero muchos jugadores tienen estos avisos desactivados. Midnight Helper no te cambia ninguno: escribe |cffffffff/mh aggro|r para ver cómo los tienes configurados.|n|n• |cffffffff{UI:NAMEPLATE_OPTIONS_LABEL} > {UI:UNIT_NAMEPLATES_THREAT_DISPLAY}|r: marca |cffffffff{UI:UNIT_NAMEPLATES_THREAT_DISPLAY_FLASH}|r. La placa de nombre de un enemigo parpadea cuando el tank lo pierde o cuando un DPS o healer lo atrae.|n• |cffffffff{UI:COMPACT_UNIT_FRAME_PROFILE_DISPLAYAGGROHIGHLIGHT}|r (marcos de banda): un borde rojo alrededor de quien tiene el aggro. Útil para los healers.|n• |cffffffff{UI:ACCESSIBILITY_AUDIO_LABEL} > {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} > {UI:CAA_SAY_IF_TARGETED_LABEL}|r: una voz te avisa cuando un enemigo te elige como objetivo. Activa primero {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL}; este ajuste se guarda por especialización.|n|n¿Usas un addon de placas de nombre como Plater? Entonces el parpadeo en las placas de nombre viene de ese addon, no del juego: mira en sus propios ajustes.",

	CODEX_RAID_VAULT_TITLE = "Banda — Gran cámara",
	CODEX_RAID_VAULT_BODY = "• Los jefes de banda llenan la fila Bandas de la cámara: 2, 4 y 6 jefes abren una, dos y tres opciones. Cuenta cualquier dificultad, también el Buscador de bandas, y también el jefe de la Lair.|n• En la Temporada 2 cada opción viene de una dificultad por encima de aquella en la que mataste a los jefes: Buscador de bandas da Champion, Normal da Hero, Heroico da Myth, Mítico da Myth a un nivel más alto.|n• Dificultades mezcladas: cada opción usa la dificultad más alta en la que llegaste a ese número de jefes. La UI de cámara muestra lo que tienes esta semana.|n• Los crests son lo que gastas después para mejorar el equipo de banda.",

	CODEX_VAULT_ADVISOR_TITLE = "Consejero de la Gran cámara",
	CODEX_VAULT_ADVISOR_BODY = "• Panel lateral junto a la ventana de la Gran cámara de Blizzard cuando eliges tu recompensa en la Gran cámara de Silvermoon — no dentro de las pestañas de Midnight Helper. SHIFT-J solo muestra un resumen, así que el panel no aparece ahí.|n• Clasifica las piezas de cámara frente al equipo puesto usando las prioridades de estadística de la guía (y Pawn opcional).|n• Se activa en los ajustes rápidos de minimapa / Esc -> AddOns -> Midnight Helper.|n• Perfil Auto vs Banda vs M+ para los pesos de estadística.",

	CODEX_WORLD_HUB_TITLE = "Void & Rituals — un solo sistema",
	CODEX_WORLD_HUB_BODY = "• Desde el parche 12.0.5, |cffffffffRitual Sites|r y |cffffffffVoid Assaults|r funcionan como un solo sistema. Ambos se mueven cada semana entre Eversong Woods y Zul'Aman, y comparten una moneda y un renombre.|n• Mismas |cffffffffField Accolades|r y hub del Bazaar — no las farmees como actividades separadas.|n• La Temporada 2 bajó el equipo que compras con Field Accolades a aventurero y veterano: útil para un personaje nuevo, no para el mejor equipo.|n• Abre la pestaña combinada para ver el sitio y la zona activos de esta semana, tus Field Accolades y tu renombre, y los botones de ruta.",

	CODEX_RITUAL_TITLE = "Ritual Sites",
	CODEX_RITUAL_BODY = "• Un ritual en instancia para 1 a 5 jugadores. Cada semana está en uno de dos sitios: Daggerspine Point en Eversong Woods o el Broken Throne en Zul'Aman. Elige un Tier y termínalo para conseguir accolades, renombre y botín.|n• Solo un sitio está activo a la vez; el addon resalta cuál.|n• El pin de Ritual Site en la SMC City Guide pone una ruta al sitio activo de esta semana. Si el addon aún no lo conoce, el pin abre la pestaña Void & Rituals.",

	CODEX_VOID_TITLE = "Void Assaults",
	CODEX_VOID_BODY = "• El Vacío ataca Eversong Woods o Zul'Aman, una de las dos cada semana. Despeja Void Strikes; con suficientes empieza una Void Incursion más grande. Ambos dan Field Accolades.|n• Comparte las Field Accolades y el renombre de Ritual Sites con Ritual Sites: avanzas en ambos a la vez.|n• La pestaña Void & Rituals muestra la zona de esta semana, la de la semana que viene y tu misión semanal.",

	CODEX_RARES_TITLE = "Rares Midnight",
	CODEX_RARES_BODY = "• Mobs raros semanales con botín de cuenta/personaje (revisa las reglas de cada raro en el juego).|n• Pestaña |cffffffffRares|r: sigue los kills y crea una ruta, el raro más cercano primero. La flecha de ruta (la de Midnight Helper, o la de TomTom si lo usas) pasa después al siguiente más cercano.|n• Alerta en vivo cuando un raro seguido está cerca (~500 yd) — se activa en los ajustes.",

	CODEX_PROF_TITLE = "Profesiones — ciclo semanal",
	CODEX_PROF_BODY = "• Cada profesión tiene sus propios |cffffffffpuntos de conocimiento (KP)|r y su propio |cffffffffArrojo de artesano|r: el Arrojo de Alquimia solo compra cosas de Alquimia.|n• |cffffffffCada semana, por profesión:|r la misión semanal de tu instructor en Lunargenta (desde la habilidad 25), los |cffffffffPatron orders|r en la mesa de Crafting Orders que dan conocimiento (la mayor fuente semanal), hasta dos objetos de conocimiento de tesoros normales en las zonas de Midnight, y un Thalassian Treatise (fabricado por Inscripción).|n• Los recolectores y los encantadores también consiguen objetos de conocimiento al recolectar o desencantar. Con esos recuperas una semana perdida; con la mayoría de las demás fuentes semanales, no.|n• |cffffffffAbundance|r es una vía aparte: un Shard of Dundun (8 por semana como máximo) inicia una Abundant Harvest, y eso da Unalloyed Abundance.|n• Pestaña |cffffffffProfesiones|r: KP sin gastar, tus Shards of Dundun y pines de mapa para tesoros y libros. Dónde gastar los KP: la guía Basics.",

	CODEX_PROF_GUIDE_TITLE = "Profesiones — guía para principiantes",
	CODEX_PROF_GUIDE_BODY = "• Subpestaña |cffffffffBasics -> Profesiones|r: plan de KP paso a paso y sugerencias de combos.|n• La subpestaña |cffffffffCrests|r trata de los crests: la moneda con la que mejoras el equipo, que se gana en muchas actividades, no solo en bandas.|n• Relee tras los parches — los números y los límites pueden cambiar.",
	CODEX_PROFRESET_TITLE = "Reiniciar las especializaciones de una profesión (12.1)",
	CODEX_PROFRESET_BODY = "• El parche 12.1 permite deshacer tus elecciones de especialización Midnight — una vez por profesión.|n• |cffffffffCon quién:|r Theremis, en el Bazar de Ciudad Lunargenta junto a los encargos de artesanía. Ofrece una línea por profesión, así que puedes reiniciar Herrería y dejar Encantamiento intacto.|n• |cffffffffQué recuperas:|r cada punto de Conocimiento gastado en los árboles Midnight de esa profesión, libre para repartir de nuevo.|n• |cffffffffQué cuesta:|r el aviso del juego dice “You will lose all associated recipes”.|n• |cffffffffAsociadas, no todas.|r Lo que se pierde es lo que esas especializaciones habían desbloqueado. Las recetas de un maestro, de un botín o de una misión están fuera de los árboles y se quedan. Visto en un Encantamiento reiniciado: la lista de recetas estaba intacta y el Conocimiento gastado había vuelto al contador.|n• |cffffffffEs una sola vez.|r La confirmación escribe ONCE en mayúsculas, y es por profesión — no hay segundo intento si el nuevo camino decepciona.|n• Decide |cffffffffantes|r de confirmar. La página de Profesiones nombra el árbol a llenar y el nodo exacto.|n• ¿Vuelven las recetas retiradas si repartes igual que antes? El juego no lo dice en ninguna parte. Cuenta con que no.",
	CODEX_CORRPOWER_TITLE = "Corrosive Codex — ¿qué gift cojo primero?",
	CODEX_CORRPOWER_BODY = "|cffffcc00Doce gifts, y puedes usar uno.|r Cada uno cuesta |cffffffff8 Corrosive Souls|r, así que los doce juntos cuestan 96. Como el precio es el mismo para todos, tu primera elección va de |cffffffffqué necesitas|r — nunca de qué te puedes permitir.|n|n|cffffff78Una sola cosa explica todo el sistema|r|n• Es un |cffffffffciclo de veneno|r. La mitad de los gifts se vuelve más fuerte contra un enemigo Poisoned, o mientras |cfffffffftú mismo|r estás envenenado.|n• Por eso cada buena pareja es |cffffffffun gift que envenena + un gift que se aprovecha de ello|r. En cuanto lo ves, las combinaciones dejan de parecer aleatorias.|n|n|cffffff78¿Cuál primero? Elige por tu problema, no por una lista|r|n• |cffffffffSolo quiero pegar más fuerte|r → |cffffffffUla'tek's Gift|r. Funciona solo, sin un segundo gift y sin preparación. Todas las guías que leímos lo nombran primero.|n• |cffffffffLos grupos de enemigos tardan demasiado|r → |cffffffffPlague of Corrosion|r u |cffffffffOphidian Maw|r.|n• |cffffffffMuero constantemente en las profundidades|r → |cffffffffVirulent Mucus|r absorbe los golpes grandes, |cffffffffGorgoneion Gaze|r petrifica todo a tu alrededor en cuanto bajas de la mitad de tu vida.|n• |cffffffffLos lanzadores acaban su hechizo|r → |cffffffffAccursed Poison|r. Interrumpe uno por ti.|n|n|cffffcc00Cuidado con Mephitic Cloud.|r Deja que los |cffffffffenemigos|r afectados curen a lo que atacan. En grupo eso juega en tu contra.|n|n|cffffff78Qué hemos medido nosotros y qué no|r|n• |cffffffffDel juego:|r el precio de 8 y el texto completo de Ula'tek's Gift. Eso es nuestro.|n• |cffffffffDe guías:|r el orden de arriba y cuántos gifts abren la segunda ranura. El juego solo dice \"until your offerings are sufficient\" y no da ninguna cifra. |cffffffffSeis fuentes dicen 8|r — entre ellas la propia página de hechizo de Wowhead, que lo pone en una tabla — y un blog dice 6. Así que 8 es casi seguro lo correcto; simplemente no lo hemos visto nosotros. Lo sabrás en el momento en que aparezca tu segunda ranura.|n• A Ula'tek's Gift ya |cffffffffle han bajado la potencia una vez|r. Una clasificación de agosto no es automáticamente cierta hoy — justo por eso el ciclo de veneno de arriba es la parte que hay que recordar.",
	CODEX_ATALUTEK_TITLE = "Las Vaults of Atal'Utek — qué hay dentro y dónde",
	CODEX_ATALUTEK_BODY = "|cff8fd3ffPara empezar|r|n|n• |cffffffffQué es:|r una zona de la 12.1 en la Coiled Isle con mapa propio, y debajo un segundo mapa, la Underbelly. Ya está abierta — no hay puerta de temporada.|n|n• |cffffffffCómo entrar:|r una cadena de cuatro misiones — |cffffffffInto the Vaults of Atal'Utek|r, luego |cffffffffVaults of Atal'Utek: One Coin Too Many|r y |cffffffffVaults of Atal'Utek: A Toxic Tour|r, que te dan a la vez, luego |cffffffffVaults of Atal'Utek: The Altar of Corrosion|r. Todo lo demás está detrás de ellas, así que hazlas primero. |cffffffffA Toxic Tour es una misión de historia única, no una diaria|r — pide una Patrol, un Strike, una Incursion y un Ancient Foe, así que se completa sola mientras haces la vuelta que se describe más abajo.|n|n|cff8fd3ffQué se hace aquí|r|n|n• |cffffffffLo que realmente haces aquí — cuatro cosas, y se alimentan entre sí.|r Las |cffffffffTemple Patrols|r recorren el mapa y rotan cada diez minutos aproximadamente; son lo más fácil a lo que unirse y casi siempre hay una. Las |cffffffffTemple Strikes|r son más grandes y preparan una incursión. Cuando se han hecho suficientes Strikes empieza una |cffffffffTemple Incursion|r, y cada Incursion termina despertando a un |cffffffffAncient Foe|r — de ahí salen los tres élites raros: solo uno de ellos por semana, con diez minutos de reloj. Monedas, llaves, equipo y reputación salen todos de ese bucle. Si te preguntas qué hacer: únete a lo que esté en marcha.|n|n• |cffffffff¿Cómo encuentro realmente un Temple Strike?|r Abre el mapa dentro de las Vaults y busca los iconos de evento — un Strike aparece ahí como cualquier evento de zona, y |cffffffffno tiene temporizador|r: se queda esperando hasta que un grupo lo termina, así que puedes ir andando con calma. |cffffffffCon unos pocos jugadores basta|r; no hace falta grupo montado, y normalmente ya hay gente. Hay seis, cada uno con un punto de inicio fijo — pulsa para marcar: {WAY:2509:50.55:15.70:Cursed Depths} · {WAY:2509:47.36:46.17:Overflowing Venom} · {WAY:2509:47.67:46.34:Profane Pyres} · {WAY:2509:47.26:26.69:Purifying Earth and Sky} · {WAY:2509:39.32:39.92:Ruuk’Jar’s Clutch} · {WAY:2613:52.25:36.27:The Underbelly}.|nSi el mapa no muestra ningún Strike, probablemente hay en marcha una Incursion o su Ancient Foe: únete a eso. Aparece un Strike nuevo en cuanto termina.|n|n• |cffffffffMoverte por dentro.|r Los |cffffffffAmani Windcallers|r te llevan entre tres puntos de las Vaults — el centro |cffffffffAmani Foothold|r, el Eastern Amani Outpost y el Northern Amani Bulwark. El maestro de vuelo |cffffffffEagletender Mal’Tiki|r está en {WAY:2509:44.42:62.21:Amani Foothold}. No se puede volar dentro de las Vaults, y por eso están ahí — es más grande de lo que parece, y andar es la forma lenta.|n|n• |cffffffffLas misiones repetibles — una semanal y ocho diarias.|r |cffffffffPurging the Vaults|r con |cffffffffWarleader Abdumati|r en el Amani Foothold es la semanal que no conviene saltarse. Las ocho diarias son |cffffffffPatrolling the Temple|r, |cffffffffBounty of the Cursed|r, |cffffffffRelentless Strikes|r, |cffffffffDecisive Incursions|r, |cffffffffFrom Whence it Came|r, |cffffffffEssence of Malice|r, |cffffffffWhat's Out There?|r y |cffffffffShoulder to Shoulder|r — coge las que te ofrezca el mapa hoy. La mayoría piden las actividades de arriba, así que se completan solas mientras juegas. Dos quieren que estés en grupo (What's Out There? y Shoulder to Shoulder): basta con la gente que ya está a tu lado, no hace falta un grupo montado. Y una que nunca encontrarás estando aquí: |cffffffffMidnight: Vaults of Atal'Utek|r es una meta semanal de este lugar que se recoge en |cffffffffSilvermoon|r.|n|n|cff8fd3ffCoin and Soul|r|n|n• |cffffffffCorrosive Coin|r es la moneda de la zona. En palabras del propio juego: “Spirits of the Amani within the Vaults of Atal'Utek deal exclusively in this phantasmal token.” Tu saldo es el número que aparece encima de este artículo.|n|n• |cffffffffCorrosive Soul no es eso.|r No es una moneda en absoluto, sino un |cffffffffobjeto|r en tus bolsas, y es lo que el Corrosive Codex te pide ofrecer. Las guías intercambian los dos nombres continuamente; el juego nunca. Si algo te dice que gastes Corrosive Coins en el Codex, esa es la confusión.|n|n• |cffffffffAdónde van las monedas — dos sitios, ambos en Er’inye|r en {WAY:2509:51.10:62.76:Er'inye}. Hablar con ella compra |cffffffffCorrode Spirit|r, que alimenta el árbol del altar; a su lado, la |cffffffffSkull of Er’inye|r es un mercader con tres páginas de monturas, mascotas, conjuntos y recetas, de 500 a 25.000 monedas. |cffffffffEl precio del corrode sube cada vez que lo compras|r — visto a 1.500 y luego 2.000 en una visita — así que lee la ventana en vez de ahorrar para una cifra.",
	CODEX_ATALUTEK_DISC_TITLE = "Altar of Corrosion: las cuatro llaves",
	CODEX_ATALUTEK_DISC_BODY = "• |cffffffffEl Altar of Corrosion|r es el árbol de nodos que abre la última misión de la cadena. La mayoría se abre al gastar, pero |cffffffffcuatro nodos están detrás de una llave que tienes que ir a buscar|r — y los cuatro funcionan igual: cae un objeto, lo usas sobre un objeto fijo en algún punto de las Vaults, eso da un objeto de misión, y Er’inye hace el resto.|n|cffffffffCorroded Key|r → el Venom-Worn Coffer → |cffffffffRun of the Vaults|r (Glideways, o Swift Steps) · |cffffffffSpirit Loupe|r → la Feather of Tok’jara en {WAY:2509:48.46:25.80:Feather of Tok'jara} → |cffffffffSpectral Winds|r (Spirit Walk, o Spectral Shipping) · |cffffffffExcising Knife|r → el Eye of Szarith, en una charca de veneno de la Underbelly → |cffffffffBroodmaster|r (+100% de daño a los huevos, o −75% de daño de sus estallidos) · |cffffffffDispelling Charm|r → Jin’tal’s Reliquary en el Profaned Mausoleum → |cffffffffSpiritual Protection|r (aliados fantasmales en los Curse Surges, o levantarte al instante si mueres fuera de las Vaults).|n|cffffffffEnseñarle una llave a Er’inye no desbloquea nada.|r Es ciega y te cuenta lo que siente: eso es una pista de dónde va el objeto. |cffffffffDe dónde salen las llaves|r — las guías ya coinciden: la Corroded Key, de los Temple Strikes; el Excising Knife, de una Temple Incursion; la Spirit Loupe, de un Ancient Foe. El |cffffffffDispelling Charm|r es la excepción: no sale de los eventos, sino de Jin’tal en la Vault of Restless Bones, durante una cadena de misiones secundaria sobre los Med’jai.|n|n• |cffffffffGasta tus primeras monedas en el árbol de inmediato.|r Sus cuatro primeros nodos no cuestan nada y se abren mientras gastas en otra parte, y aumentan la Corrosive Coin que ganas un |cffffffff25, 50, 75 y finalmente 100 por ciento|r. El árbol se paga solo, así que cada vuelta después de la primera rinde más — ahorrar es la opción cara. Y fíjate en la asimetría que marca el ritmo de la zona: |cfffffffflas monedas no tienen tope|r, las Corrosive Souls sí. Farmea monedas sin miedo; no planees una noche alrededor de las souls.",
	CODEX_ATALUTEK_DEAD_TITLE = "The Honored Dead y los raros",
	CODEX_ATALUTEK_DEAD_BODY = "• |cffffffff“The Honored Dead” — doce memoriales|r en el mapa de las Vaults, un logro, y lo más claro que puedes ir a hacer aquí. En un solo orden de recorrido, de arriba del mapa hacia abajo:|n{WAY:2509:46.79:7.51:To a sister 46.79, 7.51} · {WAY:2509:56.49:22.88:To a shield-bearer 56.49, 22.88} · {WAY:2509:47.22:28.77:To a father 47.22, 28.77} · {WAY:2509:42.57:33.18:To a stranger 42.57, 33.18} (bajo el puente) · {WAY:2509:52.91:33.90:To a captain 52.91, 33.90} · {WAY:2509:55.62:40.60:To a dream 55.62, 40.60} · {WAY:2509:42.84:39.93:To sons 42.84, 39.93} · {WAY:2509:52.21:45.12:To a lover 52.21, 45.12} · {WAY:2509:38.50:47.66:To Comrades 38.50, 47.66} · {WAY:2509:55.31:48.45:To parents 55.31, 48.45} · {WAY:2509:49.50:56.59:To a daughter 49.50, 56.59} · {WAY:2509:45.81:61.79:To Failure 45.81, 61.79}|n|n• |cffffffffLa Underbelly|r es el mapa de abajo, se entra en {WAY:2509:47.30:11.20:The Underbelly} del mapa de las Vaults. Allí vive un raro, |cffffffffSzarith the Fanged|r en {WAY:2613:38.40:17.69:Szarith the Fanged}, y la Underbelly tiene un logro propio: |cffffffffSoft Underbelly|r. |cffffffffCon Szarith solo no basta:|r según las guías, el logro también pide varios élites con nombre que solo aparecen mientras está en marcha el Temple Strike |cffffffffThe Underbelly|r.|n|n• |cffffffffTres élites raros en el mapa principal|r — Congealed Malice, Khu'tulak y Susarikk — forman un tercero: |cffffffffOppose the Foes|r. |cffffffffNo tienen un sitio fijo, y esa es la respuesta, no un hueco|r: uno de los tres despierta en cuanto se completa una |cffffffffTemple Incursion|r, y tienes unos diez minutos para matarlo. |cffffffffSolo uno de los tres está en la rotación cada semana|r, así que este logro lleva al menos tres semanas. No sales a cazarlos: terminas Incursions, y el de esta semana viene a ti.",
})

merge(ns._mhLocales and ns._mhLocales.ptBR, {
	TAB_CODEX = "Midnight Codex",
	CODEX_PANEL_TITLE = "Midnight Codex",
	CODEX_PANEL_INTRO = "Seu manual para Midnight — o que é cada sistema, para que serve cada moeda e onde clicar neste addon. Passe o cursor sobre os ícones de moeda para ver as dicas da Blizzard.",
	CODEX_OPEN_TAB_FMT = "Abrir: %s",
	CODEX_NAV_DELVES_VAULT = "Aba Delves & Vault (bloco do Grande Cofre)",
	CODEX_NAV_DELVES_MIDNIGHT = "Aba Delves & Vault (lista de profundezas)",
	CODEX_NAV_BASICS_DAWN = "Categoria Basics (Crests)",
	CODEX_NAV_BASICS_PROF = "Aba Basics (guia de Profissões)",
	CODEX_BALANCE_FMT = "Você tem: |cffffffff%d|r",
	CODEX_BALANCE_UNKNOWN = "O saldo atualiza quando você entra com este personagem.",
	CODEX_SEARCH_OPENED = "Midnight Codex aberto.",
	CODEX_BETA_DISABLED = "O Midnight Codex está desativado nas Configurações (abas beta).",

	CODEX_CAT_START = "Comece aqui",
	CODEX_CAT_WEEKLY = "Ciclo semanal",
	CODEX_CAT_CURRENCIES = "Currencies",
	CODEX_CAT_DELVES = "Delves",
	CODEX_CAT_DUNGEONS = "Dungeons & M+",
	CODEX_CAT_RAID = "Raide & Crests",
	-- ⚠️ Was "Void & Rituals" until 19 aug, and half of what sits under it is neither.
	-- The category holds Prey hunts, rares, Turbulent Timeways and Showdowns alongside
	-- the void and ritual articles. Rob went looking for Prey, read that button, and
	-- walked straight past it — the same class of fault as the twelve type-only commands
	-- on 18 aug: the feature was there, under a name nobody would guess.
	CODEX_CAT_WORLD = "World content",
	CODEX_CAT_COILEDISLE = "Coiled Isle",
	CODEX_ROUTE_BTN = "Seguir a rota",
	CODEX_CAT_PROFESSIONS = "Professions",

	CODEX_START_TITLE = "Comece aqui — sua semana Midnight",
	CODEX_START_BODY = "|cffffcc00Pense em camadas:|r um reset semanal, várias trilhas de recompensa. Você não precisa de cada sistema todo dia — escolha um objetivo.|n|n|cffffff781) Conta & reset|r|n• Confira a aba |cffffffffThis Week|r para o cofre, o chefe de mundo, as keys e as tarefas.|n• |cffffffffAccount snapshot|r mostra todos os seus alts (cofre, Delver's Call, semanais de profissão).|n|n|cffffff782) Conteúdo de combate|r|n• |cffffffffDelves|r — trilha principal de equipamento (keys, níveis, espaços do Grande Cofre). Use |cffffffffDelve Coach|r para dicas por profundeza.|n• |cffffffffMythic+|r e |cffffffffRaide|r preenchem outros espaços do Grande Cofre (veja categorias Dungeons & Raide).|n|n|cffffff783) Mundo aberto|r|n• |cffffffffIlha Enrolada|r — a zona da Série 2, do patch 12.1, com uma categoria própria aqui.|n• As caçadas de |cffffffffPrey|r contam para a mesma linha do Grande Cofre que as profundezas.|n• Aba |cffffffffVoid & Rituals|r — Field Accolades, Ritual Sites, Void Assaults (mesma trilha de renome).|n• Aba |cffffffffRares|r — saque raro semanal e rotas.|n|n|cffffff784) Profissões|r|n• Aba |cffffffffProfissões|r para KP / mats semanais; |cffffffffBasics|r para Crests.|n|n|cffffcc00Dica:|r abra a categoria |cffffffffCurrencies|r aqui quando esquecer para que serve uma ficha. Role a prévia do chefe no Delve Coach para dar zoom.",
	CODEX_MIDSTART_TITLE = "Começar a campanha Midnight",
	CODEX_MIDSTART_BODY = "|cffffcc00No nível 80 a missão |r|cffffffffMidnight|r|cffffcc00 chega sozinha.|r Não precisa procurar nada — ela cai no seu registro assim que você chega a 80. Abaixo de 80 você já consegue viajar até Silvermoon, mas ainda não há nada para aceitar lá.|n|n|cffffff78Onde começa|r|n• Fale com a |cffffffffImage of Lady Liadrin|r. Ela fica em mais de uma capital, então também na sua.|n• Ela oferece duas coisas: assistir à introdução, ou |cffffffffI have heard this tale before|r para pular.|n|n|cffffff78Pular não custa nada|r|n• Você sai em |cffffffffSilvermoon|r e recebe a próxima missão na hora.|n• Nada fica trancado atrás da introdução — rotas, pontos da cidade e a rotina semanal funcionam igual.|n|n|cffffff78Escolher por onde começar|r|n• Essa próxima missão, |cffffffffAdventuring in Midnight|r, manda você para a |cffffffffScouting Map|r no Sanctum of Light.|n• Cinco pontos de partida: |cffffffffArator's Journey|r, |cffffffffEversong|r, |cffffffffZul'Aman|r, |cffffffffVoidstorm|r e |cffffffffHarandar|r.|n• Passe o mouse por um para ver o que tem lá; clicar só abre o scouting report dele. |cffffffffOlhar não custa nada.|r|n|n|cffffcc00Escolheu e mudou de ideia?|r Escolher esconde os outros quatro enquanto essa missão estiver no seu registro — mas |cffffffffabandone a missão|r e os cinco voltam. Ela define sua ordem, não seu caminho.",
	CODEX_WARBAND_TITLE = "Bando de guerra & seu banco",
	CODEX_WARBAND_BODY = "|cffffcc00Seu bando de guerra|r são todos os personagens da sua conta, tratados como um time. Muita coisa agora é |cffffffffvinculada ao bando de guerra|r — compartilhada na conta toda — então você envia bem menos correio entre alts.|n|n|cffffff78Itens & moedas vinculados ao bando de guerra|r|n• Algumas moedas são compartilhadas pela conta toda ou podem ser movidas entre personagens — sua janela de moedas mostra quais. Os crests de melhoria contam por personagem.|n• O equipamento costuma ser |cffffffffvinculado ao bando de guerra até equipar|r — mande para um alt, mas uma vez equipado fica com aquele personagem.|n|n|cffffff78O banco do bando de guerra|r — um banco compartilhado que todos os seus personagens usam.|n• Abra com |cffffffffqualquer banqueiro|r (ou Jeeves) — é uma aba do seu banco normal, ao lado do banco de personagem.|n• Guarde qualquer item |cffffffffnão vinculado à alma|r e deposite ou retire |cffffffffouro|r entre personagens (até entre facções).|n• Fabrique direto dele — conta como fonte de reagentes.|n|n|cffffff78Abas & custo|r — 5 abas, 98 espaços cada (490 no total). Você começa sem nenhuma; compre-as com ouro:|n• Aba 1: |cffffffff1.000o|r|n• Aba 2: |cffffffff25.000o|r|n• Aba 3: |cffffffff100.000o|r|n• Aba 4: |cffffffff500.000o|r|n• Aba 5: |cffffffff2.500.000o|r  (as cinco = 3.126.000o)|n|n|cffffcc00Dica:|r 2-3 abas bastam para a maioria. Não confunda com seu |cffffffffbanco de personagem|r (também com abas desde o patch 11.2, bem mais barato) — esse é por personagem; o banco do bando de guerra é compartilhado.",

	CODEX_WEEKLY_RESET_TITLE = "Reset semanal",
	CODEX_WEEKLY_RESET_BODY = "• A maior parte do progresso semanal reinicia no dia de manutenção da sua região (EU quarta de manhã, US terça de manhã).|n• As escolhas do Grande Cofre, o saque do chefe de mundo e muitos limites semanais reiniciam.|n• A aba |cffffffffThis Week|r mostra o tempo até o reset quando a API fornece.|n• Planeje os alts: o |cffffffffAccount snapshot|r compara quem ainda tem uma recompensa do cofre, keys ou Delver's Calls pendentes.",

	CODEX_VAULT_TITLE = "Grande Cofre",
	CODEX_VAULT_BODY = "• Três linhas: |cffffffffWorld|r (profundezas, Prey e outras atividades de mundo), |cffffffffDungeons|r (Heroico, Mítico, Mythic+ e Caminhada Temporal), |cffffffffRaide|r (chefes de raide em qualquer dificuldade, e o chefe do Lair).|n• Cada linha abre até três opções: World com 2/4/8 atividades, Dungeons com 1/4/8, Raide com 2/4/6 chefes.|n• Cada opção é só tão boa quanto a run mais fraca de que ela precisou: a opção de 4 runs usa sua 4ª melhor run da semana, a opção de 8 runs a sua 8ª melhor. Uma key difícil só melhora sua primeira opção de Dungeons.|n• Série 2: uma opção de raide vem um degrau acima do que você matou — chefes mortos no Normal dão um item da track Herói, no Heroico um item da track Mito.|n• Após o reset você escolhe |cffffffffuma|r recompensa no total entre todas as opções desbloqueadas, no Grande Cofre em Silvermoon. SHIFT-J só mostra um resumo.|n• Com 3 ou mais opções desbloqueadas, de quaisquer linhas, você pode pegar um |cffffffffNebulous Voidcore|r (uma rolagem bônus) em vez de um item.|n• |cffffffffVault Advisor|r (na UI do cofre da Blizzard) classifica as opções contra seu equipamento.|n• Neste addon a linha World fica na aba |cffffffffProfundidades & Cofre|r — expanda |cffffffffGrande Cofre (mundo)|r. Passe o cursor sobre um personagem no |cffffffffAccount snapshot|r para ver as três linhas.|n• Resumo também na aba |cffffffffThis Week|r.",

	CODEX_WORLDBOSS_TITLE = "Chefe de mundo (Midnight)",
	CODEX_WORLDBOSS_BODY = "• Um chefe de mundo rotativo por semana (Lu'ashal, Cragpine, Thorm'belan, Predaxas), como missão mundial com uma caveira no mapa. Você não precisa pegar nada.|n• Lady Liadrin em Lunargente às vezes oferece |cffffffffMidnight: World Boss|r como uma das suas quatro opções semanais; derrotar o chefe desta semana a conclui.|n• Saque de bando de guerra: assim que um personagem o mata, os alts aparecem como concluídos.|n• Acompanhado no topo da aba |cffffffffProfundidades & Cofre|r com rota TomTom.|n• Também vinculado pelo SMC City Guide quando você está em Lunargente.",
	CODEX_FOLIO_TITLE = "Omnium Folio (12.0.7)",
	CODEX_FOLIO_BODY = "• Sistema de poder do patch 12.0.7, ainda ativo na 12.1 — um livro de minimapa de |cffffffffrunas|r que você troca livremente fora de combate (sem custo de espaço).|n• O poder vem da cadeia |cffffffff'Seeking Knowledge'|r (5 etapas): The Omnium Folio, Ritualized Arcana, Ley Line Assaults, Magical Primessence, Off-World Magic.|n• Cada etapa recompensa um |cffffffffMote of Omnial Inquiry|r que abre a próxima fileira de runas.|n• Conclua as 5 para a conquista meta e a decoração Sunstrider Omnium Simulacrum.|n• Perdeu semanas? Faça as missões perdidas em sequência para recuperar — sem esperar resets.|n• Alts: depois que um personagem fez a introdução, os outros podem pulá-la (12.1). Suas escolhas de runas continuam sendo por personagem.",
	CODEX_TT_TITLE = "Turbulent Timeways (12.0.7)",
	CODEX_TT_BODY = "• Evento Caminhada Temporal de volta — desta vez um grupo de masmorras de |cffffffffDragonflight|r: Algeth'ar Academy, Halls of Infusion, Neltharus, Ruby Life Pools, The Azure Vault, Brackenhide Hollow.|n• Semanal: faça |cffffffff5 masmorras de Caminhada Temporal|r por um cache de equipamento; cada run acumula |cffffffffKnowledge of Timeways|r (buff de XP).|n• Ganhe |cffffffffMastery of Timeways|r em 4 de 6 semanas para 'Master of the Turbulent Timeways' e a montaria |cffffffffSpawn of Vyranoth|r.|n• Gaste os Distintivos Temporais no vendedor do evento.|n• Vai de ~30 jun a 11 ago. (Datamined — confirmar no lançamento.)",

	CODEX_DELVER_CALL_TITLE = "Delver's Call",
	CODEX_DELVER_CALL_BODY = "• Uma missão por profundeza Midnight: termine essa profundeza uma vez, em qualquer tier. Cada personagem pode fazer cada uma só uma vez — elas não voltam toda semana.|n• Elas dão muita XP, e a recompensa cresce com o seu nível. Enquanto sobe de nível: termine as profundezas cedo e entregue as missões tarde (por volta do nível 87-88).|n• |cffffffffAccount snapshot|r mostra quais personagens ainda guardam calls concluídas (no banco).|n• Passe o cursor sobre a linha Delver's Call no snapshot para o detalhe por personagem.",

	CODEX_ACCOUNT_TITLE = "Account snapshot",
	CODEX_ACCOUNT_BODY = "• Visão somente leitura dos personagens com que você entrou usando o Midnight Helper.|n• Ordene/filtre por cofre pronto, keys, limite de Shards of Dundun, inativo desde o reset, etc.|n• Serve para responder: “Qual alt ainda tem uma recompensa do cofre, keys ou Delver's Calls esperando?”|n• O chefe de mundo e as missões semanais de Silvermoon ficam na aba |cffffffffThis Week|r, não aqui.|n• Não substitui entrar em um alt para conferir equipamento ou missões.",

	CODEX_CUR_COFFER_KEY_TITLE = "Restored Coffer Key",
	CODEX_CUR_COFFER_KEY_BODY = "• Abre o |cffffffffBountiful Coffer|r no fim de uma profundeza Bountiful. Você não precisa de uma para entrar numa profundeza.|n• Feita de 100 Coffer Key Shards — entrar numa profundeza junta os shards para você. A partir do rank 6 do Delver's Journey você também pode comprar 2 por semana com Naleidea Rivergleam no Delver's HQ.|n• Cada personagem tem as próprias keys. Sua contagem está em |cffffffffProfundidades & Cofre|r; o Account snapshot mostra o resto.",

	CODEX_CUR_SHARDS_TITLE = "Coffer Key Shards",
	CODEX_CUR_SHARDS_BODY = "• 100 shards fazem uma Restored Coffer Key. Entrar numa profundeza junta os shards para você.|n• Eles vêm do mundo aberto: o jogo cita tesouros, missões de mundo e eventos ao ar livre, e os raros também dão shards.|n• Limite semanal de ganho de 600 — acompanhe 'Weekly: X / Y' na aba Delves. Isso dá umas seis keys por semana. O rank 10 do Delver's Journey faz toda fonte dar mais.",

	CODEX_CUR_UNDERCOIN_TITLE = "Undercoin",
	CODEX_CUR_UNDERCOIN_BODY = "• Moeda de profundezas. Cai dos baús no fim de uma profundeza — a maior quantidade vem das profundezas Bountiful em tiers mais altos.|n• Gaste com |cffffffffNaleidea Rivergleam|r no Delver's HQ em Silvermoon: cosméticos, decoração, brinquedos e o L00T RAID-R Mini. A partir do rank 6 do Delver's Journey ela também vende as suas 2 Restored Coffer Keys semanais por essa moeda.|n• A partir do rank 5 do Delver's Journey, |cffffffffZah'ran|r aparece no fim de uma profundeza de Tier 6 ou mais. Ele vende equipamento Campeão por Undercoin, e o estoque dele muda a cada run.",

	CODEX_CUR_MANA_TITLE = "Untainted Mana-Crystals",
	CODEX_CUR_MANA_BODY = "• Compra equipamento Hero com |cffffffffZah'ran|r, o vendedor que aparece no fim de uma profundeza de Tier 6 ou mais.|n• Só a partir do rank 9 do Delver's Journey: aí os Bountiful Coffers de Tier 11 podem trazê-los (ou um item Hero), e os Tiers 8-10 dão quantidades menores.|n• O Account snapshot pode mostrar os totais por personagem.",

	CODEX_CUR_ACCOLADES_TITLE = "Field Accolades",
	CODEX_CUR_ACCOLADES_BODY = "• Moeda compartilhada dos sistemas |cffffffffVoid & Rituals|r: você a ganha em Ritual Sites e Void Assaults.|n• Gaste no Bazaar em Luaprata: |cffffffffMaren Silverwing|r vende baús de equipamento (Temporada 2: equipamento Aventureiro por 200, equipamento Veterano por 500 aleatório ou 750 para um espaço que você escolher), |cffffffffTriam Dawnsetter|r vende cosméticos.|n• Contagem ao vivo na aba |cffffffffVoid & Rituals|r.",

	CODEX_CUR_DAWN_TITLE = "Crests",
	CODEX_CUR_DAWN_BODY = "• A moeda que você gasta para subir o equipamento um rank de cada vez: 20 crests por rank, e cada track aceita só o próprio crest. Não está ligada aos seus espaços de raide do Grande Cofre.|n• Os artesãos também os usam: os crests definem o nível de item de uma peça fabricada.|n• As contagens de crests ao vivo estão em |cffffffffBasics -> Crests|r (não nesta lista).|n• Até a semana de 20 de outubro há um limite. Ele conta quantos você ganhou nesta temporada, não quantos você tem — gastar crests não libera espaço. Ele sobe 100 a cada semana. A partir da semana de 20 de outubro o limite deixa de existir.|n• Não é o mesmo que keys de profundeza — veja aquele guia para saber em que gastá-las.",
	CODEX_TRACKS_TITLE = "Gear upgrade tracks",
	CODEX_TRACKS_BODY = "• O equipamento não tem apenas um nível de item — ele está em uma |cfffffffftrack|r. De baixo para cima: |cffffffffAdventurer|r (verde), |cffffffffVeteran|r, |cffffffffChampion|r, |cffffffffHero|r, |cffffffffMyth|r.|n• Um tooltip com |cffffffffHero 3/6|r significa: track Hero, rank 3 de 6. Cada rank que você compra adiciona nível de item.|n• A track define seu teto — o tooltip mostra a faixa de nível de item que ela alcança. Para passar disso você precisa de um drop de uma track superior.|n• Cada track tem sua própria cor de crest. Conteúdo mais difícil solta equipamento em uma track superior — é assim que você sobe.|n• Superou a track? Troque crests inferiores com |cffffffffVaskarn|r. Melhore com |cffffffffCuzolth|r em Luaprata — um rank custa os crests dessa track mais um pouco de ouro.|n• Cada track tem uma conquista por ultrapassá-la, com o nome do crest da temporada — na Season 2 a série «…of the Mist». Ela reduz pela metade o custo em crests dessa track para seus outros personagens e (de Adventurer a Hero) permite que este personagem troque esse crest por um nível acima com Vaskarn: 30 por 10 do nível seguinte.|n• Contagens ao vivo e pontos de rota: |cffffffffBasics -> Crests|r.",

	CODEX_DELVES_INTRO_TITLE = "Profundezas Midnight — visão geral",
	CODEX_DELVES_INTRO_BODY = "• Runs curtas e instanciadas para 1 a 5 jogadores, com a Valira como companheira — por Quel'Thalas e a Ilha Enrolada.|n• |cffffffffTiers 1–11|r. Do Tier 4 para cima você precisa do nível 90 e da campanha Midnight concluída uma vez na sua Warband; depois disso, concluir um tier abre o próximo.|n• O equipamento para de melhorar no |cffffffffTier 8|r: Bountiful Coffer 295, Grande Cofre 305 (Hero 1/6). O Tier 11 ainda paga crests melhores.|n• Entrar é grátis — não precisa de key. Uma profundeza |cffffffffBountiful|r (até quatro por dia) termina com um Bountiful Coffer, e esse baú precisa de uma |cffffffffRestored Coffer Key|r (veja Currencies).|n• Use 'Find Nearest Bountiful Delve' na aba Delves.",

	CODEX_DELVE_COACH_TITLE = "Delve Coach",
	CODEX_DELVE_COACH_BODY = "• Painel de dicas flutuante: rota, trash e mecânicas de chefe por profundeza.|n• Abre sozinho quando você entra em uma profundeza, ou via |cffffffffDelve Coach (preview tips)|r / |cffffffff/mh coach|r.|n• As dicas ficam no idioma do seu jogo; `/mh lang` alterna entre inglês e neerlandês.|n• Destaque do chefe: role no modelo para dar zoom (salvo por chefe).|n• Nomes de magias em azul levam às dicas reais de magia quando os IDs são conhecidos.",

	CODEX_DELVE_CURIOS_TITLE = "Valira & curios de profundeza",
	CODEX_DELVE_CURIOS_BODY = "• A Valira tem três espaços que você mesmo preenche: um |cffffffffPoison|r, um |cffffffffCombat Curio|r e um |cffffffffUtility Curio|r. A função dela (Tanque, Cura ou DPS) é uma escolha separada.|n• Troque-os nos suprimentos no início de uma profundeza e no checkpoint dela, onde você também repara.|n• A Série 2 tem seis venenos: três desde o início, e mais três depois das missões de introdução da Série 2 da Valira (Seasonal Refresher: Midnight, depois Slithering Spoils).|n• |cffffffff/mh curios|r mostra o que cada opção faz nas palavras do próprio jogo, com uma estrela no que a maioria dos guias escolhe. Um pequeno painel com essas escolhas abre ao lado da janela dela.|n• O popup de itens de profundeza acompanha RAID-R Mini e Trovehunter's Bounty.",

	CODEX_TORMENTS_TITLE = "Venomfall Deeps (profundeza Nêmesis)",
	CODEX_TORMENTS_BODY = "• A profundeza Nêmesis da Série 2, no norte da Ilha Enrolada: {WAY:2512:51.23:30.26:Venomfall Deeps}. O chefe é |cffffffffAzta'rec|r, na dificuldade |cffffffff?|r ou |cffffffff??|r.|n• Para desbloquear, conclua qualquer profundeza de Tier 7 com pelo menos uma vida sobrando (para ?), ou qualquer profundeza de Tier 10 com uma vida sobrando (para ??).|n• A entrada recomenda nível de item 290 para ? e 309 para ??.|n• Só nesta série: derrotá-lo dá a conquista My Venomous Nemesis (um transmog de costas); no ?? sem outros jogadores, Let Me Solo Him: Azta'rec (a montaria Apophic Soul Crusher).|n• Torment's Rise e Nullaeus foram o Nêmesis da Série 1.|n• O Delve Coach tem o plano da luta.",

	CODEX_DELVE_LOG_TITLE = "Delve Log",
	CODEX_DELVE_LOG_BODY = "• Um registro por personagem de cada profundeza de Midnight e de cada run de Ritual Site que você termina: tier, tempo e mortes — nas profundezas, também se você usou uma key, e o chefe final.|n• O registro é automático; a aba não precisa estar aberta.|n• Útil para ver qual tier você concluiu por último e quanto tempo levou.|n• Procurando uma entrada? |cffffffffFind Nearest Delve|r fica na aba |cffffffffProfundidades & Cofre|r.",

	CODEX_MPLUS_TITLE = "Mythic+ & cofre de masmorras",
	CODEX_MPLUS_BODY = "• O Mythic+ preenche a fileira |cffffffffDungeons|r do Grande Cofre (separada das fileiras de profundeza/mundo). Masmorras Heroicas, Mythic 0 e de Caminhada Temporal também contam ali, com uma recompensa menor.|n• Uma key mais alta dá um nível de item mais alto no cofre. No tempo ou não, toda key terminada conta. Nesta temporada isso para de subir no +10.|n• Suas três opções usam sua melhor, sua 4ª melhor e sua 8ª melhor key da semana.|n• O Vault Advisor tem pesos de atributo M+ separados só para curadores; tanques e DPS recebem os mesmos pesos para raide e para M+.|n• O Midnight Helper não substitui um addon de rota — use MDT / notas para semanas de afixo.",
	CODEX_MPLUS_START_TITLE = "M+, desde a sua primeira key",
	CODEX_MPLUS_START_BODY = "M+ é uma masmorra normal com uma |cffffcc00Keystone|r: uma key com um nível, como +2 ou +3. Keys mais altas são mais difíceis e dão saque melhor, e cada key que você termina conta para o seu |cffffcc00Grande Cofre|r.|n|n|cffffcc00Sua primeira key|r|n• Termine uma masmorra Mythic 0: o último chefe dá uma key para você.|n• Ou entre na key de outra pessoa: quando ela termina, você também ganha uma.|n• Perdeu a sua, ou nunca teve uma? |cffffffffLindormi|r em Silvermoon City, ao lado do portal para The Timeways, dá uma para você.|n• Você tem uma key por vez, e ela começa em +2.|n|n|cffffcc00Entrar em um grupo|r|n• Aperte |cffffffffI|r, abra |cffffffff{UI:GROUP_FINDER}|r, depois |cffffffff{UI:LFGLIST_NAME}|r e |cffffffffMasmorras|r. Masmorras míticas não têm fila.|n• Escolha uma key baixa, de +2 a +4. Grupos marcados com |cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r esperam jogadores novos.|n• Clique em |cffffffff{UI:SIGN_UP}|r, marque a sua função e espere o líder convidar você.|n|n|cffffcc00Criar o seu próprio grupo|r|n• No mesmo lugar: clique em |cffffffff{UI:START_A_GROUP}|r, escolha a masmorra da sua key, escolha um estilo de jogo (|cffffffff{UI:GROUP_FINDER_GENERAL_PLAYSTYLE1}|r serve) e clique em |cffffffff{UI:LIST_GROUP}|r.|n• Mude a dificuldade da masmorra para |cffffffffMítico|r antes de entrar.|n• Lá dentro, quem tem a key clica na |cffffffffFont of Power|r perto da entrada, coloca a key e aperta |cffffffff{UI:CHALLENGE_MODE_START_CHALLENGE}|r. Depois de uma contagem de 10 segundos, o tempo começa a correr.|n|n|cffffcc00Durante a run|r|n• De +2 a +5, morrer não custa tempo, e inimigos marcados mostram uma rota. A partir de +6, cada morte custa tempo.|n• A partir de +5, entra uma regra extra da semana. A aba |cffffffff{UI:CHALLENGES}|r no Localizador de Grupos mostra qual é.|n• No tempo: a sua key sobe de 1 a 3 níveis. Atrasado: você ainda ganha saque, mas a key cai 1 nível. Nos dois casos, ela muda para outra masmorra.|n• Precisa parar? Digite |cffffffff/abandon|r para abrir uma votação. Só sair pode marcar você como Keystone Deserter.|n• No fim, todo mundo abre o baú para pegar o próprio saque.|n|n|cffffcc00Ajuda|r|n• Diga no grupo: 'first time in this dungeon' (primeira vez nesta masmorra). Em keys baixas, a maioria dos jogadores gosta de explicar.|n• Pergunte na sua guilda, ou procure em |cffffffff{UI:COMMUNITIES_GUILD_FINDER}|r e |cffffffffEncontrar uma Comunidade|r na janela de Guilda e Comunidades (J).|n• A sua |cffffffff{UI:DUNGEON_SCORE}|r fica na aba {UI:CHALLENGES}. Muitos líderes também olham a pontuação do Raider.IO.|n|nO Midnight Helper ajuda lá dentro: dicas dos chefes abrem quando você entra, e |cffffffff/mh mplus|r mostra a sua melhor run por masmorra e onde uma key rende mais.",
	CODEX_AGGRO_TITLE = "Aggro: quem o inimigo está atacando?",
	CODEX_AGGRO_BODY = "Aggro significa que um inimigo está atacando você. O tank quer isso; um DPS ou healer que puxa o aggro muitas vezes morre. O jogo já pode avisar você, mas muitos jogadores estão com esses avisos desligados. O Midnight Helper não muda nenhum deles para você: digite |cffffffff/mh aggro|r para ver como os seus estão configurados.|n|n• |cffffffff{UI:NAMEPLATE_OPTIONS_LABEL} > {UI:UNIT_NAMEPLATES_THREAT_DISPLAY}|r: marque |cffffffff{UI:UNIT_NAMEPLATES_THREAT_DISPLAY_FLASH}|r. A placa de identificação de um inimigo pisca quando o tank o perde ou quando um DPS ou healer o puxa.|n• |cffffffff{UI:COMPACT_UNIT_FRAME_PROFILE_DISPLAYAGGROHIGHLIGHT}|r (quadros de raide): uma borda vermelha em volta de quem está com o aggro. Útil para healers.|n• |cffffffff{UI:ACCESSIBILITY_AUDIO_LABEL} > {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL} > {UI:CAA_SAY_IF_TARGETED_LABEL}|r: uma voz avisa quando um inimigo escolhe você como alvo. Ative primeiro {UI:CAA_COMBAT_AUDIO_ALERTS_LABEL}; esta opção é salva por especialização.|n|nUsa um addon de placas de identificação como o Plater? Então o piscar nas placas vem desse addon, não do jogo: veja nas configurações dele.",

	CODEX_RAID_VAULT_TITLE = "Raide — Grande Cofre",
	CODEX_RAID_VAULT_BODY = "• Chefes de raide preenchem a linha Raide do cofre: 2, 4 e 6 chefes abrem uma, duas e três opções. Toda dificuldade conta, o Localizador de Raides também, e o chefe do Lair também.|n• Na Temporada 2 cada opção vem de uma dificuldade acima daquela em que você matou os chefes: Localizador de Raides dá Champion, Normal dá Hero, Heroico dá Myth, Mítico dá Myth num nível mais alto.|n• Dificuldades misturadas: cada opção usa a dificuldade mais alta em que você chegou àquele número de chefes. A UI do cofre mostra o que você tem esta semana.|n• Crests são o que você gasta depois para melhorar o equipamento de raide.",

	CODEX_VAULT_ADVISOR_TITLE = "Conselheiro do Grande Cofre",
	CODEX_VAULT_ADVISOR_BODY = "• Painel lateral ao lado da janela do Grande Cofre da Blizzard quando você escolhe sua recompensa no Grande Cofre em Silvermoon — não dentro das abas do Midnight Helper. SHIFT-J só mostra um resumo, então o painel não aparece ali.|n• Classifica as peças do cofre contra o equipamento usado segundo as prioridades de atributo do guia (e Pawn opcional).|n• Ativável nas configurações rápidas do minimapa / Esc -> AddOns -> Midnight Helper.|n• Perfil Auto vs Raide vs M+ para os pesos de atributo.",

	CODEX_WORLD_HUB_TITLE = "Void & Rituals — um só sistema",
	CODEX_WORLD_HUB_BODY = "• Desde o patch 12.0.5, |cffffffffRitual Sites|r e |cffffffffVoid Assaults|r funcionam como um só sistema. Os dois mudam toda semana entre Eversong Woods e Zul'Aman, e compartilham uma moeda e um renome.|n• Mesmas |cffffffffField Accolades|r e hub do Bazaar — não as farme como atividades separadas.|n• A Série 2 reduziu o equipamento que você compra com Field Accolades para Aventureiro e Veterano: útil para um personagem novo, não para o equipamento de topo.|n• Abra a aba combinada para ver o site e a zona ativos desta semana, suas Field Accolades e seu renome, e os botões de rota.",

	CODEX_RITUAL_TITLE = "Ritual Sites",
	CODEX_RITUAL_BODY = "• Um ritual instanciado para 1 a 5 jogadores. A cada semana ele fica em um de dois lugares: Daggerspine Point em Eversong Woods ou o Broken Throne em Zul'Aman. Escolha um tier e conclua para ganhar accolades, renome e saque.|n• Só um site fica ativo por vez; o addon destaca qual.|n• O pin de Ritual Site no SMC City Guide traça uma rota até o site ativo desta semana. Se o addon ainda não souber qual é, o pin abre a aba Void & Rituals.",

	CODEX_VOID_TITLE = "Void Assaults",
	CODEX_VOID_BODY = "• O Caos ataca Eversong Woods ou Zul'Aman — um dos dois a cada semana. Faça Void Strikes; quando houver o suficiente, começa uma Void Incursion maior. Os dois dão Field Accolades.|n• Compartilha as Field Accolades e o renome de Ritual Sites com os Ritual Sites — você avança nos dois ao mesmo tempo.|n• A aba Void & Rituals mostra a zona desta semana, a da próxima semana e sua missão semanal.",

	CODEX_RARES_TITLE = "Rares Midnight",
	CODEX_RARES_BODY = "• Mobs raros semanais com saque de conta/personagem (confira as regras de cada raro no jogo).|n• Aba |cffffffffRares|r: acompanhe os kills e monte uma rota, com o raro mais próximo primeiro. A seta de rota (a do Midnight Helper, ou a do TomTom se você usa) passa depois para o próximo mais perto.|n• Alerta ao vivo quando um raro acompanhado está por perto (~500 yd) — ativável nas configurações.",

	CODEX_PROF_TITLE = "Profissões — ciclo semanal",
	CODEX_PROF_BODY = "• Cada profissão tem seus próprios |cffffffffpontos de conhecimento (KP)|r e sua própria |cffffffffMarra do Artífice|r: a Marra de Alquimia só compra coisas de Alquimia.|n• |cffffffffToda semana, por profissão:|r a missão semanal do seu instrutor em Silvermoon (a partir da perícia 25), as |cffffffffPatron orders|r na mesa de Crafting Orders que dão conhecimento (a maior fonte semanal), até dois itens de conhecimento de tesouros comuns nas zonas de Midnight, e um Thalassian Treatise (feito por Escrivania).|n• Coletores e Encantadores também ganham itens de conhecimento coletando ou desencantando. Esses recuperam uma semana perdida; a maioria das outras fontes semanais não.|n• |cffffffffAbundance|r é uma trilha separada: um Shard of Dundun (no máximo 8 por semana) inicia uma Abundant Harvest, e ela dá Unalloyed Abundance.|n• Aba |cffffffffProfissões|r: KP não gastos, seus Shards of Dundun e pinos no mapa para tesouros e livros. Onde gastar KP: o guia Basics.",

	CODEX_PROF_GUIDE_TITLE = "Profissões — guia para iniciantes",
	CODEX_PROF_GUIDE_BODY = "• Subaba |cffffffffBasics -> Profissões|r: plano de KP passo a passo e sugestões de combos.|n• A subaba |cffffffffCrests|r é sobre crests: a moeda que você usa para melhorar equipamento, ganha em muitas atividades — não só em raides.|n• Releia após patches — números e limites podem mudar.",
	CODEX_PROFRESET_TITLE = "Reiniciar as especializações de uma profissão (12.1)",
	CODEX_PROFRESET_BODY = "• O patch 12.1 permite desfazer as tuas escolhas de especialização Midnight — uma vez por profissão.|n• |cffffffffCom quem:|r Theremis, no Bazar de Luaprata junto às encomendas de profissão. Oferece uma linha por profissão, por isso podes reiniciar Ferraria e deixar Encantamento intacto.|n• |cffffffffO que recuperas:|r cada ponto de Conhecimento gasto nas árvores Midnight dessa profissão, livre para redistribuir.|n• |cffffffffO que custa:|r o aviso do jogo diz “You will lose all associated recipes”.|n• |cffffffffAssociadas, não todas.|r O que se perde é o que essas especializações tinham desbloqueado. As receitas de um treinador, de um despojo ou de uma missão estão fora das árvores e ficam. Visto num Encantamento reiniciado: a lista de receitas estava intacta e o Conhecimento gasto tinha voltado ao contador.|n• |cffffffffÉ uma só vez.|r A confirmação escreve ONCE em maiúsculas, e é por profissão — não há segunda tentativa se o novo caminho desiludir.|n• Decide |cffffffffantes|r de confirmar. A página de Profissões indica a árvore a preencher e o nó exato.|n• As receitas retiradas voltam se redistribuíres igual? O jogo nunca o diz. Conta que não.",
	CODEX_CORRPOWER_TITLE = "Corrosive Codex — qual gift pegar primeiro?",
	CODEX_CORRPOWER_BODY = "|cffffcc00Doze gifts, e você pode usar um.|r Cada um custa |cffffffff8 Corrosive Souls|r, então os doze juntos custam 96. Como o preço é o mesmo para todos, sua primeira escolha é sobre |cffffffffo que você precisa|r — nunca sobre o que dá para pagar.|n|n|cffffff78Uma coisa explica o sistema inteiro|r|n• É um |cffffffffciclo de veneno|r. Metade dos gifts fica mais forte contra um inimigo Poisoned, ou enquanto |cffffffffvocê mesmo|r está envenenado.|n• Por isso toda dupla boa é |cffffffffum gift que envenena + um gift que aproveita isso|r. Depois que você enxerga isso, as combinações deixam de parecer aleatórias.|n|n|cffffff78Qual primeiro? Escolha pelo seu problema, não por uma lista|r|n• |cffffffffSó quero bater mais forte|r → |cffffffffUla'tek's Gift|r. Funciona sozinho, sem um segundo gift e sem preparo. Todos os guias que lemos citam esse primeiro.|n• |cffffffffGrupos de inimigos demoram demais|r → |cffffffffPlague of Corrosion|r ou |cffffffffOphidian Maw|r.|n• |cffffffffEu morro direto nos delves|r → |cffffffffVirulent Mucus|r absorve os golpes grandes, |cffffffffGorgoneion Gaze|r petrifica tudo ao seu redor assim que você cai abaixo da metade da vida.|n• |cffffffffConjuradores conseguem terminar a magia|r → |cffffffffAccursed Poison|r. Ele interrompe uma para você.|n|n|cffffcc00Cuidado com Mephitic Cloud.|r Ele deixa os |cffffffffinimigos|r afetados curarem o que estão atacando. Em grupo isso joga contra você.|n|n|cffffff78O que medimos nós mesmos e o que não|r|n• |cffffffffDo jogo:|r o preço de 8 e o texto completo de Ula'tek's Gift. Esses são nossos.|n• |cffffffffDe guias:|r a ordem acima e quantos gifts abrem o segundo espaço. O jogo só diz \"until your offerings are sufficient\" e não dá número nenhum. |cffffffffSeis fontes dizem 8|r — incluindo a própria página de magia do Wowhead, que coloca isso numa tabela — e um blog diz 6. Então 8 é quase certo; só não vimos acontecer com os nossos olhos. Você vai saber no momento em que o seu segundo espaço aparecer.|n• Ula'tek's Gift já |cfffffffffoi enfraquecido uma vez|r. Um ranking de agosto não é automaticamente verdade hoje — e é justamente por isso que o ciclo de veneno acima é a parte que vale lembrar.",
	CODEX_ATALUTEK_TITLE = "As Vaults of Atal'Utek — o que há lá dentro e onde",
	CODEX_ATALUTEK_BODY = "|cff8fd3ffPara começar|r|n|n• |cffffffffO que é:|r uma área da 12.1 na Coiled Isle com mapa próprio, e por baixo um segundo mapa, a Underbelly. Já está aberta — não há trava de série.|n|n• |cffffffffComo entrar:|r uma cadeia de quatro missões — |cffffffffInto the Vaults of Atal'Utek|r, depois |cffffffffVaults of Atal'Utek: One Coin Too Many|r e |cffffffffVaults of Atal'Utek: A Toxic Tour|r, que você recebe ao mesmo tempo, depois |cffffffffVaults of Atal'Utek: The Altar of Corrosion|r. Todo o resto está atrás delas, então faça essas primeiro. |cffffffffA Toxic Tour é uma missão de história única, não uma diária|r — ela pede uma Patrol, um Strike, uma Incursion e um Ancient Foe, então se completa sozinha enquanto você faz o ciclo descrito abaixo.|n|n|cff8fd3ffO que se faz aqui|r|n|n• |cffffffffO que você faz de verdade aqui — quatro coisas, e elas se alimentam.|r As |cffffffffTemple Patrols|r percorrem o mapa e trocam mais ou menos a cada dez minutos; são o mais fácil de acompanhar e quase sempre tem uma rolando. As |cffffffffTemple Strikes|r são maiores e preparam uma incursão. Com Strikes suficientes começa uma |cffffffffTemple Incursion|r, e toda Incursion termina despertando um |cffffffffAncient Foe|r — é daí que vêm os três elites raros: só um deles por semana, com dez minutos no relógio. Moedas, chaves, equipamento e reputação saem todos desse ciclo. Se você está na dúvida sobre o que fazer: entre no que estiver rolando.|n|n• |cffffffffComo eu acho um Temple Strike, afinal?|r Abra o mapa dentro das Vaults e procure os ícones de evento — um Strike aparece lá como qualquer evento de zona, e |cffffffffnão tem cronômetro|r: ele fica esperando até um grupo terminá-lo, então você pode ir andando com calma. |cffffffffAlguns poucos jogadores bastam|r; você não precisa de grupo montado, e normalmente já tem gente lá. São seis, cada um com um ponto de partida fixo — clique em um para marcar um waypoint: {WAY:2509:50.55:15.70:Cursed Depths} · {WAY:2509:47.36:46.17:Overflowing Venom} · {WAY:2509:47.67:46.34:Profane Pyres} · {WAY:2509:47.26:26.69:Purifying Earth and Sky} · {WAY:2509:39.32:39.92:Ruuk’Jar’s Clutch} · {WAY:2613:52.25:36.27:The Underbelly}.|nSe o mapa não mostrar nenhum Strike, provavelmente há uma Incursion ou o Ancient Foe dela rolando agora — entre nisso. Um Strike novo aparece assim que acabar.|n|n• |cffffffffComo se deslocar lá dentro.|r Os |cffffffffAmani Windcallers|r levam você entre três pontos das Vaults — o centro |cffffffffAmani Foothold|r, o Eastern Amani Outpost e o Northern Amani Bulwark. O mestre de voo |cffffffffEagletender Mal’Tiki|r fica em {WAY:2509:44.42:62.21:Amani Foothold}. Não dá para voar dentro das Vaults, e é exatamente por isso que eles existem — o lugar é maior do que parece, e andar a pé é o jeito lento.|n|n• |cffffffffAs missões repetíveis — uma semanal e oito diárias.|r |cffffffffPurging the Vaults|r com o |cffffffffWarleader Abdumati|r no Amani Foothold é a semanal que não vale a pena perder. As oito diárias são |cffffffffPatrolling the Temple|r, |cffffffffBounty of the Cursed|r, |cffffffffRelentless Strikes|r, |cffffffffDecisive Incursions|r, |cffffffffFrom Whence it Came|r, |cffffffffEssence of Malice|r, |cffffffffWhat's Out There?|r e |cffffffffShoulder to Shoulder|r — pegue as que o mapa oferecer hoje. A maioria pede as atividades acima, então elas se completam sozinhas enquanto você joga. Duas querem que você esteja em grupo (What's Out There? e Shoulder to Shoulder): as pessoas que já estão ao seu lado bastam, não precisa de premade. E uma que você nunca encontraria estando aqui: |cffffffffMidnight: Vaults of Atal'Utek|r é uma meta semanal deste lugar que você pega em |cffffffffSilvermoon|r.|n|n|cff8fd3ffCoin and Soul|r|n|n• |cffffffffCorrosive Coin|r é a moeda da zona. Nas palavras do próprio jogo: “Spirits of the Amani within the Vaults of Atal'Utek deal exclusively in this phantasmal token.” O seu saldo é o número acima deste artigo.|n|n• |cffffffffCorrosive Soul não é isso.|r Não é moeda nenhuma, mas um |cffffffffitem|r nas suas bolsas, e é o que o Corrosive Codex pede que você ofereça. Os guias trocam os dois nomes o tempo todo; o jogo nunca. Se algo disser para você gastar Corrosive Coins no Codex, é essa a confusão.|n|n• |cffffffffPara onde vão as moedas — dois lugares, ambos com Er’inye|r em {WAY:2509:51.10:62.76:Er'inye}. Falar com ela compra |cffffffffCorrode Spirit|r, que alimenta a árvore do altar; ao lado dela, a |cffffffffSkull of Er’inye|r é um mercador com três páginas de montarias, mascotes, conjuntos e receitas, de 500 a 25.000 moedas. |cffffffffO preço do corrode sobe a cada compra|r — visto a 1.500 e depois 2.000 numa visita — então leia a janela em vez de juntar para um valor.",
	CODEX_ATALUTEK_DISC_TITLE = "Altar of Corrosion: as quatro chaves",
	CODEX_ATALUTEK_DISC_BODY = "• |cffffffffO Altar of Corrosion|r é a árvore de nós que a última missão da cadeia abre. A maior parte abre conforme você gasta, mas |cffffffffquatro nós ficam atrás de uma chave que você precisa ir buscar|r — e os quatro funcionam do mesmo jeito: cai um item, você o usa num objeto fixo em algum lugar das Vaults, isso dá um item de missão, e Er’inye cuida do resto.|n|cffffffffCorroded Key|r → o Venom-Worn Coffer → |cffffffffRun of the Vaults|r (Glideways, ou Swift Steps) · |cffffffffSpirit Loupe|r → a Feather of Tok’jara em {WAY:2509:48.46:25.80:Feather of Tok'jara} → |cffffffffSpectral Winds|r (Spirit Walk, ou Spectral Shipping) · |cffffffffExcising Knife|r → o Eye of Szarith, numa poça de veneno na Underbelly → |cffffffffBroodmaster|r (+100% de dano aos ovos, ou −75% de dano das explosões de ovos) · |cffffffffDispelling Charm|r → Jin’tal’s Reliquary no Profaned Mausoleum → |cffffffffSpiritual Protection|r (aliados espectrais nos Curse Surges, ou levantar na hora se você morrer fora das Vaults).|n|cffffffffMostrar uma chave para Er’inye não desbloqueia nada.|r Ela é cega e diz o que sente — isso é uma pista de onde o objeto pertence. |cffffffffDe onde vêm as chaves|r — os guias agora concordam: a Corroded Key vem dos Temple Strikes, a Excising Knife de uma Temple Incursion, a Spirit Loupe de um Ancient Foe. O |cffffffffDispelling Charm|r é a exceção: não vem dos eventos, mas de Jin’tal na Vault of Restless Bones, durante uma linha de missões secundária sobre os Med’jai.|n|n• |cffffffffGaste suas primeiras moedas na árvore logo de cara.|r Os quatro primeiros nós não custam nada e abrem conforme você gasta em outro lugar, e aumentam a Corrosive Coin que você ganha em |cffffffff25, 50, 75 e por fim 100 por cento|r. A árvore se paga sozinha, então cada volta depois da primeira rende mais — juntar é a escolha cara. E repare na assimetria que define o ritmo da zona: |cffffffffmoedas não têm limite|r, as Corrosive Souls têm. Farme moedas à vontade; não planeje uma noite em torno das souls.",
	CODEX_ATALUTEK_DEAD_TITLE = "The Honored Dead e os raros",
	CODEX_ATALUTEK_DEAD_BODY = "• |cffffffff“The Honored Dead” — doze memoriais|r no mapa das Vaults, uma conquista, e a coisa mais clara para você ir fazer aqui. Numa só ordem de percurso, do topo do mapa para baixo:|n{WAY:2509:46.79:7.51:To a sister 46.79, 7.51} · {WAY:2509:56.49:22.88:To a shield-bearer 56.49, 22.88} · {WAY:2509:47.22:28.77:To a father 47.22, 28.77} · {WAY:2509:42.57:33.18:To a stranger 42.57, 33.18} (debaixo da ponte) · {WAY:2509:52.91:33.90:To a captain 52.91, 33.90} · {WAY:2509:55.62:40.60:To a dream 55.62, 40.60} · {WAY:2509:42.84:39.93:To sons 42.84, 39.93} · {WAY:2509:52.21:45.12:To a lover 52.21, 45.12} · {WAY:2509:38.50:47.66:To Comrades 38.50, 47.66} · {WAY:2509:55.31:48.45:To parents 55.31, 48.45} · {WAY:2509:49.50:56.59:To a daughter 49.50, 56.59} · {WAY:2509:45.81:61.79:To Failure 45.81, 61.79}|n|n• |cffffffffA Underbelly|r é o mapa de baixo, com entrada em {WAY:2509:47.30:11.20:The Underbelly} no mapa das Vaults. Lá embaixo vive um raro, |cffffffffSzarith the Fanged|r em {WAY:2613:38.40:17.69:Szarith the Fanged}, e a Underbelly tem uma conquista própria: |cffffffffSoft Underbelly|r. |cffffffffSó o Szarith não basta:|r segundo os guias, a conquista também pede vários elites com nome que só aparecem enquanto o Temple Strike |cffffffffThe Underbelly|r está rolando.|n|n• |cffffffffTrês elites raros no mapa principal|r — Congealed Malice, Khu'tulak e Susarikk — formam uma terceira: |cffffffffOppose the Foes|r. |cffffffffEles não têm um lugar fixo, e essa é a resposta, não uma falha|r: um dos três desperta no momento em que uma |cffffffffTemple Incursion|r é concluída, e você tem cerca de dez minutos para matá-lo. |cffffffffSó um dos três está na rotação a cada semana|r, então essa conquista leva pelo menos três semanas. Você não sai caçando eles — você termina Incursions, e o da semana vem até você.",
})
